       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"5847c353-1eed-58ab-b5f9-2df3392c24dc","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تهريب مخدرات -تعاطي احلشيش -تعاطي احلبوب احملظورة -قيادة السيارة حتت تأثير تعاطي احلشيش -أسباب تخفيف العقوبة -تداخل العقوبات -إقامة حد املسكر -التعزير بالسجن واجللد واالبعاد.","document_number":"3459890","case_number":"3429446","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/10","year":"1434","subject":"مخدرات -تهريب مخدرات -تعاطي احلشيش -تعاطي احلبوب احملظورة -قيادة السيارة حتت تأثير تعاطي احلشيش -أسباب تخفيف العقوبة -تداخل العقوبات -إقامة حد املسكر -التعزير بالسجن واجللد واالبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 3459890 :‬تاريخه ‪1434/03/10 :‬هـ‬\n                          ‫رقم الدعوى‪3429446 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34257062‬تاريخه‪1434/7/2 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬تهريــب مخــدرات ‪ -‬تعاطــي احلشــيش ‪ -‬تعاطــي احلبــوب‬\n      ‫احملظــورة ‪ -‬قيــادة الســيارة حتــت تأثيــر تعاطــي احلشــيش ‪ -‬أســباب‬\n      ‫تخفيــف العقوبــة ‪ -‬تداخــل العقوبــات ‪ -‬إقامــة حــد املســكر ‪ -‬التعزيــر‬\n                                                     ‫بالســجن واجللــد واالبعــاد‪.‬‬\n\n\n\n\n               ‫احل ِّق }‪.‬‬           ‫‪ -1‬قوله تعالى { َو َال َت ْق ُت ُلو ْا ال َّن ْف َس ا َّلتِي َح َّر َم ّ ُ‬\n                      ‫الل ِإ َّال ِب َ‬\n                       ‫ال ِح َها }‪.‬‬‫‪ -2‬قوله تعالى { َو َال ُت ْف ِس ُدو ْا ِف األرض َب ْع َد ِإ ْص َ‬\n                                               ‫‪ -3‬املادة (‪ )41‬من نظام مكافحة املخدرات ‪.‬‬\n                                              ‫‪ -4‬املادة (‪ )60‬من نظام مكافحة املخدرات ‪.‬‬\n               ‫‪ -5‬الفقرة الثانية من املادة (‪ )56‬من نظام مكافحة املخدرات ‪.‬‬\n\n\n\n\n      ‫توجيــه االتهــام لزائــر خليجــي بتهريــب لفافــة تبــغ مخلوطــة باحلشــيش‬\n      ‫لقصــد االســتعمال بتعاطيــه للحشــيش املخــدر وتعاطيــه حلبــوب‬\n      ‫االمفيتامــن وقيادتــه للســيارة حتــت تأثيــر احلشــيش ‪ ،‬مت تفتيــش‬\n      ‫ســيارته التــي يقودهــا مــن قبــل إحــدى املنافــذ البريــة اجلمركيــة‬\n      ‫وعثــر بداخلهــا علــى لفافــة تبــغ ملفوفــة باحلشــيش ‪ ،‬كمــا أثبــت‬\n      ‫تقريــر الســموم الشــرعية إيجابيــة العينــة املأخــوذة مــن ســوائل املدعــى‬\n‫‪75‬‬\n\f‫عليــه ملــادة احلشــيش ومركــب االمفيتامــن احملظــور ‪ ،‬طلــب املدعــى‬\n‫العــام إثبــات مــا أســند إليــه واحلكــم عليــه بالعقوبــة الــواردة يف نظــام‬\n‫مكافحــة املخــدرات وإبعــاده عــن البــاد بعــد تنفيــذ محكوميتــه‪ ،‬أقــر‬\n‫املدعــى عليــه مبــا نســب إليــه‪ ،‬صــدر احلكــم بإثبــات إدانــة املدعــى عليــه‬\n‫مبــا نســب إليــه وإقامــة حــد املســكر ودخــول عقوبــة تعاطــي حبــوب‬\n‫االمفيتامــن يف حــد املســكر‪ ،‬التعزيــر بالســجن واإلبعــاد‪ ،‬إثبــات‬\n‫قيــادة املدعــى عليــه للســيارة حتــت تأثيــر املســكر والعقوبــة يف ذلــك‬\n          ‫للجهــة املختصــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫ـدي أنــا‬\n      ‫احلمــدهلل وحــده والصــاة والســام علــى َمــنْ النبــي بعــده وبعــد فلـ َّ‬\n‫ـاء علــى املعاملــة الــواردة‬\n                            ‫‪ ...‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫إلينــا مــن دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء برقــم ‪778‬‬\n‫وتاريخ‪1434/01/17‬ه ـ واملقيــدة بهــذه احملكمــة برقــم ‪34142468‬‬\n‫وتاريــخ ‪1434/01/18‬ه ـ واحملالــة إلينــا مــن فضيلــة الرئيــس برقــم‬\n‫‪ 3429446‬وتاريــخ ‪1434/01/18‬ه ـ فتحــت اجللســة وفيها حضر املدعي‬\n‫العــام ‪ ...‬امل ـ ُ َـع ّمد بالترافــع أمــام احملكمــة طرفنــا مبوجــب خطاب ســعادة‬\n‫رئيــس دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء ذي الرقــم‬\n‫ا ‪ :‬بصفتــي مدعي ًا‬  ‫‪ 13415‬والتاريــخ ‪1433/12/01‬ه ـ وقـ ّـرر دعــواه قائـ ً‬\n‫عامـ ًا بدائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي ‪ ،....:‬البالــغ مــن‬\n‫العمر(‪)36‬عامــا قطــري اجلنســية مبوجــب البطاقــة رقــم (‪ )....‬متســبب ‪،‬‬\n‫غيــر محصــن‪ ،‬قبــض عليــه بتاريــخ ‪1433/11/2‬ه ـ مفــرج عنــه مبوجــب‬\n‫أمــر اإلفــراج الصــادر مــن دائــرة التحقيــق واالدعــاء العــام باألحســاء رقــم‬\n\n                                                                                       ‫‪76‬‬\n\f     ‫(ه ـ ق‪ )213635/2‬وتاريــخ ‪1433/12/6‬ه ـ انــه بتاريــخ ‪1433/11/2‬ه ـ‬\n     ‫مت تفتيــش ســيارة مــن قبــل منفــذ ســلوى مــن نــوع ‪ ....‬موديــل ‪2008‬م‬\n     ‫وحتمــل اللوحــة رقــم (‪ )....‬والتــي يقودهــا املدعــى عليــه املذكــور وعثــر‬\n     ‫بداخلهــا علــى لفافــة تبــغ ملفوفــة يشــتبه انهــا مخلوطــة باحلشــيش املخــدر‬\n     ‫وبلــغ وزنهــا (‪ )1,68‬جــرام وثمانيــة وســتون مــن املائــة مــن اجلــرام‪ .‬وقــد‬\n     ‫اثبــت تقريــر الكيمــاوي الشــرعي رقــم (‪ 3942‬ك ش) لعــام ‪1433‬ه ـ‬\n     ‫احتــواء العينــة املرســلة ملــادة احلشــيش املخــدر واملدرجــة مــن ضمــن‬\n     ‫املــواد احملظــورة يف اجلــدول (‪ )1‬فئــة (أ) مــن نظــام مكافحــة املخــدرات‬\n     ‫واملؤثــرات العقليــة كمــا اثبــت تقريــر الســموم الشــرعية رقــم (‪1484‬‬\n     ‫م أ) لعــام ‪1433‬ه ـ ايجابيــة العينــة املأخــوذة مــن ســوائل املدعــى عليــه‬\n     ‫ملــادة احلشــيش املخــدر و ملركــب امفيتامينــي محظــور وباســتجواب‬\n     ‫املدعــى عليــه ‪ /‬اقــر بصحــة واقعــة القبــض والضبــط وعائديــه الســيارة‬\n     ‫لــه وقــد أســفر التحقيــق عــن توجيــه االتهــام لــه بتهريــب لفافــة تبــغ‬\n     ‫مخلوطــة باحلشــيش املخــدر البالــغ وزنهــا (‪ 1,68‬جــم ) جــرام وثمانيــة‬\n     ‫وســتون مــن املائــة مــن اجلــرام إلــى داخــل البــاد بقصــد التعاطــي وتعاطيــه‬\n     ‫لنوعــه وتعاطــي االمفيتامــن احملظــور وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n     ‫‪ -1-‬ماجــاء بأقوالــه املدونــة علــى الصفحــة رقــم (‪ )1‬مــن ملــف التحقيــق‬\n     ‫املرفــق علــى اللفــة رقــم (‪ -2.)11‬مــا جــاء مبحضــر القبــض املنــوه عنــه‬\n                                                       ‫واملرفــق علــى اللفــة رقــم (‪.)4‬‬\n     ‫‪-3‬مــا أثبتــه التقريــر الكيمــاوي الشــرعي املنــوه عنــه واملرفــق برقــم‬\n                                                                                  ‫(‪.)20‬‬\n     ‫‪-4‬مــا أثبتــه التقريــر الســموم الشــرعية املنــوه عنــه واملرفــق علــى اللفــة‬\n     ‫رقــم (‪.)23‬وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق‬\n\n\n‫‪77‬‬\n\f                                                                            ‫مســجلة ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا يف ضــوء الفقــرة الثانيــة مــن‬\n‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n‫باملرســوم امللكــي الكــرمي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ اطلــب‬\n                                ‫إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪-:‬‬\n‫‪ -1‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة لقــاء مــا اســند إليه مــن اتهام‪-2.‬‬\n‫إبعــاده خــارج البــاد بعــد تنفيــذ حكوميتــه اســتناد ًا للفقــرة الثانيــة مــن‬\n‫املــادة (‪ )56‬مــن ذات النظــام هكــذا ا َّدعــى ؛ عليــه فقــد حضــر املدعــى‬\n‫عليــه وبعــد التأكــد مــن هويتــه جــرى عــرض دعــوى املدعــي العــام عليــه‬\n‫فأجــاب قائ ـاً‪ :‬صحيــح مــا نســبه لــي املدعــي العــام مــن واقعــة القبــض‬\n‫ومــن تهريبــي للفافــة تبــغ مخلــوط تبغهــا باحلشــيش البالــغ وزنهــا (‪)1,68‬‬\n‫جــرام وثمانيــة وســتون مــن املائــة مــن اجلــرام بقصــد التعاطــي وصحيــح‬\n‫اعتــرايف واســتعمالي للحشــيش املخــدر واحلبــوب احملظــورة وقيادتــي‬\n‫للســيارة حتــت تأثيرهمــا وأنــا نــادم علــى مابــدر منــي وتائــب إلــى اهلل‬\n‫هكــذا أجــاب هــذا وقــد جــرى االطــاع علــى التقريــر الكيمــاوي‬\n‫الشــرعي الصــادر مــن قســم الكيميــاء الشــرعية باملركــز اإلقليمــي‬\n‫ملراقبــة الســموم التابــع للمديريــة العامــة للشــؤون الصحيــة باملنطقــة‬\n‫الشــرقية برقــم ( ‪ 1742‬ك ش ) لعــام ‪1433‬ه ـ املتضمــن إيجابيــة عي ــنة‬\n‫مــا ضبــط للحشــيش املخــدر كمــا جــرى االطــاع علــى كــرت ســوابق‬\n‫املدعــى عليــه املتضمــن خلــوه مــن الســوابق فبناء على مــا ورد من الدعوى‬\n‫واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه والتأكــد مــن أهليتــه وملــا‬\n\n\n                                                                                           ‫‪78‬‬\n\f     ‫ورد يف محضــر القبــض واعتــراف املدعــي عليــه ومبــا أنــه صــادق علــى‬\n     ‫صحــة مــا نســب إليــه مــن تهريــب احلشــيش املخــدر علــى صفــة مــا ورد‬\n     ‫يف الدعــوى ومبــا أن مــا صــدر منــه حــرام يف الشــريعة ملــا يف احلشــيش‬\n     ‫املخــدر احلبــوب احملظــورة مــن اخلطــر و الضــرر علــى البــاد والعبــاد‬\n     ‫وعلــى مــن صــدر منــه ذلــك قــال تعالــى (وال تقتلــوا النفــس التــي حــرم‬\n     ‫اهلل إال باحلــق) وقــال (وال تفســدوا يف األرض بعــد إصالحهــا ) ممــا‬\n     ‫يســتوجب معاقبــة املدعــى عليــه و تعزيــزه بالعقوبــة الــواردة يف املــادة‬\n     ‫الواحــدة واألربعــن مــن نظــام مكافحــة املخــدرات ويتوجــه أن يكــون‬\n     ‫أقــل عقوبــة ملــا ظهــر مــن حالــه مــن النــدم وألنــه ال ســوابق لــه ولقلــة‬\n     ‫الكميــة التــي وجــدت بحيازتــه كمــا يتوجــه تخفيــف تلــك العقوبــة‬\n     ‫أيضــا حســب مقتضــى املــادة الســتني مــن النظــام نفســه ملــا ظهــر مــن‬\n     ‫حالــه مــن النــدم ولظروفــه االجتماعيــة التــي اقتنعــت بهــا احملكمــة ـ‬\n     ‫وألنــه ال ســوابق لــه كمــا يتوجــه اســتحقاقه للعقوبــة الــواردة يف املــادة‬\n     ‫أن املدعــى عليــه أقـ َّـر‬  ‫السادســة واخلمســن الفقــرة الثانيــة منهــا ومبــا َّ‬\n     ‫باســتعمال احلشــيش املخــدر واســتعماله يأخــذ حكــم املســكر للتوافــق‬\n     ‫بينهمــا يف منــاط احلكــم وحــد املســكر أن يجلــد صاحبــه ثمانــن جلــدة‬\n     ‫علنــا كمــا اســتقر عليــه عمــل األمــة ممــا يتوجــب حــد املدعــى عليــه حــد‬\n     ‫املســكر الســتعماله للحشــيش املخــدر واالكتفــاء عــن مجازاتــه عــن‬\n     ‫اســتعمال احلبــوب لدخــول األصغــر يف حكــم األكبــر لــذا كلــه وألجــل‬\n     ‫ـدي إدانــة‬‫احلــق العــام حكمــت علــى املدعــى عليــه باآلتــي ‪ :‬أو ًال ‪ /‬ثبــت لـ َّ‬\n     ‫املدعــى عليــه باســتعمال احلشــيش املخــدر ويجلــد حــد املســكر ثمانــن‬\n     ‫ـدي إدانتــه باســتعمال احلبــوب‬       ‫جلــدة دفعــة واحــدة علن ـ ًا كمــا ثبــت لـ َّ‬\n     ‫احملظــورة وعقوبتــه داخلــة يف حـ ِّـد املســكر ثاني ـ ًا ‪ /‬ثبــت لــدي إدانــة‬\n\n\n‫‪79‬‬\n\f‫املدعــى عليــه بتهريــب لفافــة تبــغ مخلــوط تبغهــا باحلشــيش البالــغ وزنهــا‬\n‫(‪ )1,68‬جــرام وثمانيــة وســتون مــن املائــة مــن اجلــرام بقصــد التعاطي وأن‬\n‫يعــزر بســجنه شــهرين حتتســب منهــا املــدة التــي أوقــف فيهــا علــي ذمــة‬\n‫القضيــة وذلــك مبوجــب املــادة الواحــدة و األربعــن مــن نظــام مكافحــة‬\n‫املخــدرات واملــادة الســتني ‪ .‬ثالث ـ ًا ‪ /‬وأن يبعــد عــن اململكــة بعــد تنفيــذ‬\n‫العقوبــة احملكــوم بهــا عليــه واســتيفاء مــا لــه ومــا عليــه مــن حقــوق وال‬\n‫يســمح لــه بالعــودة إليهــا فيمــا عــدا مــا تســمح بــه تعليمــات احلــج والعمــرة‬\n‫حســب مقتضــى مــا ورد يف املــادة السادســة واخلمســن مــن النظــام‬\n‫نفســه الفقــرة الثانيــة وبتــاوة احلكــم علــى الطرفــن وإفهــام املدعــى‬\n‫عليــه بحقــه يف التمييــز قــرر قناعتــه باحلكــم وطلــب املدعــي العــام‬\n‫رفــع احلكــم للتمييــز وأن الئحتــه االعتراضيــة هــي الئحــة الدعــوى‬\n‫هــذا وجــرى توجيــه املدعــى عليــه مبــا يلــزم ومــن ذلــك حرمــة اســتعمال‬\n‫احلشــيش املخــدر و احلبــوب احملظــورة وأثــره الســيئ علــى العقــل واملــال‬\n‫وأقفلــت اجللســة الســاعة العاشــرة والنصــف وصلــى اهلل وســلم علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه أجمعــن حــرر احلكــم يف ‪1434/03/09‬ه ـ ‪.‬‬\n‫احلمــدهلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد‬\n‫ففــي يــوم األحد‪1434/06/04‬ه ـ فتحــت اجللســة الثانيــة الســاعة‬\n‫الثانيــة عشــرة وفيهــا حضــر الطرفــان وقــد عــادت املعاملــة املتعلقــة‬\n‫بالدعــوى العامــة ضــد ‪....‬مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n‫مبوجــب خطــاب فضيلــة رئيســها ذي الرقــم‪ 34/736056‬وتاريــخ‬\n‫‪1434/05/14‬ه ـ وبرفقهــا قــرار الدائــرة اجلزائيــة الثالثيــة األولــى(ج‪)1/‬‬\n‫رقم‪34209243‬وتاريخ‪1434/05/08‬ه ـ املتضمــن مــا نصــه‪« :‬وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ أن املدعــى عليــه أقـ َّـر‬\n\n\n                                                                                         ‫‪80‬‬\n\f     ‫بقيادتــه الســيارة حتــت تأثيــر اســتعماله املخــدر واحلبــوب احملظــورة ولــم‬\n     ‫جنــد أن فضيلــة ناظــر القضيــة أجــرى الــازم حيــال ذلــك ملالحظــة ذلــك‬\n     ‫وإكمــال الــازم ومــن ثــم إعــادة املعاملــة واهلل املوفــق « ا‪.‬ه ـ عليــه أجيــب‬\n     ‫ـأن ماذكــروه صحيــح وقــد وقــع ذلك مني‬          ‫مشــايخي نفعنــي اهلل بعلمهــم بـ َّ‬\n     ‫أن املدعــى عليــه أقـ َّـر بقيــادة الســيارة‬\n                                                  ‫ـهوا واهلل املســتعان وعليــه ومبــا َّ‬\n                                                                                        ‫سـ ً‬\n     ‫حتــت تأثيــر احلشــيش املخــدر وحتــت تأثيــر احلبــوب احملظــورة وإثبــات‬\n     ‫إدانتــه بذلــك لــدى هــذه احملكمــة والعقوبــة لــدى ولــي األمــر حســب‬\n     ‫األنظمــة املرعيــة التتــي ال تتعــارض مــع املصالــح الشــرعية لــذا فقــد ثبــت‬\n     ‫ـدي إدانــة املدعــى عليــه بقيــادة الســيارة حتــت تأثيــر املخــدرات واحلبــوب‬   ‫لـ َّ‬\n     ‫ـأن عقوبتــه عائــدة لولــي األمــر وبعرضــه عليهمــا‬        ‫احملظــورة وأفهمتــه بـ َّ‬\n     ‫ـرت بالتهميــش علــى قــرار احلكــم مبــا طــرأ عليــه ومــن ثـ ّـم‬     ‫قنــع بــه وأمـ ُ‬\n     ‫إعــادة املعاملــة حملكمــة االســتئناف باملنطقــة الشــرقية لتدقيــق احلكــم‬\n     ‫وأقفلت اجللســة الســاعة الثانية عشــرة والنصف ظهر ًا وصلى اهلل وســلم‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ُحـ ِـر َر يف‪1434/06/04‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n     ‫برقــم ‪ 34/736056‬وتاريــخ ‪1434/6/14‬ه ـ املقيــدة لــدى احملكمــة‬\n     ‫برقــم ‪ 341509167‬وتاريــخ ‪1434/6/21‬ه ـ املرفــق بهــا القــرار الصــادر‬\n     ‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪....‬برقــم ‪ 3459890‬وتاريــخ‬\n     ‫‪1434/3/10‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضد‪..../‬قطــري اجلنســية‬\n     ‫يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n     ‫ومفصــل فيــه ‪ .‬حيــث ســبق دراســة القــرار وصــورة ضبطــه وباإلطــاع‬\n\n\n‫‪81‬‬\n\f‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء‬\n‫علــى قرارنــا رقــم‪ 34209243‬يف ‪1434/5/8‬ه ـ قررنــا املصادقــة علــى‬\n‫احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                              ‫وآلــه وصحبــه وســلم حــرر يف ‪1434/7/2‬هــ‪.‬‬\n\n\n\n\n                                                                                   ‫‪82‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":75,"source_page_end":82,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"56138d2c5c750323c236d107daddfb6b78d710a45f144e0c23166120bf11b837","normalized_text_hash":"1308407590640b51936a3ab76e59b363ac2575eeb9e091823d9968edc81c1ae6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p75-3459890"},{"id":"ea2b7595-5f5f-5890-bc65-63624376abaf","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تهريب بقصد االجتار -قات -التعزير بالسجن واجللد والغرامة واإلبعاد.","document_number":"33475491","case_number":"33644973","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/21","year":"1434","subject":"مخدرات -تهريب بقصد االجتار -قات -التعزير بالسجن واجللد والغرامة واإلبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 33475491:‬تاريخه‪1433/12/21:‬هـ‬\n                       ‫رقم الدعوى‪33644973 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3416010‬تاريخه‪1434/1/19 :‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬تهريــب بقصــد االجتــار ‪ -‬قــات ‪ -‬التعزيــر بالســجن واجللــد‬\n                                                            ‫والغرامــة واإلبعــاد‪.‬‬\n\n\n\n\n                     ‫‪ -1‬األمر السامي الكرمي رقم (‪ )59633‬يف ‪1432/12/9‬هـ‪.‬‬\n                             ‫‪ -2‬قرار مجلس الوزراء رقم (‪ )11‬لعام ‪1374‬هـ ‪.‬‬\n     ‫‪ -3‬الفقــرة (أ) مــن املــادة األولــى مــن قــرار وزيــر الداخليــة رقــم ( ‪) 2057‬‬\n                                                                    ‫يف ‪1404/5/26‬هـ ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي العــام ضــد مدعــى عليهــم بتهــرب القــات مــن األراضــي‬\n     ‫اليمنيــة إلــى األراضــي الســعودية و طلــب إثبــات مــا أســند إليهــم واحلكــم‬\n     ‫بتعزيرهــم وفــق الفقــرة أ مــن املــادة األولــى لقــرار مجلــس الــوزراء‬\n     ‫رقــم(‪ )11‬لعــام ‪1374‬ه ـ وتشــديد العقوبــة علــى الثالــث لكثــرة ســوابقه‬\n     ‫‪ -‬حيــث مت القبــض علــى املدعــى عليهــم أثنــاء قدومهــم مــن اليمــن إلــى‬\n     ‫الســعودية ســير ًا علــى األقــدام بطريقــة غيــر مشــروعة وضبــط بحوزتهــم‬\n     ‫كميــة مــن نبــات القــات ‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة‬\n     ‫العينــة املضبوطــة لنبــات القــات احملظــور ‪ -‬صــادق املدعــى عليهــم علــى‬\n     ‫االدعــاء املوجــه اليهــم ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــر‬\n\n‫‪83‬‬\n\f‫املدعــى عليــه األول والثالــث بالســجن خمــس ســنوات و جلــد كل واحــد‬\n‫منهمــا خمســمائة جلــدة علنـ ًا مفرقــة كل دفعــة قدرهــا خمســون جلــدة‬\n‫و غرامــة ماليــة قدرهــا خمســة آالف ريــال وتعزيــر املدعــى عليــه الثانــي‬\n‫بالســجن أربــع ســنوات وجلــده أربعمائــة جلــدة علن ـ ًا مفرقــة كل دفعــة‬\n‫قدرهــا خمســون وغرامــة ماليــة قدرهــا ثالثــة آالف ريــال وإبعادهــم عــن‬\n‫البــاد بعــد إنفــاذ العقوبــة املقــررة بحقهــم وقنــع املدعــى عليهــم باحلكــم‬\n‫‪،‬وصــدق احلكــم‬ ‫واعتــرض املدعــي العــام مكتفي ـ ًا بالئحــة الدعــوى ُ‬\n                                                  ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بجــازان برقــم ‪ 33644973‬وتاريــخ ‪1433/11/09‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331979764‬وتاريــخ ‪1433/11/09‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافق‪1433/11/10‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 15‬‬\n‫وفيهــا حضــر املدعــي العــام ‪.....‬بالتعميــد رقــم ( ‪ ).....‬يف ‪1433/3/22‬ه ـ‬\n‫واملدعــى عليهــم‪..... /‬و‪.....‬و‪.....‬مينــي اجلنســية وقــدم املدعــي العــام دعــوى‬\n‫محــررة تتضمــن ‪ :‬أنــه بتاريــخ ‪1433/6/28‬ه ـ مت القبــض علــى املدعــى‬\n‫عليهــم أثنــاء قدومهــم مــن األراضــي اليمنيــة إلــى األراضــي الســعودية‬\n‫ســير ًا علــى األقــدام بطريقــة غيــر مشــروعة وضبــط بحوزتهــم كميــة‬\n‫مــن نبــات القــات احملظــور بلــغ وزنهــا (‪ 18‬كجــم) ثمانيــة عشــر كيلــو‬\n‫جرام ـ ًا لــكل واحــد منهــم وأثبــت التقريــر الكيميائــي الشــرعي رقــم‬\n‫(‪ ).....‬وتاريــخ ‪1433/7/14‬ه ـ إيجابيــة العينــات املرســلة منــه لنبــات‬\n\n                                                                                      ‫‪84‬‬\n\f     ‫القــات احملظــور وباســتجوابهم بعــد مواجهتهــم بالتهمــة املنســوبة إليهــم‬\n     ‫أقـ ــر كل واحــد منهــم بتهريــب الكميــة املضبوطــة بحوزتــه مــن نبــات‬\n     ‫القات احملظور من اليمن إلى الســعودية لصالح شــخص (ميني اجلنســية)‬\n     ‫يدعى‪...../‬يســكن اليمــن لغــرض إيصالهــا إلــى الشــبك بالقــرب مــن‬\n     ‫قريــة ‪.....‬الســعودية وذلــك مقابــل أجــر مــادي قــدره مائتــي ريــال لــكل‬\n     ‫واحــد منهــم ويســتقبلها شــخص يدعى‪.....‬الــذي يقــوم بإيصالهــا إلــى‬\n     ‫جهــة غيــر معلومــة لهــم وصادقــوا علــى أقوالهــم بذلــك حتقيق ـ ًا وقــد‬\n     ‫أســفر التحقيــق مــع كل مــن‪..... :‬و‪.....‬و‪.....‬عــن توجيــه االتهــام إليهــم‬\n     ‫بارتــكاب كل منهــم جرميــة تهريــب مــا وزنــه (‪ 18‬كجــم‪ -‬ثمانيــة عشــر‬\n     ‫كيلــو جرام ـاً) مــن نبــات القــات احملظــور مــن اليمــن إلــى الســعودية‬\n     ‫بقصــد االجتــار وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا ورد بأقوالهــم‬\n     ‫مبحضــر التحقيــق املرفــق ‪ -2‬مــا ورد بإقرارهــم لــدى اجلهــة القابضــة‬\n     ‫واملرفــق ‪ -3‬مــا جــاء يف محضــر القبــض املنــوه عنــه املرفــق ‪ -4‬مــا جــاء‬\n     ‫يف التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق وحيــث إن مــا أقــدم‬\n     ‫عليــه املذكوريــن فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا مبوجب قرار‬\n     ‫مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات لــذا‬\n     ‫أطلــب ‪ :‬إثبــات إدانتهــم مبــا أســند إليهــم واحلكــم بتعزيرهــم يف ضــوء‬\n     ‫الفقــرة (أ) مــن املــادة (األولــى) مــن القــرار الــوزاري املشــار إليــه أعــاه‬\n     ‫إنفــاذا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ‬\n     ‫والتشــديد يف العقوبــة علــى املدعــى عليــه الثالــث لكثــرة ســوابقه‬\n     ‫ال مــن ‪..........‬و‪.....‬مينــي اجلنســية أجــاب كل‬‫وبســؤال املدعــى عليهــم ك ً‬\n     ‫واحــد منهــم باالعتــراف بتهريــب مــا وزنــه ثمانيــة عشــر كيلــو جرامـ ًا من‬\n     ‫نبــات القــات احملظــور مــن األراضــي اليمنيــة إلــي األراضــي الســعودية‬\n\n\n‫‪85‬‬\n\f‫حلســاب الغيــر مقابــل مبلــغ مالــي هكــذا أجــاب املدعــى عليهــم عنــد‬\n‫ذلــك جــرى منــا االطــاع علــى التقريــر الكيميائــي الشــرعي وعلــى‬\n‫محضــري الــوزن والقبــض فوجــدت متطابقــة ملــا جــاء بالدعــوى وبنــاء‬\n‫علــى مــا ذكــر مــن دعــوى املدعــي العــام وعلــى إجابــة املدعــى عليهــم‬\n‫‪.....‬و‪.....‬و‪.....‬مينــي اجلنســية باالعتــراف بتهريــب كل واحــد منهــم ملــا وزنــه‬\n‫ثمانيــة عشــر كيلــو جرام ـ ًا مــن نبــات القــات احملظــور مــن اليمــن إلــي‬\n‫الســعودية حلســاب الغيــر مقابــل مبلــغ مالــي لــذا فقــد ثبــت لــدي شــرع ًا‬\n‫إدانــة املدعــى عليهــم بتهريــب كل واحــد منهــم للكميــة املوضحــة‬\n‫أعــاه حلســاب الغيــر مقابــل مبلــغ مالــي لقصــد الترويــج وهــم يســتحقون‬\n‫العقوبــة علــى ذلــك وفــق الفقــرة (أ) مــن املــادة األولــى مــن قــرار وزيــر‬\n‫الداخليــة رقــم (‪ )2057‬وتاريــخ ‪1404/5/26‬ه ـ املبنــي علــى قــرار مجلس‬\n‫الــوزراء رقــم (‪ )11‬وتاريــخ ‪1374/2/1‬ه ـ إنفــاذا لألمــر الســامي الكرمي‬\n‫رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ وملــا ذكــر أعــاه فقــد حكمــت‬\n‫بتعزيــر كل واحــد مــن املدعــى عليــه األول والثالــث بالســجن ملــدة خمس‬\n‫ســنوات مــن تاريــخ إيقــاف كل واحــد منهمــا يف ‪1433/6/28‬ه ـ وجلــد‬\n‫كل واحــد منهمــا بخمســمائة جلــدة علن ـ ًا مفرقــة كل دفعــة خمســون‬\n‫جلــدة بــن الدفعــة واألخــرى عشــرة أيــام وغرامــة ماليــة قدرهــا خمســة‬\n‫آالف ريــال (‪ 5000‬ريــال) تــودع بيــت مــال املســلمني ويعــزر املدعــى عليــه‬\n‫الثانــي بالســجن ملــدة أربــع ســنوات مــن تاريــخ إيقافــه يف ‪1433/6/28‬ه ـ‬\n‫وجلــدة بأربعمائــة جلــدة علن ـ ًا مفرقــة كل دفعــة خمســون جلــدة بــن‬\n‫الدفعــة واألخــرى عشــرة أيــام وغرامــة ماليــة قدرهــا ثالثــة أالف ريــال‬\n‫تــودع بيــت مــال املســلمني ويبعــدون عــن البــاد بعــد إنفــاذ العقوبــة املقــرر‬\n‫بحقهــم شــرع ًا وال يســمح لهــم بالعــودة إليهــا عــدى مــا تســمح بــه أنظمــة‬\n\n\n                                                                                        ‫‪86‬‬\n\f     ‫احلــج والعمــرة هــذا مــا حكمــت بــه وبعرضــه علــى الطرفــن قــرر املدعــى‬\n     ‫عليهــم القناعــة وطلــب املدعــي العــام اســتئناف احلكــم مكتفيـ ًا بالئحــة‬\n     ‫االدعــاء العــام وأمــرت بتنظيــم القــرار الــازم مبوجبــه ورفعــه حملكمــة‬\n     ‫االســتئناف مبنطقــة عســير لدراســته وإبــداء مــا تــراه نحــوه وصلــى اهلل‬\n        ‫وســلم علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر ‪1433/11/10‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n     ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n     ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n     ‫‪ 331979764‬وتاريــخ ‪1433/12/27‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n     ‫فضيلــة القاضــي باحملكمــة الشــيخ‪..... /‬برقــم ‪ 33475491‬وتاريــخ‬\n     ‫‪1433/12/21‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد كل مــن‪/‬‬\n     ‫‪.....‬و‪.....‬و‪(.....‬مينــي اجلنســية) يف قضيــة (قــات) علــى الصفــة املوضحــة يف‬\n     ‫القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة‬\n     ‫القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم ‪.‬‬\n           ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪87‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":83,"source_page_end":87,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"099d23bcc804f0ab7b94a587b9157361e7c1e452bd1b79762324476b72df172c","normalized_text_hash":"b549a9e6b86a2709f6e26c1db4033d8060b92ff9f5c140cad45d821d49f562a7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p83-33475491"},{"id":"3fc3e085-fead-53d4-8bee-32712179763d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -قات -تهريب -التعزير بالسجن واجللد واإلبعاد من","document_number":"34198977","case_number":"34163330","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":"الدائرة الثالثة لتدقيق القضايا اجلزائية مبحكمة الاستئناف","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/27","year":"1434","subject":"مخدرات -قات -تهريب -التعزير بالسجن واجللد واإلبعاد من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34198977 :‬تاريخه‪1434/4/27:‬هـ‬\n                  ‫رقم الدعوى‪34163330 :‬‬\n  ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34264980‬تاريخه‪1434/7/11 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬قــات ‪ -‬تهريــب ‪ -‬التعزيــر بالســجن واجللــد واإلبعــاد مــن‬\n                                                                  ‫البــاد‬\n\n\n\n\n                     ‫‪ -1‬األمر السامي رقم (‪ )59633‬يف ‪1432/12/9‬هـ‪.‬‬\n                     ‫‪ -2‬قرار مجلس الوزراء رقم(‪ )11‬يف ‪1374/2/1‬هـ‪.‬‬\n‫‪ -3‬الفقــرة (أ) مــن املــادة األولــى مــن قــرار وزيــر الداخليــة رقــم (‪)2057‬‬\n                                                             ‫يف ‪1404/5/26‬هــ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا بتلقــي قــات بقصــد االجتــار‪،‬‬\n‫قبــض علــى املدعــى عليهمــا عنــد الشــبك احلــدودي أثنــاء اســتقبالهما‬\n‫للقــات املهــرب مــن اليمــن وبحوزتهمــا نبــات القــات وطلب إثبات ما أســند‬\n‫إليهمــا ومعاقبتهمــا وإبعادهمــا عــن البــاد وتشــديد العقوبــة علــى الثانــي‬\n‫لتعــدد ســوابقه وأثبــت التقريــر الكيمائــي الشــرعي إيجابيــة العينــة‬\n‫لنبــات القــات احملظــور ‪،‬مصادقــة املدعــى عليهمــا علــى الدعــوى‪ ،‬وبنــاء‬\n‫علــى مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليهمــا بســجن األول‬\n‫ثــاث ســنوات وجلــده ‪ 500‬جلــده والثانــي بخمــس ســنوات وجلــده ‪700‬‬\n‫جلــده وإبعادهمــا عــن البــاد وقنــع املدعــى عليهمــا واعتــرض املدعــي‬\n\n                                                                                    ‫‪88‬‬\n\f            ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n                                                   ‫العــام بــدون الئحــة ُ‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزائيــة بجــازان برقــم ‪ 34163330‬وتاريــخ ‪1434/04/09‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 34869065‬وتاريــخ ‪1434/04/09‬ه ـ ففــي يــوم‬\n     ‫األربعــاء املوافق‪1434/04/10‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 15‬‬\n     ‫وفيهــا حضــر املدعــي العــام ‪.....‬بالتعميــد رقــم (‪ ).....‬يف ‪1433/3/22‬ه ـ‬\n     ‫واملدعــى عليهمــا ‪.....‬مينــي اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪).....‬‬\n     ‫و‪ .....‬مينــي اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ ).....‬وقــدم املدعــي‬\n     ‫العــام دعــوى محــررة تتضمــن ‪ :‬أنــه بتاريــخ ‪1434/2/25‬ه ـ وأثنــاء قيــام‬\n     ‫إحــدى دوريــات حــرس احلــدود بواجبهــا مت مشــاهدة أربعــة أشــخاص‬\n     ‫كانــوا متواجديــن مــن الشــبك احلــدودي مــن اجلهــة الغربيــة شــرق قريــة‬\n     ‫‪.....‬ومبراقبتهــم شــاهدوا أشــخاص يقومــون برمــي أكيــاس ال يعــرف‬\n     ‫مــا بداخلهــا مــن فــوق الشــبك ويقــوم األشــخاص األربعــة باســتقبال‬\n     ‫الكميــات وبالتوجــه إليهــم الذوا بالفــرار إلــى قريــة ‪.....‬وباللحــاق بهــم‬\n     ‫مت القبــض علــى اثنــن منهــم واتضــح أنهمــا املدعــى عليهمــا وكان‬\n     ‫بحــوزة املدعــى عليــه ‪.....‬مــا وزنــه (‪ 9‬كجــم) تســعة كيلــو جرام ـ ًا مــن‬\n     ‫نبــات القــات احملظــور وبحــوزة ‪.....‬مــا وزنــه (‪ 12‬كجــم) اثنــا عشــر‬\n     ‫كيلــو جرام ـ ًا مــن نبــات القــات احملظــور ولــم يتمكــن أفــراد الدوريــة‬\n     ‫مــن القبــض علــى اآلخريــن وقــد أثبــت التقريــر الكيميائــي الشــرعي‬\n     ‫رقــم (‪ ).....‬وتاريــخ ‪1434/15‬ه ـ ايجابيــة العينــات املرســلة لنبــات‬\n\n‫‪89‬‬\n\f‫القــات احملظــور وباســتجواب املدعــى عليهمــا ومبواجهتهمــا بالتهمــة‬\n‫املنســوبة إليهمــا أقــرا بتلقيهمــا الكميــة املضبوطــة معهمــا مــن نبــات‬\n‫القــات احملظــور وأفــادا بــأن غرضهمــا مــن تلقــي الكميــة ايصالــه‬\n‫إلــى شــخص مينــي يف قريــة ‪.....‬الســعودية مقابــل االســتخدام ملــا قيمتــه‬\n‫عشــرون ريــال لــكل حبــة قــات وقــد أســفر التحقيــق معهمــا عــن توجيــه‬\n‫االتهــام إليهمــا بتلقــي األول مــا وزنــه (‪ 12‬كجــم) اثنــا عشــر كيلــو‬\n‫جرام ـ ًا مــن نبــات القــات احملظــور واملهــرب مــن اليمــن الــى الســعودية‬\n‫بقصــد االجتــار وتلقــي الثانــي مــا وزنــه (‪ 9‬كجــم) تســعة كيلــو جرامـ ًا‬\n‫مــن نبــات القــات احملظــور واملهــرب مــن اليمــن الــى الســعودية بقصــد‬\n‫االجتــار وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء يف أقوالهمــا املنــوه‬\n‫عنهــا واملدونــة علــى محاضــر االســتجواب املرفقــة ‪ -2‬مــا جــاء محضــر‬\n‫القبــض والتفتيــش املرفــق ‪ -3‬مــا جــاء يف التقريــر الكيميائــي املنــوه‬\n‫عنــه واملرفــق وحيــث إن مــا أقــدم عليــه املذكوريــن فعــل محــرم شــرع ًا‬\n‫ومعاقــب عليــه نظام ـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام‬\n‫‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات لــذا أطلــب مــا يلــي ‪ :‬إثبــات إدانتهمــا‬\n‫مبــا أســند إليهمــا واحلكــم عليهمــا مبــا يلــي‪ /1 :‬بتعزيره يف ضــوء الفقرة‬\n‫(أ) مــن املــادة (األولــى) مــن القــرار الــوزاري املشــار إليــه أعــاه إنفــاذ ًا‬\n‫لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ يف ‪1432/12/9‬ه ـ ‪/2‬‬\n‫وإبعادهمــا عــن البــاد بعــد انتهــاء محكوميتهمــا اســتنادا لتعميــم وزيــر‬\n‫الداخليــة رقــم ( ‪ )69935‬بتاريــخ ‪1433/6/18‬ه ـ ‪ /3‬تشــديد العقوبــة‬\n‫علــى الثانــي نظــر ًا لتعــدد ســوابقه وبســؤال املدعــى عليهمــا ‪.....‬و‪ .....‬مينــي‬\n‫اجلنســية أجــاب املدعــى عليــه األول بتلقــي مــا وزنــه اثنــا عشــر كيلــو‬\n‫جرامـ ًا مــن نبــات القــات احملظــور مــن مهــرب مــن اليمــن إلــي الســعودية‬\n\n\n                                                                                         ‫‪90‬‬\n\f     ‫حلســاب الغيــر مقابــل مبلــغ مالــي وأجــاب املدعــى عليــه الثانــي ‪.....‬مينــي‬\n     ‫اجلنســية باالعتــراف بتلقــي مــا وزنــه تســعة كيلــو جرام ـ ًا مــن نبــات‬\n     ‫القــات احملظــور مــن مهــرب مــن اليمــن إلــي الســعودية حلســاب الغيــر‬\n     ‫مقابــل مبلــغ مالــي كمــا أقــر كل واحــد منهمــا بالســوابق املســجلة عليــه‬\n     ‫بالئحــة االدعــاء العــام هكــذا أجــاب املدعــى عليهمــا عنــد ذلــك جــرى‬\n     ‫منــا االطــاع علــى التقريــر الكيميائــي الشــرعي وعلــى محضــري الوزن‬\n     ‫والقبــض فوجــدت متطابقــة ملــا جــاء بالدعــوى وبنــاء علــى مــا ذكــر مــن‬\n     ‫دعــوى املدعــي العــام وعلــى إجابــة املدعــى عليهمــا ‪.....‬و‪ .....‬مينــي اجلنســية‬\n     ‫باالعتــراف بتلقــي األول ملــا وزنــه اثنــا عشــر كيلــو جرامـ ًا وتلقــي الثانــي‬\n     ‫ملــا وزنــه تســعة كيلــو جرام ـ ًا مــن نبــات القــات احملظــور مــن مهــرب‬\n     ‫مــن اليمــن إلــي الســعودية حلســاب الغيــر مقابــل مبلــغ مالــي لــذا فقــد‬\n     ‫ثبــت لــدي شــرع ًا إدانــة املدعــى عليهمــا املذكوريــن بتلقــي كل واحــد‬\n     ‫منهمــا لكميــة نبــات القــات احملظــور املوضحــة أعــاه مــن مهــرب مــن‬\n     ‫اليمــن إلــي الســعودية حلســاب الغيــر مقابــل مبلــغ مالــي لقصــد الترويــج‬\n     ‫وهمــا يســتحقان العقوبــة علــى ذلــك وفــق الفقــرة (أ) مــن املــادة األولــى‬\n     ‫مــن قــرار ســمو وزيــر الداخليــة رقــم (‪ )2057‬وتاريــخ ‪1404 /5/26‬ه ـ‬\n     ‫اســتناد ًا لقــرار مجلــس الــوزراء رقــم (‪ )11‬وتاريــخ ‪1374/2/1‬ه ـ وإنفــاذ ًا‬\n     ‫لألمــر الســامي رقــم (‪ )59633‬يف ‪1432/12/9‬ه ـ وملــا ذكــر أعــاه‬\n     ‫فقــد حكمــت بتعزيــر املدعــى عليــه األول بالســجن ملــدة خمــس ســنوات‬\n     ‫وتعزيــر املدعــى عليــه الثانــي بالســجن ملــدة ســبع ســنوات لكثرة ســوابقه‬\n     ‫وجلــد األول بخمســمائة جلــدة وجلــد الثانــي بســبعمائة جلــدة علن ًا مفرقة‬\n     ‫كل دفعــة خمســون جلــدة واألخــرى عشــرة أيــام وغرامــة ماليــة علــى‬\n     ‫كل واحــد منهمــا قدرهــا خمســة أالف ريــال تــودع بيــت مــال املســلمني‬\n\n\n‫‪91‬‬\n\f‫ويبعــدان عــن البــاد بعــد إنفــاذ العقوبــة املقــررة بحقهمــا شــرع ًا وال‬\n‫يســمح لهمــا بالعــودة إليهــا عــدا مــا تســمح بــه تعليمــات احلــج والعمــرة‬\n‫هــذا مــا حكمــت بــه وبعرضــه علــى الطرفــن قــرر املدعــى عليــه القناعــة‬\n‫وطلــب املدعــي العــام اســتئناف احلكــم مكتفيـ ًا بالئحــة االدعــاء العــام‬\n‫وأمــرت بتنظيــم القــرار الــازم مبوجبــه ورفعــه حملكمــة االســتئناف‬\n‫مبنطقــة عســير لدراســته وإبــداء مــا تــراه نحــوه وصلــى اهلل علــى نبينــا‬\n                      ‫محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/4/10‬ه ـ‬\n‫ـاء علــى مالحظــة أصحــاب القضــاة قضــاة‬        ‫احلمــد هلل وحــده وبعــد فبنـ ً‬\n‫الدائــرة الثالثــة لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف‬\n‫مبنطقــة عســير بقرارهــم رقــم ‪ 34222204‬وتاريــخ ‪1434/5/26‬ه ـ علــى‬\n‫القــرار الصــادر منــا برقــم ‪ 34198977‬وتريــخ ‪1434/4/27‬ه ـ اخلــاص‬\n‫بدعــوى املدعــي العــام ضــد كل مــن ‪.....‬و‪.....‬مينــي اجلنســية يف قضيــة‬\n‫قــات علــى الصفــة املوضحــة يف القــرار املتضمــن حكمنــا مبــا هــو مــدون‬\n‫ومفصــل فيــه ونــص قــرار أصحــاب الفضيلــة بدراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة تقــرر إعادتهــا لفضيلــة حاكمهــا ملالحظــة أن‬\n‫احلكــم علــى املدعــى عليهمــا كثيــر جــد ًا الســيما وأن الكميــة قليلــة‬\n‫فعلــى فضيلتــه إعــادة النظــر يف احلكــم وإكمــال الــازم واهلل املوفــق‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه وســلم أنتهــى نصــه‬\n‫وبنــاء عليــه وجتاوبــا مــع أصحــاب الفضيلــة بــأن مــا قررنــاه مــن تعزيــر‬\n‫بحــق املدعــى عليهمــا يتناســب مــع جرمهمــا وكثــرة ســوابقهما وخاصــة‬\n‫املدعــى عليــه الثانــي فعليــه خمــس ســوابق منوعــة وقــد ســجن يف بعضهــا‬\n‫ســبع ســنوات ولــم يرتــدع بالعقوبــة التــي نالهــا وعلــى املدعــى عليــه األول‬\n‫ســابقة واحــدة ممــا ثلــة ومــع هــذا وجتاوبـ ًَا مــع أصحــاب الفضيلــة فقــد‬\n\n\n                                                                                     ‫‪92‬‬\n\f     ‫قــررت تخفيــف ســجن كل واحــد مــن املدعــى عليهمــا ســنتني ليصبــح‬\n     ‫ســجن املدعــى عليــه األول ثــاث ســنوات وســجن املدعــى الثانــي خمــس‬\n     ‫ســنوات مــن التاريــخ املوضــح باحلكــم مــع بقــاء حكمنــا فيمــا عــدى‬\n     ‫ذلــك علــى مــا هــو عليــه وجــرى منــا عــرض ذلــك علــى املدعــي العــام بقــي‬\n     ‫املدعــي العــام علــى اعتراضــه الســابق وأمــرت بإحلــاق مــا ذكــر بالقــرار‬\n     ‫وضبطــه وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر‬\n                                                                  ‫يف ‪1434/6/14‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n     ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n     ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان رقــم‬\n     ‫‪ 341426187‬وتاريــخ ‪1434/6/21‬ه ـ املرفــق بهــا القــرار الشــرعي‬\n     ‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪..... /‬رقــم ‪34198977‬‬\n     ‫وتاريــخ ‪1434/4/27‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد كل مــن‪/‬‬\n     ‫‪.....‬و ‪ (.....‬مينــي اجلنســية ) يف قضيــة ( قــات ) علــى الصفــة املوضحــة يف‬\n     ‫القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وحيــث‬\n     ‫ســبق دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى‬\n     ‫ـاء علــى قرارنــا‬\n                      ‫مــا أجــاب بــه فضيلتــه وأحلقــه بالقــرار وصــورة ضبطــه بنـ ً‬\n     ‫رقــم ‪ 34222204‬وتاريــخ ‪1434/5/26‬ه ـ تقــررت املوافقــة علــى احلكــم‬\n     ‫بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                     ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪93‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":88,"source_page_end":93,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a82673090b0a7eb26e2f142c4506c834c602b111ff4645975a5b4522fed93034","normalized_text_hash":"003c590722a338d3e3d45489996ad87731ec38c0b285f9ed1e35c2a6aad11d8a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p88-34198977"},{"id":"3342d2c3-b2c3-5d53-b67e-9c98baf6079f","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تهريب احلبوب احملظورة «الكبتاجون» -رجوع عن إقرار مصدق شرع ا -الرجوع عن االقرار مبا يوجب التعزير اليقبل - من لم يندفع فساده اال بالقتل يقتل -التعزير بالقتل ومصادرة السيارة واجلوال املستخدمة يف اجلرمية.","document_number":"34279643","case_number":"34243103","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/25","year":"1434","subject":"مخدرات -تهريب احلبوب احملظورة «الكبتاجون» -رجوع عن إقرار مصدق شرع ا -الرجوع عن االقرار مبا يوجب التعزير اليقبل - من لم يندفع فساده اال بالقتل يقتل -التعزير بالقتل ومصادرة السيارة واجلوال املستخدمة يف اجلرمية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 34279643 :‬تاريخه‪1434/7/25 :‬هـ رقم‬\n                            ‫الدعوى‪34243103 :‬‬\n‫رقم قرار التصديق من محكمة االستئناف‪34350294 :‬‬\n                          ‫تاريخه‪1434/11/4 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬تهريــب احلبــوب احملظــورة «الكبتاجــون» ‪ -‬رجــوع عــن إقــرار‬\n      ‫مصــدق شــرع ًا‪ -‬الرجــوع عــن االقــرار مبــا يوجــب التعزيــر اليقبــل ‪-‬‬\n      ‫مــن لــم يندفــع فســاده اال بالقتــل يقتــل ‪ -‬التعزيــر بالقتــل ومصــادرة‬\n                                   ‫الســيارة واجلــوال املســتخدمة يف اجلرميــة‪.‬‬\n\n\n\n\n      ‫‪ -‬قولــه تعالــى‪« :‬إمنــا جــزاء الذيــن يحاربــون اهلل ورســوله ويســعون يف‬\n      ‫األرض فســاد ًا أن يقتلــوا أو يصلبــوا أو تقطــع أيديهــم وأرجلهــم مــن‬\n                                                         ‫خــاف) اآليــة [املائــدة‪]33:‬‬\n      ‫‪ -‬قــال ابــن قدامــة رحمــه اهلل‪( :‬وال يقبــل رجــوع املقــر عــن إقــراره إال‬\n      ‫فيمــا كان حــدا هلل تعالــى يــدرأ بالشــبهات‪ ،‬ويحتــاط إلســقاطه فأمــا‬\n      ‫حقــوق اآلدميــن وحقــوق اهلل تعالــى التــي ال تدرأ بالشــبهات كالزكاة‬\n      ‫والكفــارات‪ ،‬فــا يقبــل رجوعــه عنهــا وال نعلــم يف هــذا خالفــا ) أ‪.‬ه ـ‬\n                                                                       ‫املغنــي‪469/4 :‬‬\n      ‫‪ -‬قــال يف كشــاف القنــاع‪( :‬ويكــون التعزيــر بالضرب واحلبس والصفع‬\n      ‫والتوبيــخ والعــزل عــن الواليــة وقــال يف االختيــارات إذا كان املقصــود‬\n      ‫دفــع الفســاد ولــم يندفــع إال بالقتــل قتــل وحينئــذ فمــن تكــرر منــه‬\n      ‫جنــس الفســاد ولــم يرتــدع باحلــدود املقــدرة بــل اســتمر علــى الفســاد‬\n                               ‫فهــو كالصائــل ال يندفــع إال بالقتــل فيقتل)أ‪.‬ه ـ‬\n      ‫وقــال‪( :‬وقــال الشــيخ يعــزر أي مــن وجــب عليــه التعزيــر مبــا يردعــه ألن‬\n                                                                                         ‫‪94‬‬\n\f     ‫القصــد الــردع وقــد يقــال بقتلــه أي مــن لزمــه التعزيــر للحاجة)أ‪.‬ه ـ‬\n                                                   ‫كشــاف القنــاع‪.)120/14( :‬‬\n     ‫‪ -‬مــا جــاء يف قــرار هيئــة كبــار العلمــاء رقــم ( ‪ ) 138‬الصــادر عــن‬\n     ‫مجلــس هيئــة كبــار العلمــاء يف دورتــه التاســعة والعشــرين املنعقــدة‬\n     ‫مبدينــة الريــاض بتاريــخ ‪1407 /6/9‬ه ـ وحتــى‪1407 /6/20‬هــ‪( :‬أوال‬\n     ‫بالنســبة ملهــرب املخــدرات فــإن عقوبتــه القتــل ملــا يســببه تهريــب‬\n     ‫املخــدرات وإدخالهــا البــاد مــن فســاد عظيــم ال يقتصــر علــى املهــرب‬\n     ‫نفســه وأضــرار جســيمة وأخطــار بليغــة علــى األمــة مبجموعهــا ويلحــق‬\n     ‫باملهــرب الشــخص الــذي يســتورد أو يتلقــى املخــدرات مــن اخلــارج‬\n                                                     ‫فيم ـ ّون بهــا املروجني)أ‪.‬ه ـ‬\n     ‫‪ -‬الفقــرة األولــى مــن املــادة الســابعة والثالثــن مــن نظــام مكافحــة‬\n     ‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )37‬يف‬\n                                                                 ‫‪1426/7/8‬هــ‪.‬‬\n\n\n\n\n     ‫أســفر التحقيــق مــع املدعــى عليــه عــن اتهامــه بتهريــب كميــة مــن حبوب‬\n     ‫اإلمفيتامــن املنبــه للجهــاز العصبــي احملظــور البالــغ عددهــا مائتــان‬\n     ‫وتســعة آالف ومائــة وعشــر حبــات‪ ،‬طلــب املدعــي العــام إثبــات مــا أســند‬\n     ‫إلــى املدعــى عليــه‪ ،‬واحلكــم عليــه بالقتــل تعزيــرا‪ ،‬ومصــادرة الســيارة‪،‬‬\n     ‫واجلــوال املســتخدمة يف اجلرميــة‪ ،‬وفــق نظــام مكافحــة املخــدرات‬\n     ‫واملؤثــرات العقليــة ‪ ،‬لــم يســجل علــى املدعــى عليــه أي ســوابق‪ ،‬بعــرض‬\n     ‫دعــوى املدعــي العــام علــى املدعــى عليــه أنكرهــا‪ ،‬ودفــع أن الكميــة‬\n     ‫وجــدت يف ســيارته وأنــه ليــس هــو الــذي وضعهــا‪ ،‬وال يعلــم عنهــا‪ ،‬جــرى‬\n\n‫‪95‬‬\n\f‫االطــاع علــى إقــرار املدعــى عليــه املصــدق شــرعا‪ ،‬كما جــرى االطالع‬\n‫علــى محضــر الضبــط‪ ،‬كمــا جــرى االطــاع علــى التقريــر الكيميائــي‬\n‫الشــرعي املتضمــن أنــه بالفحــص الكيميائــي الشــرعي حملتويــات احلــرز‬\n‫املرســل ثبــت إيجابيــة العينــة ملــادة اإلمفيتامــن ‪ ،‬بعــرض أدلــة املدعــي‬\n‫العــام علــى املدعــى عليــه‪ ،‬أنكــر إقــراره املصــدق شــرعا‪ ،‬ودفــع أنــه‬\n‫أخــذ منــه بالقــوة وأنــه ال بينــة لــه علــى ذلــك‪ ،‬وصــادق علــى مــا جــاء يف‬\n‫محضــر الضبــط‪ ،‬وقــرر عــدم علمــه مبــا جــاء يف التقريــر الكيميائــي‬\n‫الشــرعي ‪ ،‬نظــر ًا إلنــكار املدعــى عليــه مــا جــاء يف دعــوى املدعــي العام‬\n‫جملــة وتفصي ـاً‪ ،‬وملــا جــاء يف اعتــراف املدعــى عليــه املصــدق شــرعاً‪،‬‬\n‫واملتضمــن صحــة مــا ذكــره املدعــي العــام يف دعــواه‪ ،‬وإلنــكار املدعــى‬\n‫عليــه هــذا االعتــراف جملــة وتفصيــا ودفعــه بأنــه أخــذ منــه بالقــوة وال‬\n‫بينــة لــه علــى ذلــك‪ ،‬وألن الرجــوع عــن اإلقــرار مبــا يوجــب التعزيــر ال‬\n‫يقبــل‪ ،‬ولكــون املدعــى عليــه مكلفــا لــذا ثبتــت إدانــة املدعــى عليــه مبــا‬\n‫أســند إلــى املدعــى عليــه‪ ،‬ومت احلكــم بقتلــه تعزيــراً‪ ،‬ومصــادرة ســيارته‬\n‫وجوالــه املوصوفــن يف الدعــوى ‪ ،‬بعــرض احلكــم علــى املدعــى عليــه‬\n‫قــرر اعتراضــه عليــه وطلــب اســتئنافه مــع تقــدمي الئحــة اعتراضيــة‪،‬‬\n‫وال حاجــة لعــرض احلكــم علــى املدعــي العــام ألنــه حكــم لــه بــكل‬\n‫طلباتــه بنــاء علــى املــادة (‪ )174‬مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n‫التنفيذيــة‪ ،‬وبعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقة عليه‪.‬‬\n\n\n\n\n                                                                                      ‫‪96‬‬\n\f     ‫احلمــد هلل وحــده وبعــد يف يــوم الثالثــاء ‪1434/7/25‬ه ـ لدينــا نحــن‬\n     ‫القضــاة باحملكمــة العامــة بتبــوك ‪ ......‬و‪ ......‬و‪ ......‬وبنــاء علــى ورود‬\n     ‫املعاملــة إلــى احملكمــة العامــة بتبــوك بخطاب رئيس فــرع هيئة التحقيق‬\n     ‫واإلدعــاء العــام مبنطقــة تبــوك رقــم ‪ 8776‬يف ‪1434/5/7‬ه ـ واملقيــدة يف‬\n     ‫احملكمــة برقــم ‪ 341175324‬يف ‪1434/5/13‬ه ـ واحملالــة إلينــا مــن‬\n     ‫فضيلــة الرئيــس برقــم ‪ 34243103‬يف ‪1434/5/26‬ه ـ والتــي ســبق وأن‬\n     ‫صــدر فيهــا قــرار مــن هــذه احملكمــة برقــم ‪/3/3‬ض يف ‪1431/4/28‬هـ‬\n     ‫ومت نقضــه مبوجــب القــرار الصــادر مــن الدائــرة اجلزائيــة األولــى‬\n     ‫باحملكمــة العليــا رقــم ‪ 3/1/19‬يف ‪1434/3/21‬ه ـ بشــأن دعــوى‬\n     ‫املدعــي العــام ضــد ‪ ......‬بشــأن قضيــة تهريــب مخــدرات فتحــت اجللســة‬\n     ‫األولــى يف متــام الســاعة الثامنــة وفيهــا حضــر املدعــي العام ‪ ......‬الســعودي‬\n     ‫بالســجل املدنــي رقــم ‪ ......‬مبوجــب خطــاب التكليــف الصــادر مــن‬\n     ‫ســعادة رئيــس فــرع هيئــة التحقيــق واإلدعــاء العــام بتبــوك رقــم ‪ ......‬يف‬\n     ‫‪1433/9/5‬ه ـ وادعــى علــى احلاضــر معــه ‪ ......‬الســعودي بالســجل املدنــي‬\n     ‫رقــم ‪ ......‬قائــا يف حتريــر دعــواه بصفتــي مدعيــا عامــا بدائــرة اإلدعــاء‬\n     ‫العــام لفــرع الهيئــة مبنطقــة تبــوك أدعــي علــى احلاضــر ‪ ......‬إنــه بتاريــخ‬\n     ‫‪1430/4/28‬ه ـ قــدم املدعــى عليــه مــن دولــة األردن إلــى منفــذ الــدرة‬\n     ‫الســعودي وعنــد تفتيــش ســيارته مــن نــوع ‪ ....‬يحمــل اللوحــة رقــم ‪ ......‬مت‬\n     ‫اشــتباه موظــف اجلمــرك بخــزان الوقــود األساســي وعنــد إنزالــه وفتحــه‬\n     ‫وجــد بداخلــه كميــة مــن احلبــوب يشــتبه أن تكــون مــن حبــوب‬\n     ‫الكبتاجــون املخــدرة احملظــورة بلــغ عددهــا مائتــن وتســعة آالف ومائــة‬\n\n‫‪97‬‬\n\f‫وعشــر ‪209110‬حبــة موزعــة علــى أكيــاس بالســتيك وكان يرافــق‬\n‫املدعــى عليــه أثنــاء القبــض عليــه اثنــان مــن أبنائــه وأثنــاء وجــوده داخــل‬\n‫اجلمــرك ورده اتصــال مــن رقــم أردنــي (‪ ) ......‬وذكــر أن املتصــل هــو‬\n‫مكفولــه املدعــو ‪ ......‬أردنــي اجلنســية ولديــه إقامــة ســائق خــاص وقــال‬\n‫لــه (هــل خرجــت مــن اجلمــرك؟ قــال لــه نعــم) ثــم اتصــل عليــه مــرة أخــرى‬\n‫إال أنــه أقفــل جوالــه وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم ‪......‬‬\n‫لعــام ‪1430‬ه ـ الصــادر مــن مراقبة الســموم والكيمياء الطبية الشــرعية‬\n‫بصحــة تبــوك ثبــوت إيجابيــة العينــة املضبوطــة ملــادة األمفيتامــن املنبــه‬\n‫للجهــاز العصبــي املركــزي واملــدرج باجلــدول رقــم (‪ )2‬فئــة (ب) مــن‬\n‫تعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم (‪)89400/19‬‬\n‫وتاريــخ ‪1426/10/25‬ه ـ وباســتجواب املدعــى عليــه أقــر أنــه بتاريــخ‬\n‫‪1430/4/28‬ه ـ قــدم مــن دولــة األردن إلــى الســعودية عبــر منفــذ الــدرة‬\n‫علــى ســيارته مــن نــوع ‪ .....‬يحمــل اللوحــة رقــم ‪ ......‬وعنــد إجــراء التفتيــش‬\n‫علــى ســيارته عثــر موظــف اجلمــارك بداخــل خــزان الوقــود لســيارته علــى‬\n‫كميــة مــن احلبــوب احملظــورة بلــغ عددهــا مائتــن وتســعة آالف ومائــة‬\n‫وعشــر ‪209110‬حبــة واعتــرف بــأن هــذه الكميــة تعــود لشــخص أردنــي‬\n‫يدعــى ‪ ......‬حيــث أنــه يف نفــس اليــوم وعندمــا كان يف األردن اتصــل‬\n‫عليــه املدعــو ‪ ......‬علــى جوالــه وطلــب منــه احلضــور إلــى منزلــه عصــرا يف‬\n‫‪ ......‬بــاألردن وتوجــه إلــى منــزل املدعــو ‪ ......‬يف األردن وعــرض عليــه‬\n‫تركيــب خــزان الوقــود املخــزن بداخلــه كميــة احلبــوب احملظــورة وطلب‬\n‫منــه تركيبــه علــى ســيارته ومــن ثــم إدخالــه إلــى الســعودية عبــر منفــذ‬\n‫الــدرة فوافــق علــى ذلــك ثــم توجــه إلــى الســعودية فتــم القبــض عليــه‬\n‫وذكــر أنــه أقــدم علــى هــذا الفعــل لعــدم وجــود دخــل لــه ولكبــر أســرته‬\n\n\n                                                                                        ‫‪98‬‬\n\f     ‫وحاجتــه املاســة للمــال وقــد أســفر التحقيــق مــع املدعــى عليــه عــن اتهامــه‬\n     ‫بتهريــب كميــة مــن حبــوب األمفيتامــن املنبــه للجهــاز العصبــي احملظور‬\n     ‫البالــغ عددهــا مائتــن وتســعة آالف ومائــة وعشــر ‪209110‬حبــة وحيــث‬\n     ‫إن مــا أقــدم عليــه املذكــور فعــل محــرم شــرعا ومجــرم نظامــا اســتنادا‬\n     ‫للمــادة الثالثــة فقــرة (‪ )1‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n     ‫ومعاقــب عليــه بالعقوبــات األصليــة والتكميليــة لــذا أطلــب مــا يلــي ‪-1:‬‬\n     ‫إثبــات مــا أســند إليــه ‪ -2‬احلكــم عليــه بالقتــل تعزيــرا اســتنادا للمــادة‬\n     ‫(‪ )37‬فقــرة (‪ )1‬مــن البنــد أوال مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة املشــار إليــه ‪ -3 -‬احلكــم مبصــادرة الســيارة العائــدة ملكيتهــا‬\n     ‫مــن نــوع ‪ .....‬رقــم اللوحــة ‪ ......‬اللــون بيــج صنــع عــام (‪1991‬م) ومصــادرة‬\n     ‫اجلــوال العائــد لــه مــن نــوع ‪ ....‬الرقــم التسلســلي للجهــاز (‪ ) ......‬اســتنادا‬\n     ‫للمــادة رقــم (‪ )53‬فقــرة (‪ )1‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة املشــار إليــه الســتخدامها يف اجلرميــة (علمــا بــأن املدعــى عليــه‬\n     ‫ليــس مســجل ضــده ســوابق جنائيــة كمــا ذكــر ذلــك يف هــذه الالئحــة)‬\n     ‫هــذه دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب‬\n     ‫قائــا مــا ذكــره املدعــي العــام يف دعــواه غيــر صحيــح جملــة وتفصيــا‬\n     ‫والصحيــح أنــه بتاريــخ ‪1430/4/27‬ه ـ وقبــل قدومــي إلــى منفــذ الــدرة‬\n     ‫بيــوم طلــب منــي مكفولــي ‪ ......‬ســيارتي املوصوفــة يف الدعــوى إليصــال‬\n     ‫ابنتــه إلــى املستشــفى ومكثــت لديــه ســيارتي حوالــي ســبع ســاعات‬\n     ‫وبعدهــا رجــع وأعطانــي ســيارتي ثــم اجتهــت بهــا إلــى منفــذ الــدرة وكان‬\n     ‫يرافقنــي اثنــن مــن أبنائــي وبعــد التفتيــش علــى ســيارتي مــن قبــل رجــال‬\n     ‫اجلمــرك وجــدوا معــي الكميــة املذكــورة ولســت أنــا الــذي وضعتهــا يف‬\n\n\n‫‪99‬‬\n\f‫ســيارتي وال أعلــم عــن هــذه احلبــوب الكبتاجــون احملظــورة شــيئا ولــم‬\n‫يتصــل علــي مكفولــي يف اجلمــرك ولــم أتصــل عليــه وأنــا بــرئ مــن هــذه‬\n‫القضيــة هــذه إجابتــي وجــرى ســؤال املدعــي العــام عــن بينتــه علــى دعــواه‬\n‫أجــاب قائــا بينتــي هــي مــا يلــي‪ -1 :‬إقــراره املصــدق شــرعا املــدون علــى‬\n‫الصفحــة رقــم (‪ )6‬لفــة رقــم (‪ -2 )1‬محضــر الضبــط املــدون علــى اللفــة‬\n‫رقــم (‪ -3 )5‬التقريــر الكيميائــي الشــرعي املــدون علــى اللفــة رقــم (‪)14‬‬\n‫هــذه بينتــي وجــرى منــا االطــاع علــى الدليــل األول مــن أدلــة املدعــي‬\n‫العــام وهــو إقــرار املدعــى عليــه املــدون علــى الصفحــة رقــم (‪ )6‬لفــة رقــم‬\n‫(‪ )1‬ونصــه (أقــر أنــا املدعــو ‪ ......‬ســعودي اجلنســية مبوجــب الهويــة رقــم‬\n‫(‪ ) ......‬صــادرة مــن حقــل بتاريــخ ‪1403/10/29‬ه ـ عاطــل عــن العمــل‬\n‫أبلــغ مــن العمــر حوالــي (‪ 44‬ســنة) أقــر أنه بتاريــخ ‪1430/4/28‬هـ قدمت‬\n‫مــن األردن إلــى الســعودية عبــر منفــذ الــدرة علــى ســيارتي نــوع ‪ ....‬حتمــل‬\n‫اللوحــة رقــم ‪ ......‬وعنــد إجــراء التفتيــش علــى ســيارتي عثــر موظــف‬\n‫اجلمــرك بداخــل خــزان الوقــود العائــد لســيارتي علــى كميــة مــن حبــوب‬\n‫الكبتاجــون بلــغ عددهــا مائتــن وتســعة آالف ومائــة وعشــرة ‪209110‬‬\n‫حبــة وهــذه الكميــة مــن احلبــوب تعــود أصــا لشــخص أردنــي يعمــل‬\n‫حتــت كفالتــي مبهنــة ســائق خــاص ويســكن األردن ويدعــى ‪ ......‬حيــث‬\n‫أنــه يف يــوم القبــض علــي وعندمــا كنــت بــاألردن اتصــل علــى جوالــي ‪....‬‬\n‫يطلــب منــي احلضــور إلــى منزلــه عصــرا الــذي يقــع يف مدينــة ‪ ......‬األردنية‬\n‫وفعــا توجهــت لــه ومبنزلــه عــرض علــي تركيــب تانكــي الوقــود الــذي‬\n‫بــه احلبــوب علــى ســيارتي وإدخالــه إلــى حقــل عبــر منفــذ الــدرة ولــم يحــدد‬\n‫لــي املبلــغ قيمــة قيامــي بذلــك العمــل فوافقــت علــى ذلــك وقــام هــو بفــك‬\n‫خــزان الوقــود األساســي بســيارتي وتركيــب خــزان الوقــود الــذي‬\n\n\n                                                                                       ‫‪100‬‬\n\f      ‫بداخلــه كميــة احلبــوب ومــن ثــم توجهــت إلــى الســعودية ومت القبــض‬\n      ‫علــي كمــا أنــه أثنــاء تواجــودي داخــل اجلمــرك وقــت القبــض علــي اتصــل‬\n      ‫بــي ‪ .....‬مــن جوالــه األردنــي رقــم (‪ ) ......‬وقــال لــي هــل خرجــت مــن‬\n      ‫اجلمــرك قلــت لــه نعــم وقمــت باالتصــال عليــه مــرة أخــرى إال أنــه أقفــل‬\n      ‫جوالــه وهــذه هــي املــرة األولــى التــي أقــوم بهــا بتهريــب املمنوعــات إلــى‬\n      ‫البــاد وال يوجــد لــي أي ســوابق وال أســتعمل أي نــوع مــن املخــدرات وأن‬\n      ‫إقدامــي علــى هــذا الفعــل هــو حاجتــي املاســة للمــال حيــث ال يوجــد لــدي‬\n      ‫أي دخــل مــادي ولــدي أســرة مكونــة مــن ثمانيــة أشــخاص وأنــا نــادم‬\n      ‫علــى هــذا الفعــل الــذي قمــت بــه هــذا إقــراري عليــه أوقــع واهلل املوفــق)‬\n      ‫أ‪.‬ه ـ املقــر مبــا فيــه ‪ ......‬بصمتــه شــاهد ‪ ......‬توقيعــه شــاهد ‪ ......‬توقيعــه‬\n      ‫وجــرى منــا االطــاع علــى الدليــل الثانــي مــن أدلــة املدعــي العــام وهــو‬\n      ‫محضــر الضبــط املــدون علــى اللفــة رقــم (‪ )5‬ونــص احلاجــة منــه (محضــر‬\n      ‫ضبــط رقــم (‪ )40‬بتاريــخ ‪1430/4/29‬ه ـ وصفــا كامــا لكيفيــة‬\n      ‫الضبــط‪ :‬بقــدوم الســيارة بقيــادة مالكهــا ‪ ......‬ويرافقه أطفاله وعددهم‬\n      ‫اثنــان ولــدى إجــراء التفتيــش اشــتبه املفتــش اجلمركــي بخــزان الوقــود‬\n      ‫األساســي ولــدى إنزالــه وفتحــه تبــن أنــه مقســوم مــن الداخــل إلــى‬\n      ‫قســمني اجلــزء األصغــر مخصــص للوقــود واآلخــر مخبــأ فيــه كميــة مــن‬\n      ‫احلبــوب التــي يشــتبه أنهــا إفيتامــن وهــي دائريــة علــى أحــد جوانبهــا‬\n      ‫قوســن واجلانــب اآلخــر خــط مســتقيم بلــغ عددهــا مائتــن وتســعة آالف‬\n      ‫ومائــة وعشــر حبـ‪ 209110‬ــات موزعــة علــى أكيــاس بالســتيكية‬\n      ‫عددهــا مائــة وأربعــة وثمانــن كيـ‪ 184‬ــسا علــى النحــو التالــي (ثمانيــة‬\n      ‫عشــر كيـ‪ 18‬ــسا عليــه صــورة إشــارة لكــزس يف كل كيــس ألفــن‬\n      ‫وخمســن حبـ‪ 2050‬ــة لونهــا بيــج) (ســتة أكيـ‪ 6‬ــاس عليهــا صــورة متســاح‬\n\n\n‫‪101‬‬\n\f‫يف كل كيــس ألفــن وخمســة وثالثــن حبـ‪ 2035‬ــة لونهــا بنــي فــاحت)‬\n‫(مائــة وســبع وأربعــن كيـ‪ 147‬ــسا عليهــا صــورة إشــارة لكــزس يف‬\n‫كل كيــس ألــف حبـ‪ 1000‬ــة لونهــا أصفــر فاحت))أ‪.‬ه ـ الضابــط‬\n‫والضابطــون ‪ ......‬توقيعــه ‪ ......‬توقيعــه ‪ ......‬توقيعــه ‪ ......‬توقيعــه وجــرى‬\n‫منــا االطــاع علــى الدليــل الثالــث مــن أدلــة املدعــي العــام وهــو التقريــر‬\n‫الكيميائــي الشــرعي املــدون علــى اللفــة رقــم (‪ )14‬ونــص احلاجــة منــه‬\n‫(تقريــر كيميائــي شــرعي رقــم (‪ ) ......‬بالفحــص الكيميائــي الشــرعي‬\n‫حملتويــات احلــرز املرســل واملنــوه انــه صنــدوق خشــبي مرصــص يحــوى‬\n‫عــدد خمســة عشــر حبــة كالتالــي‪( :‬خمــس حبــات لونهــا أصفــر فــاحت)‬\n‫(خمــس حبــات لونهــا بنــي فــاحت) (خمــس حبــات لونهــا بيــج) ثبــت لدينــا‬\n‫اآلتي‪ :‬املرســل عبارة عن صندوق خشــبي بداخله خمســة عشــر حبـ‪ 15‬ــة‬\n‫كالتالــي ‪ -1‬كيــس بالســتيك شــفاف يحــوي خمــس حبـ‪ 5‬ــات مصفــرة‬\n‫اللــون ثبــت إيجابيــة العينــة لألمفيتامــن ‪ -2‬كيــس بالســتيك شــفاف‬\n‫يحــوي خمــس حبـ‪ 5‬ــات بنيــة اللــون ثبــت إيجابيــة العينــة لألمفيتامــن ‪-3‬‬\n‫كيــس بالســتيك شــفاف يحــوي خمــس حبـ‪ 5‬ــات بيــج اللون ثبــت إيجابية‬\n‫العينــة لألمفيتامــن هــذا وقــد اســتهلكت العينــة خــال الفحص)أ‪.‬ه ـ‬\n‫وبعــرض أدلــة املدعــي العــام علــى املدعــى عليــه أجــاب قائــا مــا ذكــره‬\n‫املدعــي العــام يف دليلــه األول وهــو إقــراري املصــدق شــرعا غيــر صحيــح‬\n‫وقــد أخــذ منــي بالقــوة وال بينــة لــي علــى ذلــك ومــا ذكــره املدعــي العــام‬\n‫يف دليلــه الثانــي وهــو محضــر الضبــط فصحيــح ومــا ذكــر املدعــي‬\n‫العــام يف دليلــه الثالــث وهــو التقريــر الكيميائــي الشــرعي فــا أعلــم‬\n‫عنــه شــيئا هكــذا أجــاب وجــرى ســؤال املدعــي العــام واملدعــى عليــه‬\n‫هــل لديهمــا مــا يريــدان إضافتــه يف هــذه القضيــة أجــاب املدعــى عليــه‬\n\n\n                                                                                       ‫‪102‬‬\n\f      ‫قائــا إننــي رجــل يتيــم ليــس عنــدي أب وال أم وال إخــوة ولــدي أســرة‬\n      ‫مكونــة مــن تســعة أطفــال وليــس لهــم عائــل بعــد اهلل إال أنــا ومــن فتــرة‬\n      ‫بقائــي يف الســجن وحتــى تاريخــه لــم يذهبــوا أوالدي إلــى املدرســة وليــس‬\n      ‫لــي عالقــة بعمليــة التهريــب هــذه وأطلــب مــن فضيلتكــم النظــر يف‬\n      ‫حالــي هكــذا أجــاب وأجــاب املدعــي العــام ليــس لــدي ســوى مــا قدمــت‬\n      ‫وأطلــب احلكــم يف هــذه القضيــة هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واإلجابــة وإلنــكار املدعــى عليــه مــا جــاء يف دعــوى املدعــي‬\n      ‫ا وإلقــرار املدعــي العــام أن بينتــه علــى صحــة دعــواه‬ ‫العــام جملــة وتفصيـ ً‬\n      ‫هــي اعتــراف املدعــى عليــه املصــدق شــرع ًا واملتضمــن صحــة مــا ذكــره‬\n      ‫املدعــي العــام يف دعــواه وإلنــكار املدعــى عليــه هــذا االعتــراف جملــة‬\n      ‫وتفصيــا ودفعــه بأنــه أخــذ منــه بالقــوة وال بينــة لــه علــى ذلــك وألن‬\n      ‫الرجــوع عــن اإلقــرار مبــا يوجــب التعزيــر ال يقبــل كمــا جــاء ذلــك يف‬\n      ‫كتــاب املغنــي البــن قدامــة رحمــه اهلل ‪ 469/4‬ونــص احلاجــة منــه (وال‬\n      ‫يقبــل رجــوع املقــر عــن إقــراره إال فيمــا كان حــدا هلل تعالــى يــدرأ‬\n      ‫بالشــبهات‪ -‬ويحتــاط إلســقاطه فأمــا حقــوق اآلدميــن وحقــوق اهلل‬\n      ‫تعالــى التــي ال تــدرأ بالشــبهات كالــزكاة والكفــارات‪ -‬فــا يقبــل‬\n      ‫رجوعــه عنهــا وال نعلــم يف هــذا خالفــا )أ‪.‬ه ـ ولقولــه تعالــى يف ســورة‬\n      ‫املائــدة آيــة رقــم (‪( )33‬إمنــا جــزاء الذيــن يحاربــون اهلل ورســوله ويســعون‬\n      ‫يف األرض فســاد ًا أن يقتلــوا أو يصلبــوا أو تقطــع أيديهــم وأرجلهــم مــن‬\n      ‫خــاف) اآليــة وملــا جــاء يف كشــاف القنــاع(‪ )120/14‬مانصه(ويكــون‬\n      ‫التعزيــر بالضــرب واحلبــس والصفــع والتوبيــخ والعــزل عــن الواليــة وقــال‬\n      ‫يف االختيــارات إذا كان املقصــود دفــع الفســاد ولــم يندفــع إال بالقتــل‬\n      ‫قتــل وحينئــذ فمــن تكــرر منــه جنــس الفســاد ولــم يرتدع باحلــدود املقدرة‬\n\n\n‫‪103‬‬\n\f‫بــل اســتمر علــى الفســاد فهــو كالصائــل ال يندفــع إال بالقتــل فيقتل)أ‪.‬ه ـ‬\n‫وجــاء فيــه أيضــا صفحــة رقــم(‪ )120‬مانصه(وقــال الشــيخ يعــزر أي مــن‬\n‫وجــب عليــه التعزيــر مبــا يردعــه ألن القصــد الــردع وقــد يقــال بقتلــه أي‬\n‫مــن لزمــه التعزيــر للحاجة)أ‪.‬ه ـ وملــا جــاء يف قــرار هيئــة كبــار العلمــاء‬\n‫رقــم( ‪ ) 138‬الصــادر عــن مجلــس هيئــة كبــار العلمــاء يف دورتــه التاســعة‬\n‫والعشــرين املنعقــدة مبدينة الريــاض بتأريخ‪1407 /6/9‬هـ وحتى‪/6/20‬‬\n‫‪1407‬ه ـ واملتضمــن قتــل مهــرب املخــدرات داخــل اململكــة إذا رأى‬\n‫حــكام القضيــة ذلــك والــذي جــاء فيــه (أوال بالنســبة ملهــرب املخــدرات‬\n‫فــإن عقوبتــه القتــل ملــا يســببه تهريــب املخــدرات وإدخالهــا البــاد مــن‬\n‫فســاد عظيــم ال يقتصــر علــى املهــرب نفســه وأضــرار جســيمة وأخطــار‬\n‫بليغــة علــى األمــة مبجموعهــا ويلحــق باملهــرب الشــخص الــذي يســتورد أو‬\n‫يتلقــى املخــدرات مــن اخلــارج فيمـ ّـون بهــا املروجني)أ‪.‬ه ـ وملــا نصــت عليــه‬\n‫املــادة الســابعة والثالثــن مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم(م‪)37‬يف ‪1426/7/8‬ه ـ الفقــرة‬\n‫األولى(أوالً‪:‬مــع مراعــاة مــا ورد يف البنــد (ثانيـاً) مــن هــذه املــادة يعاقــب‬\n‫بالقتــل تعزيــرا مــن ثبــت شــرعا بحقــه شــيء مــن األفعــال اآلتيــة‪-1:‬‬\n‫تهريــب مــواد مخــدرة أو مؤثــرات عقلية)أ‪.‬ه ـ ولكــون املدعــى عليــه‬\n‫مكلفــا لذلــك كلــه فقــد حكمنــا مبــا يلــي أوال‪ :‬إثبــات مــا أســند إلــى‬\n‫املدعــى عليــه ‪ ......‬مــن قيامــه بتهريــب الكميــة املذكــورة يف دعــوى‬\n‫املدعــي العــام ثانيــا‪ :‬حكمنــا بقتلــه تعزيــر ًا ثالثــا‪ :‬مصــادرة ســيارته‬\n‫وجوالــه املوصوفــن يف الدعــوى وبذلــك حكمنــا وبعــرض احلكــم علــى‬\n‫املدعــى عليــه قــرر اعتراضــه عليــه وطلــب اســتئنافه مــع تقــدمي الئحــة‬\n‫اعتراضيــة فســلم لــه صــورة مــن صــك احلكــم يف هــذه اجللســة بتاريــخ‬\n\n\n                                                                                       ‫‪104‬‬\n\f      ‫‪1434/7/25‬ه ـ وأفهمنــاه بــأن لــه مــدة أقصاهــا ثالثــون يومــا مــن تاريــخ‬\n      ‫اســتالمه لصــورة الصــك فــإذا انقضــت املــدة ولــم يقــدم اعتراضــه‬\n      ‫فيســقط حقــه يف االعتــراض وســيتم رفــع كامــل املعاملــة إلــى مقــام‬\n      ‫محكمــة االســتئناف املوقــرة لدراســة احلكــم وتدقيقــه حســب املتبــع‬\n      ‫ففهــم ذلــك ولــم جنــد حاجــة لعــرض احلكــم علــى املدعــي العــام ألنــه‬\n      ‫حكــم لــه بــكل طلباتــه بنــاء علــى املــادة (‪ )174‬مــن نظــام املرافعــات‬\n      ‫الشــرعية ولوائحــه التنفيذيــة واختتمــت اجللســة يف متــام الســاعة احلاديــة‬\n      ‫عشــرة وللبيــان حــرر يف ‪1434/7/25‬ه ـ وصلــى اهلل وســلم علــى نبينــا‬\n      ‫محمــد‪ .‬احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪،‬‬\n                                                                               ‫وبعد ‪-:‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلماســية الثانيــة‬\n      ‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بتبــوك برقــم‪341175324‬‬\n      ‫وتاريــخ ‪1434/9/1‬ه ـ املرفــق بهــا الصــك رقــم ‪ 34279643‬وتاريــخ‬\n      ‫‪1434/7/25‬ه ـ الصــادر مــن أصحــاب الفضيلــة القضــاة باحملكمــة‬\n      ‫العامــة بتبــوك الشــيخ‪ ...... /‬والشــيخ‪ ...... /‬والشــيخ‪ ...... /‬املتضمــن‬\n      ‫دعــوى املدعــي العــام ضــد‪ ...... /‬املتهــم بتهريــب كميــة مــن حبــوب‬\n      ‫األمفيتامــن املنبــه للجهــاز العصبــي احملظــورة البالــغ عددهــا مائتــن‬\n      ‫وتســعة آالف ومائــة وعشــر حبــات ‪ ،‬احملكــوم فيــه بقتــل املدعــى عليــه‬\n      ‫تعزيــر ًا و مصــادرة ســيارته وجوالــه‪ .‬وبدراســة احلكــم وصــورة ضبطــه‬\n      ‫والئحتــه االعتراضيــة تقــرر باالكثريــة املوافقــة علــى احلكــم ‪ .‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪،،،‬‬\n\n\n\n‫‪105‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":94,"source_page_end":105,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3daeb0466fcd1676ae7184e3c2b36247da4bb56ad8e84c6517307069eca3a333","normalized_text_hash":"91802c4ec4fb5f0ea2325c89e234c8d6fd0d0342bfeaecfdee6bc77aaa3e8fd0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p94-34279643"},{"id":"45c41e35-34cc-5678-b02d-29e4fc534494","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -االشتراك يف تهريب القات -تعاطي القات -اإلقرار باملشاركة يف نقل القات وتعاطيه -تعزير بالسجن واجللد ومصادرة اجلواالت -صرف النظر عن طلب املدعي العام مصادرة السيارة املستخدمة يف اجلرمية.","document_number":"34280698","case_number":"34265411","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/26","year":"1434","subject":"مخدرات -االشتراك يف تهريب القات -تعاطي القات -اإلقرار باملشاركة يف نقل القات وتعاطيه -تعزير بالسجن واجللد ومصادرة اجلواالت -صرف النظر عن طلب املدعي العام مصادرة السيارة املستخدمة يف اجلرمية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34280698 :‬تاريخه‪1434/7/26 :‬هـ‬\n                   ‫رقم الدعوى‪34265411 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34324713‬تاريخه‪1434/9/23 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬االشــتراك يف تهريــب القــات‪ -‬تعاطــي القــات‪ -‬اإلقــرار‬\n‫باملشــاركة يف نقــل القــات وتعاطيــه ‪ -‬تعزيــر بالســجن واجللــد‬\n‫ومصــادرة اجلــواالت‪ -‬صــرف النظــر عــن طلــب املدعــي العــام مصــادرة‬\n                                     ‫الســيارة املســتخدمة يف اجلرميــة‪.‬‬\n\n\n\n\n                        ‫‪ -‬األمر امللكي رقم ‪ 59633‬وتاريخ ‪1432/12/9‬هـ‬\n‫‪ -‬املــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬الصــادر يف ســنة‬\n                                                                    ‫‪1374‬ه ـ‬\n‫‪ -‬املــادة الثالثــة مــن قــرار ســمو وزيــر الداخليــة رقــم ‪ 2057‬وتاريــخ‬\n                                                             ‫‪1404/5/26‬هـ‬\n\n\n\n\n‫انتهــى التحقيــق مــع املدعــى عليهمــا إلــى توجيــه االتهــام إليهمــا‬\n‫باالشــتراك بنقــل (‪ )212‬حزمــة مــن القــات املخــدر بلــغ وزنهــا جميع ـ ًا‬\n‫تســعة وأربعــون كيلــو وثــاث مئــة وســتة وتســعون جــرام مــن نبــات‬\n‫القــات املخــدر‪ ،‬واســتخدام املدعــى عليــه الثانــي للقــات املخــدر‪ ،‬وذلــك‬\n‫بعــد ورود بــاغ للجهــة املختصــة يفيــد أن هنــاك شــخصني يقومــان‬\n‫بنقــل كميــة مــن القــات املخــدر وأن املدعــى عليــه الثانــي يقــوم مبســح‬\n\n                                                                                 ‫‪106‬‬\n\f      ‫الطريــق للمدعــى عليــه األول فتــم القبــض علــى املدعــى عليــه الثانــي‬\n      ‫وبتفتيشــه لوحــظ عليــه االرتبــاك وأنكــر معرفتــه بــاألول‪ ،‬ثــم مت القبــض علــى‬\n      ‫املدعــى عليــه األول وبتفتيــش الســيارة عثــر بداخلهــا علــى احلــزم املذكــورة ‪،‬‬\n      ‫أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة ملــادة نبــات القــات‬\n      ‫املخــدر ‪،‬طلــب املدعــي احلكــم عليهمــا بعقوبــة تعزيريــة ومعاقبــة الثانــي‬\n      ‫لقــاء اســتخدامه القــات املخــدر ومصــادرة جــواالت املدعــى عليهمــا‪،‬‬\n      ‫ومصــادرة الســيارة املســتخدمة يف اجلــرمي والعائــدة ملكيتهــا للمدعــى‬\n      ‫عليــه الثانــي ‪،‬وصــادق املدعــى عليهمــا علــى مــا هــو منســوب إليهمــا‪،‬‬\n      ‫وبنــاء علــى مــا تقــدم حكمــت احملكمــة بصــرف النظــر عــن طلــب‬\n      ‫املدعــي العــام مبطالبتــه مبصــادرة الســيارة وســجن املدعــى عليــه األول‬\n      ‫ثمانيــة أشــهر مــن دخولــه الســجن وجلــده خمســن جلــدة تكــرر عليــه‬\n      ‫ثــاث مــرات وســجن املدعــى عليــه الثانــي ســنة وجلــده خمســن جلــده‬\n      ‫تكــرر عليــه أربــع مــرات وذلــك لقــاء اشــتراكهما يف نقــل نبــات القــات‬\n      ‫املخــدر ويدخــل يف ذلــك مجــازاة املدعــى عليــه الثانــي علــى تعاطــي نوعهــا‬\n      ‫ومصــادرة جــواالت املدعــى عليهــم ‪،‬وبعــرض احلكــم علــى املدعــى‬\n      ‫عليهمــا قــررا القناعــة باحلكــم كمــا قــرر املدعــي العــام اعتراضــه علــى‬\n      ‫احلكــم وطلــب رفعهــا حملكمــة االســتئناف بالئحــة اعتراضيــه‪ ،‬وبعــد‬\n                       ‫رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬مســاعد رئيــس احملكمــة العامــة‬\n      ‫مبحافظــة اخلرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة اخلرمــة برقــم ‪ 34265411‬وتاريــخ‬\n‫‪107‬‬\n\f‫‪1434/06/10‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341395241‬وتاريــخ‬\n‫‪1434/6/10‬ه ـ ففــي يــوم االثنــن املوافق‪1434/07/17‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 08 : 00‬وفيهــا حضــر املدعــي العــام بدائــرة هيئــة‬\n‫التحقيــق واالدعــاء العــام مبحافظــة اخلرمــة‪ ....../‬مبوجــب خطــاب‬\n‫التكليــف رقــم ‪ ......‬يف‪1434/1/11‬ه ـ وقــدم دعــواه اخلطيــة قائــا فيهــا‬\n‫بصفتــي عضــو هيئــة التحقيــق واالدعــاء العــام بدائــرة محافظــة اخلرمــة‬\n‫أدعــي علــى‪1/‬ـ ‪ 39 ......‬عام ـ ًا ‪ ،‬ســعودي اجلنســية ‪ ،‬مبوجــب الســجل‬\n‫املدنــي رقــم (‪ ) ......‬متــزوج ‪ ،‬متعلــم ‪ ،‬عســكري ‪ ،‬موقــوف بســجن‬\n‫محافظــة اخلرمــة مبوجــب أمــر التوقيــف رقــم (‪ ......‬س) بتاريــخ‬\n‫‪1434/4/1‬هـ ـ اســتنادا للقــرار الــوزاري رقــم (‪ )1900‬يف‪1428/7/9‬ه ـ‬\n‫املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‪2 .‬ـ ‪28 ......‬‬\n‫عامـاً‪ ،‬ســعودي اجلنســية‪ ،‬مبوجــب الســجل املدنــي رقــم (‪ ) ......‬متســبب‪،‬‬\n‫متــزوج ‪،‬موقــوف بســجن محافظــة اخلرمــة مبوجــب أمــر التوقيــف رقــم‬\n‫(‪ )......‬بتاريــخ ‪1434/4/1‬هـ ـ اســتنادا للقــرار الــوزاري رقــم (‪ )1900‬يف‬\n‫‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‪.‬‬\n‫إنــه بتاريــخ ‪1434/3/27‬ه ـ ورد خطــاب مكافحــة املخــدرات رنيــة رقــم‬\n‫‪ ......‬يف ‪1434/3/27‬ه ـ إلــى وحــدة مكافحــة املخــدرات مبحافظــة‬\n‫اخلرمــة تفيــد أن هنــاك شــخصني يقومــون بنقــل كميــة مــن القــات‬\n‫املخــدر مــن املنطقــة اجلنوبيــة مــرور ًا مبحافظــة رنيــة ـ ـ اخلرمــة وأن املدعى‬\n‫عليــه الثانــي يقــوم مبســح الطريــق للمدعــى عليــه األول ومت القبــض علــى‬\n‫املدعــى عليــه الثانــي وبتفتيشــه لوحــظ عليــه االرتبــاك وأنكــر معرفتــه‬\n‫بــاألول ومت تشــكيل فرقــة ميدانيــة واالنتقــال للخــط الســريع املــؤدي‬\n‫حملافظــة رنيــة اخلرمــة وجــرى عمــل عــدة كمائــن متفرقــة وعنــد‬\n\n\n                                                                                        ‫‪108‬‬\n\f      ‫اســتيقاف إحــدى الســيارات القادمــة مــن جهــة محافظــة رنيــة وهــي مــن‬\n      ‫نــوع موديــل (‪ )2011‬لوحــة رقــم ‪ ......‬بيضــاء اللــون بداخلهــا شــخص‬\n      ‫وبرفقتــه امــرأة وبطلــب إثباتــه ظهــرت عليــه عالمــات االرتبــاك وأفــاد‬\n      ‫انــه يدعــى ‪ ......‬وبطلــب إثبــات العائلــة اتضــح أنــه يدعــى ‪ ......‬وبرفقتــه‬\n      ‫املواطنــة ‪ ......‬واتضــح إن املــرأة هــي زوجتــه كمــا يتضــح مــن كــرت‬\n      ‫العائلــة وبتفتيــش الســيارة وجــد بداخلهــا وحتديــد ًا داخــل األبــواب‬\n      ‫األربعــة‪ ،‬وداخــل املقعــد اخللفــي وداخــل ديكــور القيــر والطبلــون ‪ ،‬عثــر‬\n      ‫علــى عــدد (‪ )212‬حزمــة مــن نبــات القــات املخــدر بلــغ وزنهــا اإلجمالــي‬\n      ‫‪49,396‬كجــم تســعه وأربعــون كيلــو وثــاث مئــة وســتة وتســعون جــرام‬\n      ‫مــن نبــات القــات املخــدر‪ ،‬وقــد اثبــت التقريــر الكيميائــي الشــرعي‬\n      ‫رقــم (‪ )......‬بتاريــخ ‪1434/4/23‬ه ـ إيجابيــة العينــة مبــا مت ضبطــه مــع‬\n      ‫املدعــى عليــه األول ملــادة نبــات القــات املخــدر وهــي مــن املــواد املدرجــة‬\n      ‫بجــدول املــواد املخــدرة امللحقــة بنظــام مكافحــة املخــدرات املرفقــة‬\n      ‫بالتعميــم البرقــي لصاحــب الســمو امللكــي وزيــر الداخليــة رقــم‬\n      ‫(‪)89400/19‬يف ‪1426/10/25‬ه ــ‪ .‬وبســماع أقــوال املدعى عليه األول‪/‬‬\n      ‫اقــر أنــه اتفــق مــع املدعــي عليــه الثانــي بنقــل كميــة القــات املخــدر إلــى‬\n      ‫الريــاض مقابــل مبلــغ مالــي قــدرة عشــرة اآللــف ريــال‪ .‬وبســماع أقــوال‬\n      ‫املدعــى عليــه الثانــي‪ /‬اقــر أن القــات الــذي مت ضبطــه يعــود لــه وقــد قــام‬\n      ‫بإخفائــه بســيارته وإعطائهــا للمدعــي عليــه األول لتوصيلهــا مقابــل‬\n      ‫عشــرة أالف ريــال وإنــه يقــوم مبتابعتهــم ومســح الطريــق علــى ســيارة‬\n      ‫أخــرى‪ .‬وقــد انتهــى التحقيــق معهما إلى توجيه االتهام إليهما باالشــتراك‬\n      ‫بنقــل (‪ )212‬حزمــة مــن القــات املخــدر بلــغ وزنهــا جميعاً(‪ )49,396‬تســعة‬\n      ‫وأربعــون كيلــو وثــاث مئــة وســتة وتســعون جــرام مــن نبــات القــات‬\n\n\n‫‪109‬‬\n\f‫املخــدر‪ ،‬واســتخدام املدعــى عليــه الثانــي للقــات املخــدر وذلــك لألدلــة‬\n‫والقرائــن التاليــة‪ -1/‬مــا ورد بإقرارهمــا املصــدق شــرعا املنــوه عنــه‬\n‫مبلــف التحقيــق صفحــة رقــم (‪ )20‬لفــه رقــم (‪ )1‬وصفحــة رقــم (‪)8 ،7‬‬\n‫لفــه رقــم (‪-2 .)2‬التقريــر الكيميائــي الشــرعي رقــم (‪ ......‬بتاريــخ‬\n‫‪1434/4/23‬ه ـ لفــه (‪ -3 .)36‬شــهادة الشــهود الــواردة يف محضــر‬\n‫القبــض املــدون مبلــف التحقيــق صفحــة رقــم (‪ )11،12،13‬لفــه (‪.)1‬‬\n‫وباالطــاع علــى ســوابقهما لــم يعثــر للمدعــى عليــه األول علــى ســوابق‬\n‫وعثــر علــى املدعــى عليــه الثانــي علــى ســابقة حيــازة قــات لــذا اطلــب‬\n‫اثبــات مــا أســند إليهمــا واحلكــم عليهــم باالتــي ‪ -1 /‬إثبــات إدانتهمــا‬\n‫باالشــتراك بنقــل مــا وزنــه (‪ ) 49,396‬جــرام مــن نبــات القــات احملظــور‬\n‫واحلكــم عليهمــا بعقوبــة تعزيريــة وفقـ ًا للمــادة الرابعــة مــن قــرار مجلــس‬\n‫الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ اســتناد ًا لألمــر الســامي الكــرمي رقــم‬\n‫(‪ )59633‬يف ‪1432/12/9‬ه ـ ومعاقبــة الثانــي بعقوبــة تعزيريــة لقــاء‬\n‫اســتخدامه القــات املخــدر‪ -2‬مصــادرة جــوال املدعــي عليــة األول رقــم‬\n‫(‪ ) ......‬يحمــل الرقــم التسلســلي ‪ ) ......‬ومصــادرة جــوال املدعــي عليــة‬\n‫الثانــي رقــم ( ‪ ) ......‬يحمــل الرقــم التسلســلي (‪ ) ......‬وكذلــك جوالــه‬\n‫الثانــي رقــم (‪ ) ......‬يحمــل الرقــم التسلســلي رقــم (‪ -3 .) ......‬مصــادرة‬\n‫الســيارة املســتخدمة يف اجلرميــة وهــي مــن نــوع ‪ .....‬موديــل (‪ )2011‬لوحــة‬\n‫رقــم (‪ ) ......‬ابيــض اللــون والعائــد ملكيتهــا للمدعــى عليــة الثانــي ‪.‬هــذه‬\n‫دعــواي‪ .‬وبســؤال املدعــى عليــه األول عمــا ورد يف دعــوى املدعــي العــام‬\n‫ا مــا ذكــره املدعــي العــام يف دعــواه مــن اتفاقــي مــع املدعــى‬  ‫أجــاب قائـ ً‬\n‫عليــه الثانــي علــى نقــل كميــة القــات املذكــور يف الدعــوى علــى ســيارته‬\n‫وكونــي علــى علــم بذلــك وذلــك مقابــل مبلــغ مالــي وقــدره عشــرة اآلف‬\n\n\n                                                                                       ‫‪110‬‬\n\f      ‫ريــال فهــذا كلــه صحيــح هكــذا أجــاب‪ .‬كمــا جــرى ســؤال املدعــى‬\n      ‫ا مــا ذكــره املدعــي العــام يف دعــواه مــن‬   ‫عليــه الثانــي فأجــاب قائ ـ ً‬\n      ‫اشــتراكي بنقــل كميــة القــات املذكــورة يف الدعــوى فهــذا كلــه‬\n      ‫صحيــح فقــد قمــت بإخفائــه بســيارتي وإعطائــه للمدعــى عليــه األول‬\n      ‫لتوصيلــه إلــى منطقــة الريــاض مقابــل مبلــغ مالــي وقــدره عشــرة اآلف‬\n      ‫ريــال وأنــا أقــوم مبتابعتــه ومســح الطريــق لــه علــى ســيارة أخــرى هكــذا‬\n      ‫أجــاب‪ .‬ثــم جــرى االطــاع علــى أوراق املعاملــة فوجــدت إقــرار املدعــى‬\n      ‫عليــه حتقيقــا علــى اللفــة(‪ )1‬صفحــة رقــم(‪ )19-18‬مــن ملــف التحقيــق‬\n      ‫املتضمــن إقــرار املدعــى عليــه االول بنقــل (‪ )212‬مائتــن واثنــا عشــر‬\n      ‫حزمــة قــات بلــغ وزنهــا (‪ )49.396‬كجــم تســعة وأربعــون كيلــو‬\n      ‫وثالثمائــة وســتة وتســعون جرام ـ ًا مــن نبــات أخضــر اللــون يشــتبه أن‬\n      ‫يكــون مــن نبــات القــات املخــدر وهــي عائــدة للمدعــى عليــه الثانــي‬\n      ‫كمــا جــرى االطــاع علــى إقــرار املدعــى عليــه الثانــي حتقيق ـ ًا علــى‬\n      ‫اللفــة(‪ )2‬صفحــة رقــم (‪ )6-5‬املتضمــن إقــرار املدعــى عليــه الثانــي بورود‬\n      ‫اتصــال إليــه مــن املدعــو ‪ ......‬يف مدينــة الريــاض بحضــور شــخص إلــى‬\n      ‫منزلــه معــه كميــة مــن القــات املخــدر وطلــب منــه إخفائهــا يف ســيارته‬\n      ‫وإيصالهــا إلــى مدينــة الريــاض مببلــغ مــادي وهــو عشــرة اآلف ريــال‬\n      ‫للســائق الــذي يقــوم بنقــل الكميــة وعشــرة ريــاالت للقــرف (احلزمــة)‬\n      ‫الواحــدة بينــه وبــن املتصــل ثــم قــام باالتفــاق مــع املدعــى عليــه األول‬\n      ‫بإيصالهــا كمــا وجــدت التقريــر الكيميائــي الشــرعي رقــم (‪)......‬‬\n      ‫يف‪1434/4/23‬ه ـ علــى اللفــة (‪ )36‬املتضمــن ايجابيــة العينــة املضبوطــة‬\n      ‫مــع املدعــى عليــه ملــادة نبــات القــات املخــدر كمــا جــرى االطــاع علــى‬\n      ‫ســوابق املدعــى عليهمــا ولــم يعثــر للمدعــى عليــه األول علــى ســوابق وعثر‬\n\n\n‫‪111‬‬\n\f‫للمدعــى عليــه الثانــي علــى ســابقة حيــازة قــات‪ .‬فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة وإلقــرار املدعــى عليــه األول بنقــل كميــة القــات‬\n‫املخــدر إلــى مدينــة الريــاض مقابــل مبلــغ مالــي وقــدره عشــرة اآلف‬\n‫وإقــرار املدعــى عليــه الثانــي باشــتراكه بنقــل القــات التــي مت ضبطهــا‬\n‫مــع املدعــى عليــه األول وقيامــه بإخفائــه بســيارته وإعطائــه للمدعــى‬\n‫عليــه األول لتوصيلــه إلــى منطقــة الريــاض مقابــل مبلــغ مالــي وقــدره‬\n‫عشــرة اآلف ريــال وقيامــه مبتابعتــه ومراقبــة الطريــق لــه علــى ســيارة‬\n‫أخــرى وملــا ورد يف الدعــوى ونظــرا ملــا تضمنــه التقريريــن الكيميائيــن‬\n‫الشــرعيني املشــار إليهمــا أعــاه ونظــرا ألن املدعــى عليهمــا يســتحقان‬\n‫العقوبــة طبق ـ ًا للقواعــد الشــرعية واألنظمــة املرعيــة وملــا قــرره املدعــى‬\n‫عليهمــا واســتنادا لألمــر امللكــي رقــم ‪ 59633‬وتاريــخ ‪1432/12/9‬ه ـ‬\n‫املتضمــن املوافقــة علــى إخــراج نبــات القــات مــن العقوبــات املنصــوص‬\n‫عليهــا يف نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واالســتمرار يف‬\n‫معاملتــه وفــق العقوبــات الســائدة قبــل الشــروع يف تطبيــق النظــام‬\n‫واســتناد ًا للمــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬الصــادر يف‬\n‫ســنة ‪1374‬ه ـ واملــادة الثالثــة مــن قــرار ســمو وزيــر الداخليــة رقــم ‪2057‬‬\n‫وتاريــخ ‪1404/5/26‬ه ـ وحيــث ال ســوابق لــدى املدعــى عليــه االول وملــا‬\n‫يفهــم مــن منطــوق االمــر امللكــي املتضمــن اخــراج نبــات القــات مــن نظام‬\n‫مكافحــة املخــدرات ان املقصــود عــدم مســاواتها بالعقوبــات املقــررة‬\n‫علــى جرائــم املخــدرات والتوجــه الــى مــا هــو اقــل منهــا وملــا ظهــر لــي مــن‬\n‫نــدم املدعــى عليهمــا وظهــور عالمــات التوبــة عليهمــا وحيــث لــم ينــص يف‬\n‫العقوبــات الســائدة قبــل تطبيــق نظــام املخــدرات الــذي جــرى الرجــوع‬\n‫الــى العمــل بــه حاليــا علــى مصــادرة وســائل النقــل ولكــون املقصــود مــن‬\n\n\n                                                                                         ‫‪112‬‬\n\f      ‫العقوبــة الــردع وليــس التشــفي لذلــك كلــه فقــد ثبــت لــدي إدانــة املدعــى‬\n      ‫عليهمــا باالشــتراك يف نقــل مــا وزنــه (‪49.396‬كجــم) تســعة وأربعــون‬\n      ‫كيلــو وثالثمائــة وســتة وتســعون جرام ـ ًا نبــات القــات املخــدر وذلــك‬\n      ‫بقيــام املدعــى عليــه الثانــي ‪ ......‬بإخفــاء الكميــة املهربــة داخــل ســيارته‬\n      ‫وتســليمها لــأول وقيامــه مبراقبــة الطريــق لــه علــى ســيارة أخــرى وقيــام‬\n      ‫املدعــى عليــه األول بقيــادة الســيارة التــي فيهــا الكميــة وهــو علــى علــم‬\n      ‫مبــا فيهــا وإدانــة املدعــى عليــه الثانــي بتعاطــي نوعهــا وقــررت مــا يلــي‪:‬‬\n      ‫أوالً‪ /‬صرفــت النظــر عــن طلــب املدعــي العــام مطالبتــه مبصــادرة‬\n      ‫الســيارة ‪ .‬ثاني ـ ًا ‪ /‬ســجن املدعــى عليــه االول ثمانيــة أشــهر مــن دخولــه‬\n      ‫الســجن وجلــده خمســن جلــدة تكــرر عليــه ثــاث مرات وســجن املدعى‬\n      ‫عليــه الثانــي ســنة وجلــده خمســن جلــدة تكــرر عليــه أربــع مــرات وذلــك‬\n      ‫لقــاء اشــتراكهما يف نقــل نبــات القــات املخــدر ويدخــل يف ذلــك مجــازاة‬\n      ‫املدعــى عليــه الثانــي علــى تعاطــي نوعهــا ثالثـاً‪ /‬مصــادرة جــوال املدعــى‬\n      ‫عليــه األول رقــم (‪ ) ......‬والــذي يحمــل الرقــم التسلســلي (‪ ) ......‬ومصادرة‬\n      ‫جــوال املدعــى عليــه الثانــي رقــم (‪ ( ......‬ويحمــل الرقــم التسلســلي (‪......‬‬\n      ‫) ‪ .‬ومبــا تقــدم حكمــت وبعــرض احلكــم علــى املدعــى عليهمــا قــرروا‬\n      ‫القناعــة باحلكــم كمــا قــرر املدعــي العــام اعتراضــه علــى احلكــم‬\n      ‫وطلــب رفعهــا حملكمــة االســتئناف بالئحــة اعتراضيــه فجــرى تســليمه‬\n      ‫نســخه مــن احلكــم لتقــدمي اعتراضــه خــال ثالثــن يــوم مــن هــذا التاريــخ‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد ختمــت اجللســة يف‬\n                                       ‫متام الساعة التاسعة حرر يف ‪71434/17‬هـ ـ ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة مبحكمــة االســتئناف‬\n\n\n‫‪113‬‬\n\f‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫القاضــي باحملكمــة العامــة باخلرمــة الشــيخ‪ ....../‬برقــم ‪342129456‬‬\n‫وتاريــخ ‪1434/9/6‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلتــه برقــم‬\n‫‪ 34280698‬وتاريــخ ‪1434/7/26‬ه ـ املتضمــن دعــوى املدعــي العــام‬\n‫ضــد‪ ....../‬ورفيقــه ‪ ،‬املتهمــن يف قضيــة قــات احملكــوم فيــه مبــا دون‬\n‫باطــن القــرار ‪.‬وبدراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة‬\n‫تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                          ‫وعلــى آلــه وصحبــه وســلم ‪،،،،،‬‬\n\n\n\n\n                                                                                   ‫‪114‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":106,"source_page_end":114,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0f88eada51e3e4735f2c59a8f36c13060b1f5bddb6859c162e5d6a9cfa63b7e0","normalized_text_hash":"5e0e3cdc4f8e1223762f562404c7cd93f706fee2e22b8bffa38bada3c7181952","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p106-34280698"},{"id":"f9d8aac6-e471-53b5-8c22-cf0d4598734e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -قات -تهريب قات بقصد االستعمال الشخصي -اإلقرار بالتهريب -قلة الكمية املضبوطة -حداثة سنه -ظروف مخففة للعقوبة -تعزير بالسجن واجللد واملنع من السفر املادة (األولى) الفقرة) ب) واملادة (اخلامسة) الفقرة (ب-ج) من قرار مجلس الوزراء رقم ( )11لعام 1374ه","document_number":"34275215","case_number":"34308056","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/22","year":"1434","subject":"مخدرات -قات -تهريب قات بقصد االستعمال الشخصي -اإلقرار بالتهريب -قلة الكمية املضبوطة -حداثة سنه -ظروف مخففة للعقوبة -تعزير بالسجن واجللد واملنع من السفر املادة (األولى) الفقرة) ب) واملادة (اخلامسة) الفقرة (ب-ج) من قرار مجلس الوزراء رقم ( )11لعام 1374ه","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34275215 :‬تاريخه‪1434/7/22 :‬هـ‬\n                         ‫رقم الدعوى‪34308056 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34318448‬تاريخه ‪1434/9/14 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬قــات ‪ -‬تهريــب قــات بقصــد االســتعمال الشــخصي‪ -‬اإلقــرار‬\n      ‫بالتهريــب ‪ -‬قلــة الكميــة املضبوطــة ‪ -‬حداثــة ســنه ‪ -‬ظــروف مخففــة‬\n                      ‫للعقوبــة ‪ -‬تعزيــر بالســجن واجللــد واملنــع مــن الســفر‬\n\n\n\n\n      ‫املــادة (األولــى) الفقــرة) ب) واملــادة (اخلامســة) الفقــرة (ب‪-‬ج) مــن قــرار‬\n                                        ‫مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه قيامــه بتهريــب تســعة وعشــرين‬\n      ‫جراما وتســعة أعشــار اجلرام من نبات القات املخدر بقصد االســتخدام‬\n      ‫الشــخصي وطلــب احلكــم علــى املدعــى عليــه بعقوبــة تعزيريــة ومنعــه‬\n      ‫مــن الســفر مبوجــب قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ‬\n      ‫وذلــك أثــر القبــض علــى املدعــى عليــه وتفتيــش ســيارته عثــر بداخــل‬\n      ‫شــنطتها كميــة يشــتبه أن تكــون مــن نبــات القــات ‪ -‬أثبــت التقريــر‬\n      ‫الكيميائــي الشــرعي الصــادر إيجابيــة العينــة لنبــات القــات املخــدر‬\n      ‫ا ‪،‬وحيــث‬  ‫صــادق املدعــى عليــه علــى دعــوى املدعــي العــام جملــة وتفصيـ ً‬\n      ‫إن الكميــة املضبوطــة مــع املدعــى عليــه قليلــة جــدا‪ ،‬وقــد أبــدى أســفه‬\n      ‫وندمــه علــى ذلــك‪ ،‬وحلداثــة ســنه واســتصالح ًا حلالــه‪ ،‬فقــد مت احلكــم‬\n\n‫‪115‬‬\n\f‫بتعزيــره بســجنه ملــدة شــهرين وجلــده أربعــن جلــدة دفعــة واحــدة ومنعــه‬\n‫مــن الســفر خــارج البــاد ملــدة ســنة واحــدة تبــدأ بعــد انتهــاء مــدة تنفيــذ‬\n‫عقوبــة الســجن وبعــرض احلكــم علــى املدعــى عليــه قــرر اعتراضــه علــى‬\n‫احلكــم بالئحــة اعتراضيــة وقــرر املدعــي العــام اعتراضــه علــى احلكــم‬\n             ‫بــدون الئحــة‪ ،‬صدقــت محكمــة االســتئناف علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بنجــران برقــم ‪ 34308056‬وتاريــخ ‪ 1434/07/04‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 341612700‬وتاريــخ ‪ 1434/7/4‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق‪ 1434/07/22‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 15‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ ......‬مبوجــب التكليــف الصــادر مــن هيئــة‬\n‫التحقيــق واالدعــاء العــام بنجــران رقــم ‪ ......‬بتاريــخ ‪1430/12/29‬ه ـ‬\n‫وادعــى علــى احلاضــر معــه يف مجلــس احلكــم ‪ ......‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ......‬قائــا يف دعــواه عليــه بتهريــب (‪)29,9‬‬\n‫تســعة وعشــرين جــرام وتســعة أعشــار اجلــرام مــن نبــات القــات املخــدر‬\n‫بقصــد االســتخدام الشــخصي‪ 0‬حيــث ورد مبحضــر القبــض والتفتيــش‬\n‫املعــد مــن قبــل منفــذ جمــرك اخلضــراء بنجــران رقــم (‪ )12‬أنــه بتاريــخ‬\n‫‪1434/6/8‬ه ـ قــدم مــن اليمــن ســيارة نــوع ‪ ........‬رقــم اللوحــة ‪ ......‬بقيــادة‬\n‫املهتــم أعــاه‪ ...... /‬وترافقــه والدتــه‪ ...... /‬وعنــد تفتيشــها عثــر بداخــل‬\n‫شــنطتها كميــة يشــتبه أن تكــون مــن نبــات القــات بلــغ وزنــه (‪)29,9‬‬\n‫جــرام ولــم تصــرح عنهــا (أخلــى ســبيلها يف احلــال لعــدم عالقتهــا مبــا‬\n\n                                                                                       ‫‪116‬‬\n\f      ‫ضبــط) ‪ ،‬فتــم تســليم املذكــور ومــا ضبط معه إلى مكافحة املخدرات‬\n      ‫بنجــران إلكمــال الــازم‪ .‬وبعــد انتهــاء التحقيــق معــه ُأطلــق ســراحه‬\n      ‫بالكفالــة احلضوريــة املرفقــة بــاألوراق اســتناد ًا للمــادة (‪ )120‬مــن نظــام‬\n      ‫اإلجــراءات اجلزائيــة ‪،‬وبســماع اقــوال املواطنــة‪ ...... /‬لــم تفــد التحقيــق‬\n      ‫بشــئ‪ 0‬وبســماع أقــوال املتهــم (‪ : ) ......‬أقــر بــأن القــات املضبــوط يف‬\n      ‫شــنطة والدتــه عائــد لــه شــخصي ًا وأنــه يســتخدم القــات ‪ 0‬وباســتجوابه‪:‬‬\n      ‫لــم يفــد التحقيــق بشــئ‪0‬وأثبت التقريــر الكيميائــي الشــرعي الصــادر‬\n      ‫مــن مركــز الســموم والكيميــاء الطبيــة الشــرعية مبنطقــة مكــة‬\n      ‫املكرمــة رقــم‪ ......‬أن العينــة املضبوطــة واملرســلة للتحليــل بخطــاب‬\n      ‫جمــرك اخلضــراء رقــم‪ ......‬ثبــت أنهــا لنبــات القــات املخــدر‪ ،‬والقــات‬\n      ‫مــن املــواد املدرجــة يف اجلــدول رقــم (‪ 4‬فئــة د) املرفقــة بنظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي الكــرمي رقــم‬\n      ‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬هـ ـ وقــد انتهــى التحقيــق بتوجيــه االتهــام‬\n      ‫إلــى‪ ....../‬ـ بتهريــب (‪ )29,9‬تســعة وعشــرين جــرام وتســعة أعشــار اجلــرام‬\n      ‫ا‬\n      ‫مــن نبــات القــات املخــدر بقصــد االســتخدام الشــخصي‪ ،‬ممــا يعــد فعـ ً‬\n      ‫مجرم ـ ًا اســتناد ًا للفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n                       ‫وتاريــخ ‪ 1426/7/8‬ه ـ وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n      ‫‪-1‬إعترافــه لــدى جهــة الضبــط املنــوه واملــدون علــى ص (‪ 1‬و ‪ )3‬مــن دفتــر‬\n                                                            ‫االســتدالل املرفــق لفه (‪)1‬‬\n      ‫‪-2‬محضــر القبــض والتفتيــش املنــوه عنــه واملرفــق علــى اللفــات (‪ 7‬و ‪8‬‬\n                                                                                        ‫و ‪)9‬‬\n      ‫‪-3‬التقريــر الكيميائــي الشــرعي املنــوه عنــه واملرفــق لفــه (‪. )36‬وحيــث‬\n\n\n‫‪117‬‬\n\f‫إن مــا أقــدم عليــه املتهــم‪ ...... /‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل‬\n‫مخالــف ومعاقــب عليــه نظامـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n‫لعــام ‪1374‬ه ـ لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n                                                                              ‫باآلتــي‪:‬‬\n‫‪-1‬تعزيــره شــرع ًا يف ضــوء املــادة (األولــى) الفقــرة (ب) مــن القــرار‬\n                                                ‫الــوزاري املشــار إليــه أعــاه ‪.‬‬\n‫‪-2‬منعــه مــن الســفر بعــد تنفيــذ محكوميتــه اســتناد ًا للفقــرة (د) مــن‬\n‫ذات املــادة ‪ .‬هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه وســؤاله‬\n‫ا مــا ذكــره املدعــي العــام يف دعــواه صحيــح كلــه‬       ‫اجلــواب أجــاب قائ ـ ً‬\n‫ا فقــد قمــت بتهريــب (‪ )29,9‬تســعة وعشــرين جــرام‬               ‫جملــة وتفصي ـ ً‬\n‫وتســعة أعشــار اجلــرام مــن نبــات القــات املخــدر بقصــد االســتخدام‬\n‫الشــخصي عــن طريــق منفــذ اخلضــراء وهــي عبــارة عــن بقايــا أعــواد‬\n‫قــات اســتعملته أثنــاء وجــودي يف اليمــن وقــد تبــت إلــى اهلل وندمــت علــى‬\n‫مــا فعلــت وليــس علـ ّـي ســوابق هــذه إجابتــي ‪.‬أ‪.‬ه ـ وبعــد ســماع الدعــوى‬\n‫واإلجابــة جــرى االطــاع علــى صــورة التقريــر الكيميائــي الشــرعي‬\n‫املشــار إليــه يف الدعــوى فوجــد يتضمــن ايجابيــة مــا ضبــط يف هــذه‬\n‫القضيــة للقــات‪ .‬أ‪.‬هــ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد‬\n‫االطــاع علــى وقائــع الدعــوى وأوراق املعاملــة ودراســتها ومبــا أن املدعــى‬\n‫ا فأقــر بتهريــب‬  ‫عليــه صــادق علــى دعــوى املدعــي العــام جملــة وتفصي ـ ً‬\n‫(‪ )29,9‬تســعة وعشــرين جــرام وتســعة أعشــار اجلــرام مــن نبــات القــات‬\n‫املخــدر بقصــد االســتخدام الشــخصي ‪ ،‬ومبــا أن كميــة مــا ضبــط مــع‬\n‫املدعــى عليــه قليــل جــدا‪ ،‬وقــد أبــدى املدعــى عليــه أســفه وندمــه علــى‬\n‫ذلــك‪ ،‬وحلداثــة ســن املدعــى عليــه واســتصالح ًا حلالــه‪ ،‬واســتناد ًا إلــى‬\n\n\n                                                                                          ‫‪118‬‬\n\f      ‫املــادة (األولــى) الفقــرة (ب) واملــادة (اخلامســة) الفقــرة (ب‪-‬ج) مــن قــرار‬\n      ‫مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ لــكل هــذه األســباب وتأسيسـ ًا‬\n      ‫علــى كل مــا تقــدم فقــد قــررت اآلتــي أوالً‪ :‬ثبــت لــدي إدانــة املدعــى‬\n      ‫عليــه بتهريــب (‪ )29,9‬تســعة وعشــرين جــرام وتســعة أعشــار اجلــرام مــن‬\n      ‫نبــات القــات املخــدر بقصــد االســتخدام الشــخصي‪ ،‬وقــررت تعزيــره‬\n      ‫لقــاء ذلــك بســجنه ملــدة شــهرين يحتســب منهــا مــا أمضــاه موقوفـ ًا علــى‬\n      ‫ذمــة هــذه القضيــة وجلــده أربعــن جلــدة دفعــة واحــدة‪ .‬ثانيـاً‪ :‬مينــع املدعــى‬\n      ‫عليــه مــن الســفر خــارج البــاد ملــدة ســنة واحــدة تبــدأ بعــد انتهــاء مــدة‬\n      ‫تنفيــذ عقوبــة الســجن املقــررة يف البنــد (أوالً)‪ .‬وبذلــك كلــه حكمــت‬\n      ‫وبعرضــه علــى املدعــى عليــه قــرر اعتراضــه علــى احلكــم بالئحــة‬\n      ‫اعتراضيــة لــذا واســتناد ًا إلــى املــواد (‪ )195-194‬مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة فســيتم تســليمه صــورة مــن احلكــم هــذا اليــوم وأفهــم أن مــدة‬\n      ‫االعتــراض ثالثــون يومـ ًا تبــدأ مــن يــوم غــد فــإذا مضــت املــدة ولــم يقــدم‬\n      ‫الالئحــة االعتراضيــة فــإن حقــه يف طلــب االســتئناف يســقط وترفــع‬\n      ‫املعاملــة حملكمــة االســتئناف دون الئحــة اعتراضيــة خــال خمســة‬\n      ‫وأربعــن يومـ ًا مــن تاريــخ النطــق باحلكــم ففهــم ذلــك وقــرر املدعــي العــام‬\n      ‫اعتراضــه علــى احلكــم بــدون الئحــة وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1434/7/22‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n      ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بنجــران برقــم‬\n      ‫‪ 341612700‬وتاريخ‪1434/8/9‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيل ــة القاضــي باحملكمــة الشــيخ ‪ ....../‬برقــم ‪ 34275215‬وتاريــخ‬\n\n\n‫‪119‬‬\n\f‫‪1434/7/22‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪ ...... /‬يف قضيــة‬\n‫(مخــدرات) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق‬\n                      ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n\n\n\n\n                                                                                   ‫‪120‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":115,"source_page_end":120,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e787fe01cba5608c2ad785eef9fc9ec4d81296a1440eb7cdc04dc8d6670dfb9f","normalized_text_hash":"c9e87572f535a17b734ddb24a8df029199e5cbc6996401621098de7100682867","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p115-34275215"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"5847c353-1eed-58ab-b5f9-2df3392c24dc","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تهريب مخدرات -تعاطي احلشيش -تعاطي احلبوب احملظورة -قيادة السيارة حتت تأثير تعاطي احلشيش -أسباب تخفيف العقوبة -تداخل العقوبات -إقامة حد املسكر -التعزير بالسجن واجللد واالبعاد.","document_number":"3459890","case_number":"3429446","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/10","year":"1434","subject":"مخدرات -تهريب مخدرات -تعاطي احلشيش -تعاطي احلبوب احملظورة -قيادة السيارة حتت تأثير تعاطي احلشيش -أسباب تخفيف العقوبة -تداخل العقوبات -إقامة حد املسكر -التعزير بالسجن واجللد واالبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 3459890 :‬تاريخه ‪1434/03/10 :‬هـ‬\n                          ‫رقم الدعوى‪3429446 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34257062‬تاريخه‪1434/7/2 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬تهريــب مخــدرات ‪ -‬تعاطــي احلشــيش ‪ -‬تعاطــي احلبــوب‬\n      ‫احملظــورة ‪ -‬قيــادة الســيارة حتــت تأثيــر تعاطــي احلشــيش ‪ -‬أســباب‬\n      ‫تخفيــف العقوبــة ‪ -‬تداخــل العقوبــات ‪ -‬إقامــة حــد املســكر ‪ -‬التعزيــر‬\n                                                     ‫بالســجن واجللــد واالبعــاد‪.‬‬\n\n\n\n\n               ‫احل ِّق }‪.‬‬           ‫‪ -1‬قوله تعالى { َو َال َت ْق ُت ُلو ْا ال َّن ْف َس ا َّلتِي َح َّر َم ّ ُ‬\n                      ‫الل ِإ َّال ِب َ‬\n                       ‫ال ِح َها }‪.‬‬‫‪ -2‬قوله تعالى { َو َال ُت ْف ِس ُدو ْا ِف األرض َب ْع َد ِإ ْص َ‬\n                                               ‫‪ -3‬املادة (‪ )41‬من نظام مكافحة املخدرات ‪.‬‬\n                                              ‫‪ -4‬املادة (‪ )60‬من نظام مكافحة املخدرات ‪.‬‬\n               ‫‪ -5‬الفقرة الثانية من املادة (‪ )56‬من نظام مكافحة املخدرات ‪.‬‬\n\n\n\n\n      ‫توجيــه االتهــام لزائــر خليجــي بتهريــب لفافــة تبــغ مخلوطــة باحلشــيش‬\n      ‫لقصــد االســتعمال بتعاطيــه للحشــيش املخــدر وتعاطيــه حلبــوب‬\n      ‫االمفيتامــن وقيادتــه للســيارة حتــت تأثيــر احلشــيش ‪ ،‬مت تفتيــش‬\n      ‫ســيارته التــي يقودهــا مــن قبــل إحــدى املنافــذ البريــة اجلمركيــة‬\n      ‫وعثــر بداخلهــا علــى لفافــة تبــغ ملفوفــة باحلشــيش ‪ ،‬كمــا أثبــت‬\n      ‫تقريــر الســموم الشــرعية إيجابيــة العينــة املأخــوذة مــن ســوائل املدعــى‬\n‫‪75‬‬\n\f‫عليــه ملــادة احلشــيش ومركــب االمفيتامــن احملظــور ‪ ،‬طلــب املدعــى‬\n‫العــام إثبــات مــا أســند إليــه واحلكــم عليــه بالعقوبــة الــواردة يف نظــام‬\n‫مكافحــة املخــدرات وإبعــاده عــن البــاد بعــد تنفيــذ محكوميتــه‪ ،‬أقــر‬\n‫املدعــى عليــه مبــا نســب إليــه‪ ،‬صــدر احلكــم بإثبــات إدانــة املدعــى عليــه‬\n‫مبــا نســب إليــه وإقامــة حــد املســكر ودخــول عقوبــة تعاطــي حبــوب‬\n‫االمفيتامــن يف حــد املســكر‪ ،‬التعزيــر بالســجن واإلبعــاد‪ ،‬إثبــات‬\n‫قيــادة املدعــى عليــه للســيارة حتــت تأثيــر املســكر والعقوبــة يف ذلــك‬\n          ‫للجهــة املختصــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫ـدي أنــا‬\n      ‫احلمــدهلل وحــده والصــاة والســام علــى َمــنْ النبــي بعــده وبعــد فلـ َّ‬\n‫ـاء علــى املعاملــة الــواردة‬\n                            ‫‪ ...‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫إلينــا مــن دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء برقــم ‪778‬‬\n‫وتاريخ‪1434/01/17‬ه ـ واملقيــدة بهــذه احملكمــة برقــم ‪34142468‬‬\n‫وتاريــخ ‪1434/01/18‬ه ـ واحملالــة إلينــا مــن فضيلــة الرئيــس برقــم‬\n‫‪ 3429446‬وتاريــخ ‪1434/01/18‬ه ـ فتحــت اجللســة وفيها حضر املدعي‬\n‫العــام ‪ ...‬امل ـ ُ َـع ّمد بالترافــع أمــام احملكمــة طرفنــا مبوجــب خطاب ســعادة‬\n‫رئيــس دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء ذي الرقــم‬\n‫ا ‪ :‬بصفتــي مدعي ًا‬  ‫‪ 13415‬والتاريــخ ‪1433/12/01‬ه ـ وقـ ّـرر دعــواه قائـ ً‬\n‫عامـ ًا بدائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي ‪ ،....:‬البالــغ مــن‬\n‫العمر(‪)36‬عامــا قطــري اجلنســية مبوجــب البطاقــة رقــم (‪ )....‬متســبب ‪،‬‬\n‫غيــر محصــن‪ ،‬قبــض عليــه بتاريــخ ‪1433/11/2‬ه ـ مفــرج عنــه مبوجــب‬\n‫أمــر اإلفــراج الصــادر مــن دائــرة التحقيــق واالدعــاء العــام باألحســاء رقــم‬\n\n                                                                                       ‫‪76‬‬\n\f     ‫(ه ـ ق‪ )213635/2‬وتاريــخ ‪1433/12/6‬ه ـ انــه بتاريــخ ‪1433/11/2‬ه ـ‬\n     ‫مت تفتيــش ســيارة مــن قبــل منفــذ ســلوى مــن نــوع ‪ ....‬موديــل ‪2008‬م‬\n     ‫وحتمــل اللوحــة رقــم (‪ )....‬والتــي يقودهــا املدعــى عليــه املذكــور وعثــر‬\n     ‫بداخلهــا علــى لفافــة تبــغ ملفوفــة يشــتبه انهــا مخلوطــة باحلشــيش املخــدر‬\n     ‫وبلــغ وزنهــا (‪ )1,68‬جــرام وثمانيــة وســتون مــن املائــة مــن اجلــرام‪ .‬وقــد‬\n     ‫اثبــت تقريــر الكيمــاوي الشــرعي رقــم (‪ 3942‬ك ش) لعــام ‪1433‬ه ـ‬\n     ‫احتــواء العينــة املرســلة ملــادة احلشــيش املخــدر واملدرجــة مــن ضمــن‬\n     ‫املــواد احملظــورة يف اجلــدول (‪ )1‬فئــة (أ) مــن نظــام مكافحــة املخــدرات‬\n     ‫واملؤثــرات العقليــة كمــا اثبــت تقريــر الســموم الشــرعية رقــم (‪1484‬‬\n     ‫م أ) لعــام ‪1433‬ه ـ ايجابيــة العينــة املأخــوذة مــن ســوائل املدعــى عليــه‬\n     ‫ملــادة احلشــيش املخــدر و ملركــب امفيتامينــي محظــور وباســتجواب‬\n     ‫املدعــى عليــه ‪ /‬اقــر بصحــة واقعــة القبــض والضبــط وعائديــه الســيارة‬\n     ‫لــه وقــد أســفر التحقيــق عــن توجيــه االتهــام لــه بتهريــب لفافــة تبــغ‬\n     ‫مخلوطــة باحلشــيش املخــدر البالــغ وزنهــا (‪ 1,68‬جــم ) جــرام وثمانيــة‬\n     ‫وســتون مــن املائــة مــن اجلــرام إلــى داخــل البــاد بقصــد التعاطــي وتعاطيــه‬\n     ‫لنوعــه وتعاطــي االمفيتامــن احملظــور وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n     ‫‪ -1-‬ماجــاء بأقوالــه املدونــة علــى الصفحــة رقــم (‪ )1‬مــن ملــف التحقيــق‬\n     ‫املرفــق علــى اللفــة رقــم (‪ -2.)11‬مــا جــاء مبحضــر القبــض املنــوه عنــه‬\n                                                       ‫واملرفــق علــى اللفــة رقــم (‪.)4‬‬\n     ‫‪-3‬مــا أثبتــه التقريــر الكيمــاوي الشــرعي املنــوه عنــه واملرفــق برقــم‬\n                                                                                  ‫(‪.)20‬‬\n     ‫‪-4‬مــا أثبتــه التقريــر الســموم الشــرعية املنــوه عنــه واملرفــق علــى اللفــة‬\n     ‫رقــم (‪.)23‬وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق‬\n\n\n‫‪77‬‬\n\f                                                                            ‫مســجلة ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا يف ضــوء الفقــرة الثانيــة مــن‬\n‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n‫باملرســوم امللكــي الكــرمي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ اطلــب‬\n                                ‫إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪-:‬‬\n‫‪ -1‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة لقــاء مــا اســند إليه مــن اتهام‪-2.‬‬\n‫إبعــاده خــارج البــاد بعــد تنفيــذ حكوميتــه اســتناد ًا للفقــرة الثانيــة مــن‬\n‫املــادة (‪ )56‬مــن ذات النظــام هكــذا ا َّدعــى ؛ عليــه فقــد حضــر املدعــى‬\n‫عليــه وبعــد التأكــد مــن هويتــه جــرى عــرض دعــوى املدعــي العــام عليــه‬\n‫فأجــاب قائ ـاً‪ :‬صحيــح مــا نســبه لــي املدعــي العــام مــن واقعــة القبــض‬\n‫ومــن تهريبــي للفافــة تبــغ مخلــوط تبغهــا باحلشــيش البالــغ وزنهــا (‪)1,68‬‬\n‫جــرام وثمانيــة وســتون مــن املائــة مــن اجلــرام بقصــد التعاطــي وصحيــح‬\n‫اعتــرايف واســتعمالي للحشــيش املخــدر واحلبــوب احملظــورة وقيادتــي‬\n‫للســيارة حتــت تأثيرهمــا وأنــا نــادم علــى مابــدر منــي وتائــب إلــى اهلل‬\n‫هكــذا أجــاب هــذا وقــد جــرى االطــاع علــى التقريــر الكيمــاوي‬\n‫الشــرعي الصــادر مــن قســم الكيميــاء الشــرعية باملركــز اإلقليمــي‬\n‫ملراقبــة الســموم التابــع للمديريــة العامــة للشــؤون الصحيــة باملنطقــة‬\n‫الشــرقية برقــم ( ‪ 1742‬ك ش ) لعــام ‪1433‬ه ـ املتضمــن إيجابيــة عي ــنة‬\n‫مــا ضبــط للحشــيش املخــدر كمــا جــرى االطــاع علــى كــرت ســوابق‬\n‫املدعــى عليــه املتضمــن خلــوه مــن الســوابق فبناء على مــا ورد من الدعوى‬\n‫واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه والتأكــد مــن أهليتــه وملــا‬\n\n\n                                                                                           ‫‪78‬‬\n\f     ‫ورد يف محضــر القبــض واعتــراف املدعــي عليــه ومبــا أنــه صــادق علــى‬\n     ‫صحــة مــا نســب إليــه مــن تهريــب احلشــيش املخــدر علــى صفــة مــا ورد‬\n     ‫يف الدعــوى ومبــا أن مــا صــدر منــه حــرام يف الشــريعة ملــا يف احلشــيش‬\n     ‫املخــدر احلبــوب احملظــورة مــن اخلطــر و الضــرر علــى البــاد والعبــاد‬\n     ‫وعلــى مــن صــدر منــه ذلــك قــال تعالــى (وال تقتلــوا النفــس التــي حــرم‬\n     ‫اهلل إال باحلــق) وقــال (وال تفســدوا يف األرض بعــد إصالحهــا ) ممــا‬\n     ‫يســتوجب معاقبــة املدعــى عليــه و تعزيــزه بالعقوبــة الــواردة يف املــادة‬\n     ‫الواحــدة واألربعــن مــن نظــام مكافحــة املخــدرات ويتوجــه أن يكــون‬\n     ‫أقــل عقوبــة ملــا ظهــر مــن حالــه مــن النــدم وألنــه ال ســوابق لــه ولقلــة‬\n     ‫الكميــة التــي وجــدت بحيازتــه كمــا يتوجــه تخفيــف تلــك العقوبــة‬\n     ‫أيضــا حســب مقتضــى املــادة الســتني مــن النظــام نفســه ملــا ظهــر مــن‬\n     ‫حالــه مــن النــدم ولظروفــه االجتماعيــة التــي اقتنعــت بهــا احملكمــة ـ‬\n     ‫وألنــه ال ســوابق لــه كمــا يتوجــه اســتحقاقه للعقوبــة الــواردة يف املــادة‬\n     ‫أن املدعــى عليــه أقـ َّـر‬  ‫السادســة واخلمســن الفقــرة الثانيــة منهــا ومبــا َّ‬\n     ‫باســتعمال احلشــيش املخــدر واســتعماله يأخــذ حكــم املســكر للتوافــق‬\n     ‫بينهمــا يف منــاط احلكــم وحــد املســكر أن يجلــد صاحبــه ثمانــن جلــدة‬\n     ‫علنــا كمــا اســتقر عليــه عمــل األمــة ممــا يتوجــب حــد املدعــى عليــه حــد‬\n     ‫املســكر الســتعماله للحشــيش املخــدر واالكتفــاء عــن مجازاتــه عــن‬\n     ‫اســتعمال احلبــوب لدخــول األصغــر يف حكــم األكبــر لــذا كلــه وألجــل‬\n     ‫ـدي إدانــة‬‫احلــق العــام حكمــت علــى املدعــى عليــه باآلتــي ‪ :‬أو ًال ‪ /‬ثبــت لـ َّ‬\n     ‫املدعــى عليــه باســتعمال احلشــيش املخــدر ويجلــد حــد املســكر ثمانــن‬\n     ‫ـدي إدانتــه باســتعمال احلبــوب‬       ‫جلــدة دفعــة واحــدة علن ـ ًا كمــا ثبــت لـ َّ‬\n     ‫احملظــورة وعقوبتــه داخلــة يف حـ ِّـد املســكر ثاني ـ ًا ‪ /‬ثبــت لــدي إدانــة‬\n\n\n‫‪79‬‬\n\f‫املدعــى عليــه بتهريــب لفافــة تبــغ مخلــوط تبغهــا باحلشــيش البالــغ وزنهــا‬\n‫(‪ )1,68‬جــرام وثمانيــة وســتون مــن املائــة مــن اجلــرام بقصــد التعاطي وأن‬\n‫يعــزر بســجنه شــهرين حتتســب منهــا املــدة التــي أوقــف فيهــا علــي ذمــة‬\n‫القضيــة وذلــك مبوجــب املــادة الواحــدة و األربعــن مــن نظــام مكافحــة‬\n‫املخــدرات واملــادة الســتني ‪ .‬ثالث ـ ًا ‪ /‬وأن يبعــد عــن اململكــة بعــد تنفيــذ‬\n‫العقوبــة احملكــوم بهــا عليــه واســتيفاء مــا لــه ومــا عليــه مــن حقــوق وال‬\n‫يســمح لــه بالعــودة إليهــا فيمــا عــدا مــا تســمح بــه تعليمــات احلــج والعمــرة‬\n‫حســب مقتضــى مــا ورد يف املــادة السادســة واخلمســن مــن النظــام‬\n‫نفســه الفقــرة الثانيــة وبتــاوة احلكــم علــى الطرفــن وإفهــام املدعــى‬\n‫عليــه بحقــه يف التمييــز قــرر قناعتــه باحلكــم وطلــب املدعــي العــام‬\n‫رفــع احلكــم للتمييــز وأن الئحتــه االعتراضيــة هــي الئحــة الدعــوى‬\n‫هــذا وجــرى توجيــه املدعــى عليــه مبــا يلــزم ومــن ذلــك حرمــة اســتعمال‬\n‫احلشــيش املخــدر و احلبــوب احملظــورة وأثــره الســيئ علــى العقــل واملــال‬\n‫وأقفلــت اجللســة الســاعة العاشــرة والنصــف وصلــى اهلل وســلم علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه أجمعــن حــرر احلكــم يف ‪1434/03/09‬ه ـ ‪.‬‬\n‫احلمــدهلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد‬\n‫ففــي يــوم األحد‪1434/06/04‬ه ـ فتحــت اجللســة الثانيــة الســاعة‬\n‫الثانيــة عشــرة وفيهــا حضــر الطرفــان وقــد عــادت املعاملــة املتعلقــة‬\n‫بالدعــوى العامــة ضــد ‪....‬مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n‫مبوجــب خطــاب فضيلــة رئيســها ذي الرقــم‪ 34/736056‬وتاريــخ‬\n‫‪1434/05/14‬ه ـ وبرفقهــا قــرار الدائــرة اجلزائيــة الثالثيــة األولــى(ج‪)1/‬‬\n‫رقم‪34209243‬وتاريخ‪1434/05/08‬ه ـ املتضمــن مــا نصــه‪« :‬وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ أن املدعــى عليــه أقـ َّـر‬\n\n\n                                                                                         ‫‪80‬‬\n\f     ‫بقيادتــه الســيارة حتــت تأثيــر اســتعماله املخــدر واحلبــوب احملظــورة ولــم‬\n     ‫جنــد أن فضيلــة ناظــر القضيــة أجــرى الــازم حيــال ذلــك ملالحظــة ذلــك‬\n     ‫وإكمــال الــازم ومــن ثــم إعــادة املعاملــة واهلل املوفــق « ا‪.‬ه ـ عليــه أجيــب‬\n     ‫ـأن ماذكــروه صحيــح وقــد وقــع ذلك مني‬          ‫مشــايخي نفعنــي اهلل بعلمهــم بـ َّ‬\n     ‫أن املدعــى عليــه أقـ َّـر بقيــادة الســيارة‬\n                                                  ‫ـهوا واهلل املســتعان وعليــه ومبــا َّ‬\n                                                                                        ‫سـ ً‬\n     ‫حتــت تأثيــر احلشــيش املخــدر وحتــت تأثيــر احلبــوب احملظــورة وإثبــات‬\n     ‫إدانتــه بذلــك لــدى هــذه احملكمــة والعقوبــة لــدى ولــي األمــر حســب‬\n     ‫األنظمــة املرعيــة التتــي ال تتعــارض مــع املصالــح الشــرعية لــذا فقــد ثبــت‬\n     ‫ـدي إدانــة املدعــى عليــه بقيــادة الســيارة حتــت تأثيــر املخــدرات واحلبــوب‬   ‫لـ َّ‬\n     ‫ـأن عقوبتــه عائــدة لولــي األمــر وبعرضــه عليهمــا‬        ‫احملظــورة وأفهمتــه بـ َّ‬\n     ‫ـرت بالتهميــش علــى قــرار احلكــم مبــا طــرأ عليــه ومــن ثـ ّـم‬     ‫قنــع بــه وأمـ ُ‬\n     ‫إعــادة املعاملــة حملكمــة االســتئناف باملنطقــة الشــرقية لتدقيــق احلكــم‬\n     ‫وأقفلت اجللســة الســاعة الثانية عشــرة والنصف ظهر ًا وصلى اهلل وســلم‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ُحـ ِـر َر يف‪1434/06/04‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n     ‫برقــم ‪ 34/736056‬وتاريــخ ‪1434/6/14‬ه ـ املقيــدة لــدى احملكمــة‬\n     ‫برقــم ‪ 341509167‬وتاريــخ ‪1434/6/21‬ه ـ املرفــق بهــا القــرار الصــادر‬\n     ‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪....‬برقــم ‪ 3459890‬وتاريــخ‬\n     ‫‪1434/3/10‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضد‪..../‬قطــري اجلنســية‬\n     ‫يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n     ‫ومفصــل فيــه ‪ .‬حيــث ســبق دراســة القــرار وصــورة ضبطــه وباإلطــاع‬\n\n\n‫‪81‬‬\n\f‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء‬\n‫علــى قرارنــا رقــم‪ 34209243‬يف ‪1434/5/8‬ه ـ قررنــا املصادقــة علــى‬\n‫احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                              ‫وآلــه وصحبــه وســلم حــرر يف ‪1434/7/2‬هــ‪.‬‬\n\n\n\n\n                                                                                   ‫‪82‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":75,"source_page_end":82,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"56138d2c5c750323c236d107daddfb6b78d710a45f144e0c23166120bf11b837","normalized_text_hash":"1308407590640b51936a3ab76e59b363ac2575eeb9e091823d9968edc81c1ae6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p75-3459890"},{"id":"ea2b7595-5f5f-5890-bc65-63624376abaf","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تهريب بقصد االجتار -قات -التعزير بالسجن واجللد والغرامة واإلبعاد.","document_number":"33475491","case_number":"33644973","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/21","year":"1434","subject":"مخدرات -تهريب بقصد االجتار -قات -التعزير بالسجن واجللد والغرامة واإلبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 33475491:‬تاريخه‪1433/12/21:‬هـ‬\n                       ‫رقم الدعوى‪33644973 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3416010‬تاريخه‪1434/1/19 :‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬تهريــب بقصــد االجتــار ‪ -‬قــات ‪ -‬التعزيــر بالســجن واجللــد‬\n                                                            ‫والغرامــة واإلبعــاد‪.‬‬\n\n\n\n\n                     ‫‪ -1‬األمر السامي الكرمي رقم (‪ )59633‬يف ‪1432/12/9‬هـ‪.‬‬\n                             ‫‪ -2‬قرار مجلس الوزراء رقم (‪ )11‬لعام ‪1374‬هـ ‪.‬‬\n     ‫‪ -3‬الفقــرة (أ) مــن املــادة األولــى مــن قــرار وزيــر الداخليــة رقــم ( ‪) 2057‬‬\n                                                                    ‫يف ‪1404/5/26‬هـ ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي العــام ضــد مدعــى عليهــم بتهــرب القــات مــن األراضــي‬\n     ‫اليمنيــة إلــى األراضــي الســعودية و طلــب إثبــات مــا أســند إليهــم واحلكــم‬\n     ‫بتعزيرهــم وفــق الفقــرة أ مــن املــادة األولــى لقــرار مجلــس الــوزراء‬\n     ‫رقــم(‪ )11‬لعــام ‪1374‬ه ـ وتشــديد العقوبــة علــى الثالــث لكثــرة ســوابقه‬\n     ‫‪ -‬حيــث مت القبــض علــى املدعــى عليهــم أثنــاء قدومهــم مــن اليمــن إلــى‬\n     ‫الســعودية ســير ًا علــى األقــدام بطريقــة غيــر مشــروعة وضبــط بحوزتهــم‬\n     ‫كميــة مــن نبــات القــات ‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة‬\n     ‫العينــة املضبوطــة لنبــات القــات احملظــور ‪ -‬صــادق املدعــى عليهــم علــى‬\n     ‫االدعــاء املوجــه اليهــم ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــر‬\n\n‫‪83‬‬\n\f‫املدعــى عليــه األول والثالــث بالســجن خمــس ســنوات و جلــد كل واحــد‬\n‫منهمــا خمســمائة جلــدة علنـ ًا مفرقــة كل دفعــة قدرهــا خمســون جلــدة‬\n‫و غرامــة ماليــة قدرهــا خمســة آالف ريــال وتعزيــر املدعــى عليــه الثانــي‬\n‫بالســجن أربــع ســنوات وجلــده أربعمائــة جلــدة علن ـ ًا مفرقــة كل دفعــة‬\n‫قدرهــا خمســون وغرامــة ماليــة قدرهــا ثالثــة آالف ريــال وإبعادهــم عــن‬\n‫البــاد بعــد إنفــاذ العقوبــة املقــررة بحقهــم وقنــع املدعــى عليهــم باحلكــم‬\n‫‪،‬وصــدق احلكــم‬ ‫واعتــرض املدعــي العــام مكتفي ـ ًا بالئحــة الدعــوى ُ‬\n                                                  ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بجــازان برقــم ‪ 33644973‬وتاريــخ ‪1433/11/09‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331979764‬وتاريــخ ‪1433/11/09‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافق‪1433/11/10‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 15‬‬\n‫وفيهــا حضــر املدعــي العــام ‪.....‬بالتعميــد رقــم ( ‪ ).....‬يف ‪1433/3/22‬ه ـ‬\n‫واملدعــى عليهــم‪..... /‬و‪.....‬و‪.....‬مينــي اجلنســية وقــدم املدعــي العــام دعــوى‬\n‫محــررة تتضمــن ‪ :‬أنــه بتاريــخ ‪1433/6/28‬ه ـ مت القبــض علــى املدعــى‬\n‫عليهــم أثنــاء قدومهــم مــن األراضــي اليمنيــة إلــى األراضــي الســعودية‬\n‫ســير ًا علــى األقــدام بطريقــة غيــر مشــروعة وضبــط بحوزتهــم كميــة‬\n‫مــن نبــات القــات احملظــور بلــغ وزنهــا (‪ 18‬كجــم) ثمانيــة عشــر كيلــو‬\n‫جرام ـ ًا لــكل واحــد منهــم وأثبــت التقريــر الكيميائــي الشــرعي رقــم‬\n‫(‪ ).....‬وتاريــخ ‪1433/7/14‬ه ـ إيجابيــة العينــات املرســلة منــه لنبــات‬\n\n                                                                                      ‫‪84‬‬\n\f     ‫القــات احملظــور وباســتجوابهم بعــد مواجهتهــم بالتهمــة املنســوبة إليهــم‬\n     ‫أقـ ــر كل واحــد منهــم بتهريــب الكميــة املضبوطــة بحوزتــه مــن نبــات‬\n     ‫القات احملظور من اليمن إلى الســعودية لصالح شــخص (ميني اجلنســية)‬\n     ‫يدعى‪...../‬يســكن اليمــن لغــرض إيصالهــا إلــى الشــبك بالقــرب مــن‬\n     ‫قريــة ‪.....‬الســعودية وذلــك مقابــل أجــر مــادي قــدره مائتــي ريــال لــكل‬\n     ‫واحــد منهــم ويســتقبلها شــخص يدعى‪.....‬الــذي يقــوم بإيصالهــا إلــى‬\n     ‫جهــة غيــر معلومــة لهــم وصادقــوا علــى أقوالهــم بذلــك حتقيق ـ ًا وقــد‬\n     ‫أســفر التحقيــق مــع كل مــن‪..... :‬و‪.....‬و‪.....‬عــن توجيــه االتهــام إليهــم‬\n     ‫بارتــكاب كل منهــم جرميــة تهريــب مــا وزنــه (‪ 18‬كجــم‪ -‬ثمانيــة عشــر‬\n     ‫كيلــو جرام ـاً) مــن نبــات القــات احملظــور مــن اليمــن إلــى الســعودية‬\n     ‫بقصــد االجتــار وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا ورد بأقوالهــم‬\n     ‫مبحضــر التحقيــق املرفــق ‪ -2‬مــا ورد بإقرارهــم لــدى اجلهــة القابضــة‬\n     ‫واملرفــق ‪ -3‬مــا جــاء يف محضــر القبــض املنــوه عنــه املرفــق ‪ -4‬مــا جــاء‬\n     ‫يف التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق وحيــث إن مــا أقــدم‬\n     ‫عليــه املذكوريــن فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا مبوجب قرار‬\n     ‫مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات لــذا‬\n     ‫أطلــب ‪ :‬إثبــات إدانتهــم مبــا أســند إليهــم واحلكــم بتعزيرهــم يف ضــوء‬\n     ‫الفقــرة (أ) مــن املــادة (األولــى) مــن القــرار الــوزاري املشــار إليــه أعــاه‬\n     ‫إنفــاذا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ‬\n     ‫والتشــديد يف العقوبــة علــى املدعــى عليــه الثالــث لكثــرة ســوابقه‬\n     ‫ال مــن ‪..........‬و‪.....‬مينــي اجلنســية أجــاب كل‬‫وبســؤال املدعــى عليهــم ك ً‬\n     ‫واحــد منهــم باالعتــراف بتهريــب مــا وزنــه ثمانيــة عشــر كيلــو جرامـ ًا من‬\n     ‫نبــات القــات احملظــور مــن األراضــي اليمنيــة إلــي األراضــي الســعودية‬\n\n\n‫‪85‬‬\n\f‫حلســاب الغيــر مقابــل مبلــغ مالــي هكــذا أجــاب املدعــى عليهــم عنــد‬\n‫ذلــك جــرى منــا االطــاع علــى التقريــر الكيميائــي الشــرعي وعلــى‬\n‫محضــري الــوزن والقبــض فوجــدت متطابقــة ملــا جــاء بالدعــوى وبنــاء‬\n‫علــى مــا ذكــر مــن دعــوى املدعــي العــام وعلــى إجابــة املدعــى عليهــم‬\n‫‪.....‬و‪.....‬و‪.....‬مينــي اجلنســية باالعتــراف بتهريــب كل واحــد منهــم ملــا وزنــه‬\n‫ثمانيــة عشــر كيلــو جرام ـ ًا مــن نبــات القــات احملظــور مــن اليمــن إلــي‬\n‫الســعودية حلســاب الغيــر مقابــل مبلــغ مالــي لــذا فقــد ثبــت لــدي شــرع ًا‬\n‫إدانــة املدعــى عليهــم بتهريــب كل واحــد منهــم للكميــة املوضحــة‬\n‫أعــاه حلســاب الغيــر مقابــل مبلــغ مالــي لقصــد الترويــج وهــم يســتحقون‬\n‫العقوبــة علــى ذلــك وفــق الفقــرة (أ) مــن املــادة األولــى مــن قــرار وزيــر‬\n‫الداخليــة رقــم (‪ )2057‬وتاريــخ ‪1404/5/26‬ه ـ املبنــي علــى قــرار مجلس‬\n‫الــوزراء رقــم (‪ )11‬وتاريــخ ‪1374/2/1‬ه ـ إنفــاذا لألمــر الســامي الكرمي‬\n‫رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ وملــا ذكــر أعــاه فقــد حكمــت‬\n‫بتعزيــر كل واحــد مــن املدعــى عليــه األول والثالــث بالســجن ملــدة خمس‬\n‫ســنوات مــن تاريــخ إيقــاف كل واحــد منهمــا يف ‪1433/6/28‬ه ـ وجلــد‬\n‫كل واحــد منهمــا بخمســمائة جلــدة علن ـ ًا مفرقــة كل دفعــة خمســون‬\n‫جلــدة بــن الدفعــة واألخــرى عشــرة أيــام وغرامــة ماليــة قدرهــا خمســة‬\n‫آالف ريــال (‪ 5000‬ريــال) تــودع بيــت مــال املســلمني ويعــزر املدعــى عليــه‬\n‫الثانــي بالســجن ملــدة أربــع ســنوات مــن تاريــخ إيقافــه يف ‪1433/6/28‬ه ـ‬\n‫وجلــدة بأربعمائــة جلــدة علن ـ ًا مفرقــة كل دفعــة خمســون جلــدة بــن‬\n‫الدفعــة واألخــرى عشــرة أيــام وغرامــة ماليــة قدرهــا ثالثــة أالف ريــال‬\n‫تــودع بيــت مــال املســلمني ويبعــدون عــن البــاد بعــد إنفــاذ العقوبــة املقــرر‬\n‫بحقهــم شــرع ًا وال يســمح لهــم بالعــودة إليهــا عــدى مــا تســمح بــه أنظمــة‬\n\n\n                                                                                        ‫‪86‬‬\n\f     ‫احلــج والعمــرة هــذا مــا حكمــت بــه وبعرضــه علــى الطرفــن قــرر املدعــى‬\n     ‫عليهــم القناعــة وطلــب املدعــي العــام اســتئناف احلكــم مكتفيـ ًا بالئحــة‬\n     ‫االدعــاء العــام وأمــرت بتنظيــم القــرار الــازم مبوجبــه ورفعــه حملكمــة‬\n     ‫االســتئناف مبنطقــة عســير لدراســته وإبــداء مــا تــراه نحــوه وصلــى اهلل‬\n        ‫وســلم علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر ‪1433/11/10‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n     ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n     ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n     ‫‪ 331979764‬وتاريــخ ‪1433/12/27‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n     ‫فضيلــة القاضــي باحملكمــة الشــيخ‪..... /‬برقــم ‪ 33475491‬وتاريــخ‬\n     ‫‪1433/12/21‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد كل مــن‪/‬‬\n     ‫‪.....‬و‪.....‬و‪(.....‬مينــي اجلنســية) يف قضيــة (قــات) علــى الصفــة املوضحــة يف‬\n     ‫القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة‬\n     ‫القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم ‪.‬‬\n           ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪87‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":83,"source_page_end":87,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"099d23bcc804f0ab7b94a587b9157361e7c1e452bd1b79762324476b72df172c","normalized_text_hash":"b549a9e6b86a2709f6e26c1db4033d8060b92ff9f5c140cad45d821d49f562a7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p83-33475491"},{"id":"3fc3e085-fead-53d4-8bee-32712179763d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -قات -تهريب -التعزير بالسجن واجللد واإلبعاد من","document_number":"34198977","case_number":"34163330","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":"الدائرة الثالثة لتدقيق القضايا اجلزائية مبحكمة الاستئناف","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/27","year":"1434","subject":"مخدرات -قات -تهريب -التعزير بالسجن واجللد واإلبعاد من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34198977 :‬تاريخه‪1434/4/27:‬هـ‬\n                  ‫رقم الدعوى‪34163330 :‬‬\n  ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34264980‬تاريخه‪1434/7/11 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬قــات ‪ -‬تهريــب ‪ -‬التعزيــر بالســجن واجللــد واإلبعــاد مــن‬\n                                                                  ‫البــاد‬\n\n\n\n\n                     ‫‪ -1‬األمر السامي رقم (‪ )59633‬يف ‪1432/12/9‬هـ‪.‬‬\n                     ‫‪ -2‬قرار مجلس الوزراء رقم(‪ )11‬يف ‪1374/2/1‬هـ‪.‬‬\n‫‪ -3‬الفقــرة (أ) مــن املــادة األولــى مــن قــرار وزيــر الداخليــة رقــم (‪)2057‬‬\n                                                             ‫يف ‪1404/5/26‬هــ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا بتلقــي قــات بقصــد االجتــار‪،‬‬\n‫قبــض علــى املدعــى عليهمــا عنــد الشــبك احلــدودي أثنــاء اســتقبالهما‬\n‫للقــات املهــرب مــن اليمــن وبحوزتهمــا نبــات القــات وطلب إثبات ما أســند‬\n‫إليهمــا ومعاقبتهمــا وإبعادهمــا عــن البــاد وتشــديد العقوبــة علــى الثانــي‬\n‫لتعــدد ســوابقه وأثبــت التقريــر الكيمائــي الشــرعي إيجابيــة العينــة‬\n‫لنبــات القــات احملظــور ‪،‬مصادقــة املدعــى عليهمــا علــى الدعــوى‪ ،‬وبنــاء‬\n‫علــى مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليهمــا بســجن األول‬\n‫ثــاث ســنوات وجلــده ‪ 500‬جلــده والثانــي بخمــس ســنوات وجلــده ‪700‬‬\n‫جلــده وإبعادهمــا عــن البــاد وقنــع املدعــى عليهمــا واعتــرض املدعــي‬\n\n                                                                                    ‫‪88‬‬\n\f            ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n                                                   ‫العــام بــدون الئحــة ُ‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزائيــة بجــازان برقــم ‪ 34163330‬وتاريــخ ‪1434/04/09‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 34869065‬وتاريــخ ‪1434/04/09‬ه ـ ففــي يــوم‬\n     ‫األربعــاء املوافق‪1434/04/10‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 15‬‬\n     ‫وفيهــا حضــر املدعــي العــام ‪.....‬بالتعميــد رقــم (‪ ).....‬يف ‪1433/3/22‬ه ـ‬\n     ‫واملدعــى عليهمــا ‪.....‬مينــي اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪).....‬‬\n     ‫و‪ .....‬مينــي اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ ).....‬وقــدم املدعــي‬\n     ‫العــام دعــوى محــررة تتضمــن ‪ :‬أنــه بتاريــخ ‪1434/2/25‬ه ـ وأثنــاء قيــام‬\n     ‫إحــدى دوريــات حــرس احلــدود بواجبهــا مت مشــاهدة أربعــة أشــخاص‬\n     ‫كانــوا متواجديــن مــن الشــبك احلــدودي مــن اجلهــة الغربيــة شــرق قريــة‬\n     ‫‪.....‬ومبراقبتهــم شــاهدوا أشــخاص يقومــون برمــي أكيــاس ال يعــرف‬\n     ‫مــا بداخلهــا مــن فــوق الشــبك ويقــوم األشــخاص األربعــة باســتقبال‬\n     ‫الكميــات وبالتوجــه إليهــم الذوا بالفــرار إلــى قريــة ‪.....‬وباللحــاق بهــم‬\n     ‫مت القبــض علــى اثنــن منهــم واتضــح أنهمــا املدعــى عليهمــا وكان‬\n     ‫بحــوزة املدعــى عليــه ‪.....‬مــا وزنــه (‪ 9‬كجــم) تســعة كيلــو جرام ـ ًا مــن‬\n     ‫نبــات القــات احملظــور وبحــوزة ‪.....‬مــا وزنــه (‪ 12‬كجــم) اثنــا عشــر‬\n     ‫كيلــو جرام ـ ًا مــن نبــات القــات احملظــور ولــم يتمكــن أفــراد الدوريــة‬\n     ‫مــن القبــض علــى اآلخريــن وقــد أثبــت التقريــر الكيميائــي الشــرعي‬\n     ‫رقــم (‪ ).....‬وتاريــخ ‪1434/15‬ه ـ ايجابيــة العينــات املرســلة لنبــات‬\n\n‫‪89‬‬\n\f‫القــات احملظــور وباســتجواب املدعــى عليهمــا ومبواجهتهمــا بالتهمــة‬\n‫املنســوبة إليهمــا أقــرا بتلقيهمــا الكميــة املضبوطــة معهمــا مــن نبــات‬\n‫القــات احملظــور وأفــادا بــأن غرضهمــا مــن تلقــي الكميــة ايصالــه‬\n‫إلــى شــخص مينــي يف قريــة ‪.....‬الســعودية مقابــل االســتخدام ملــا قيمتــه‬\n‫عشــرون ريــال لــكل حبــة قــات وقــد أســفر التحقيــق معهمــا عــن توجيــه‬\n‫االتهــام إليهمــا بتلقــي األول مــا وزنــه (‪ 12‬كجــم) اثنــا عشــر كيلــو‬\n‫جرام ـ ًا مــن نبــات القــات احملظــور واملهــرب مــن اليمــن الــى الســعودية‬\n‫بقصــد االجتــار وتلقــي الثانــي مــا وزنــه (‪ 9‬كجــم) تســعة كيلــو جرامـ ًا‬\n‫مــن نبــات القــات احملظــور واملهــرب مــن اليمــن الــى الســعودية بقصــد‬\n‫االجتــار وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء يف أقوالهمــا املنــوه‬\n‫عنهــا واملدونــة علــى محاضــر االســتجواب املرفقــة ‪ -2‬مــا جــاء محضــر‬\n‫القبــض والتفتيــش املرفــق ‪ -3‬مــا جــاء يف التقريــر الكيميائــي املنــوه‬\n‫عنــه واملرفــق وحيــث إن مــا أقــدم عليــه املذكوريــن فعــل محــرم شــرع ًا‬\n‫ومعاقــب عليــه نظام ـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام‬\n‫‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات لــذا أطلــب مــا يلــي ‪ :‬إثبــات إدانتهمــا‬\n‫مبــا أســند إليهمــا واحلكــم عليهمــا مبــا يلــي‪ /1 :‬بتعزيره يف ضــوء الفقرة‬\n‫(أ) مــن املــادة (األولــى) مــن القــرار الــوزاري املشــار إليــه أعــاه إنفــاذ ًا‬\n‫لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ يف ‪1432/12/9‬ه ـ ‪/2‬‬\n‫وإبعادهمــا عــن البــاد بعــد انتهــاء محكوميتهمــا اســتنادا لتعميــم وزيــر‬\n‫الداخليــة رقــم ( ‪ )69935‬بتاريــخ ‪1433/6/18‬ه ـ ‪ /3‬تشــديد العقوبــة‬\n‫علــى الثانــي نظــر ًا لتعــدد ســوابقه وبســؤال املدعــى عليهمــا ‪.....‬و‪ .....‬مينــي‬\n‫اجلنســية أجــاب املدعــى عليــه األول بتلقــي مــا وزنــه اثنــا عشــر كيلــو‬\n‫جرامـ ًا مــن نبــات القــات احملظــور مــن مهــرب مــن اليمــن إلــي الســعودية‬\n\n\n                                                                                         ‫‪90‬‬\n\f     ‫حلســاب الغيــر مقابــل مبلــغ مالــي وأجــاب املدعــى عليــه الثانــي ‪.....‬مينــي‬\n     ‫اجلنســية باالعتــراف بتلقــي مــا وزنــه تســعة كيلــو جرام ـ ًا مــن نبــات‬\n     ‫القــات احملظــور مــن مهــرب مــن اليمــن إلــي الســعودية حلســاب الغيــر‬\n     ‫مقابــل مبلــغ مالــي كمــا أقــر كل واحــد منهمــا بالســوابق املســجلة عليــه‬\n     ‫بالئحــة االدعــاء العــام هكــذا أجــاب املدعــى عليهمــا عنــد ذلــك جــرى‬\n     ‫منــا االطــاع علــى التقريــر الكيميائــي الشــرعي وعلــى محضــري الوزن‬\n     ‫والقبــض فوجــدت متطابقــة ملــا جــاء بالدعــوى وبنــاء علــى مــا ذكــر مــن‬\n     ‫دعــوى املدعــي العــام وعلــى إجابــة املدعــى عليهمــا ‪.....‬و‪ .....‬مينــي اجلنســية‬\n     ‫باالعتــراف بتلقــي األول ملــا وزنــه اثنــا عشــر كيلــو جرامـ ًا وتلقــي الثانــي‬\n     ‫ملــا وزنــه تســعة كيلــو جرام ـ ًا مــن نبــات القــات احملظــور مــن مهــرب‬\n     ‫مــن اليمــن إلــي الســعودية حلســاب الغيــر مقابــل مبلــغ مالــي لــذا فقــد‬\n     ‫ثبــت لــدي شــرع ًا إدانــة املدعــى عليهمــا املذكوريــن بتلقــي كل واحــد‬\n     ‫منهمــا لكميــة نبــات القــات احملظــور املوضحــة أعــاه مــن مهــرب مــن‬\n     ‫اليمــن إلــي الســعودية حلســاب الغيــر مقابــل مبلــغ مالــي لقصــد الترويــج‬\n     ‫وهمــا يســتحقان العقوبــة علــى ذلــك وفــق الفقــرة (أ) مــن املــادة األولــى‬\n     ‫مــن قــرار ســمو وزيــر الداخليــة رقــم (‪ )2057‬وتاريــخ ‪1404 /5/26‬ه ـ‬\n     ‫اســتناد ًا لقــرار مجلــس الــوزراء رقــم (‪ )11‬وتاريــخ ‪1374/2/1‬ه ـ وإنفــاذ ًا‬\n     ‫لألمــر الســامي رقــم (‪ )59633‬يف ‪1432/12/9‬ه ـ وملــا ذكــر أعــاه‬\n     ‫فقــد حكمــت بتعزيــر املدعــى عليــه األول بالســجن ملــدة خمــس ســنوات‬\n     ‫وتعزيــر املدعــى عليــه الثانــي بالســجن ملــدة ســبع ســنوات لكثرة ســوابقه‬\n     ‫وجلــد األول بخمســمائة جلــدة وجلــد الثانــي بســبعمائة جلــدة علن ًا مفرقة‬\n     ‫كل دفعــة خمســون جلــدة واألخــرى عشــرة أيــام وغرامــة ماليــة علــى‬\n     ‫كل واحــد منهمــا قدرهــا خمســة أالف ريــال تــودع بيــت مــال املســلمني‬\n\n\n‫‪91‬‬\n\f‫ويبعــدان عــن البــاد بعــد إنفــاذ العقوبــة املقــررة بحقهمــا شــرع ًا وال‬\n‫يســمح لهمــا بالعــودة إليهــا عــدا مــا تســمح بــه تعليمــات احلــج والعمــرة‬\n‫هــذا مــا حكمــت بــه وبعرضــه علــى الطرفــن قــرر املدعــى عليــه القناعــة‬\n‫وطلــب املدعــي العــام اســتئناف احلكــم مكتفيـ ًا بالئحــة االدعــاء العــام‬\n‫وأمــرت بتنظيــم القــرار الــازم مبوجبــه ورفعــه حملكمــة االســتئناف‬\n‫مبنطقــة عســير لدراســته وإبــداء مــا تــراه نحــوه وصلــى اهلل علــى نبينــا‬\n                      ‫محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/4/10‬ه ـ‬\n‫ـاء علــى مالحظــة أصحــاب القضــاة قضــاة‬        ‫احلمــد هلل وحــده وبعــد فبنـ ً‬\n‫الدائــرة الثالثــة لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف‬\n‫مبنطقــة عســير بقرارهــم رقــم ‪ 34222204‬وتاريــخ ‪1434/5/26‬ه ـ علــى‬\n‫القــرار الصــادر منــا برقــم ‪ 34198977‬وتريــخ ‪1434/4/27‬ه ـ اخلــاص‬\n‫بدعــوى املدعــي العــام ضــد كل مــن ‪.....‬و‪.....‬مينــي اجلنســية يف قضيــة‬\n‫قــات علــى الصفــة املوضحــة يف القــرار املتضمــن حكمنــا مبــا هــو مــدون‬\n‫ومفصــل فيــه ونــص قــرار أصحــاب الفضيلــة بدراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة تقــرر إعادتهــا لفضيلــة حاكمهــا ملالحظــة أن‬\n‫احلكــم علــى املدعــى عليهمــا كثيــر جــد ًا الســيما وأن الكميــة قليلــة‬\n‫فعلــى فضيلتــه إعــادة النظــر يف احلكــم وإكمــال الــازم واهلل املوفــق‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه وســلم أنتهــى نصــه‬\n‫وبنــاء عليــه وجتاوبــا مــع أصحــاب الفضيلــة بــأن مــا قررنــاه مــن تعزيــر‬\n‫بحــق املدعــى عليهمــا يتناســب مــع جرمهمــا وكثــرة ســوابقهما وخاصــة‬\n‫املدعــى عليــه الثانــي فعليــه خمــس ســوابق منوعــة وقــد ســجن يف بعضهــا‬\n‫ســبع ســنوات ولــم يرتــدع بالعقوبــة التــي نالهــا وعلــى املدعــى عليــه األول‬\n‫ســابقة واحــدة ممــا ثلــة ومــع هــذا وجتاوبـ ًَا مــع أصحــاب الفضيلــة فقــد‬\n\n\n                                                                                     ‫‪92‬‬\n\f     ‫قــررت تخفيــف ســجن كل واحــد مــن املدعــى عليهمــا ســنتني ليصبــح‬\n     ‫ســجن املدعــى عليــه األول ثــاث ســنوات وســجن املدعــى الثانــي خمــس‬\n     ‫ســنوات مــن التاريــخ املوضــح باحلكــم مــع بقــاء حكمنــا فيمــا عــدى‬\n     ‫ذلــك علــى مــا هــو عليــه وجــرى منــا عــرض ذلــك علــى املدعــي العــام بقــي‬\n     ‫املدعــي العــام علــى اعتراضــه الســابق وأمــرت بإحلــاق مــا ذكــر بالقــرار‬\n     ‫وضبطــه وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر‬\n                                                                  ‫يف ‪1434/6/14‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n     ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n     ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان رقــم‬\n     ‫‪ 341426187‬وتاريــخ ‪1434/6/21‬ه ـ املرفــق بهــا القــرار الشــرعي‬\n     ‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪..... /‬رقــم ‪34198977‬‬\n     ‫وتاريــخ ‪1434/4/27‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد كل مــن‪/‬‬\n     ‫‪.....‬و ‪ (.....‬مينــي اجلنســية ) يف قضيــة ( قــات ) علــى الصفــة املوضحــة يف‬\n     ‫القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وحيــث‬\n     ‫ســبق دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى‬\n     ‫ـاء علــى قرارنــا‬\n                      ‫مــا أجــاب بــه فضيلتــه وأحلقــه بالقــرار وصــورة ضبطــه بنـ ً‬\n     ‫رقــم ‪ 34222204‬وتاريــخ ‪1434/5/26‬ه ـ تقــررت املوافقــة علــى احلكــم‬\n     ‫بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                     ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪93‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":88,"source_page_end":93,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a82673090b0a7eb26e2f142c4506c834c602b111ff4645975a5b4522fed93034","normalized_text_hash":"003c590722a338d3e3d45489996ad87731ec38c0b285f9ed1e35c2a6aad11d8a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p88-34198977"},{"id":"3342d2c3-b2c3-5d53-b67e-9c98baf6079f","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تهريب احلبوب احملظورة «الكبتاجون» -رجوع عن إقرار مصدق شرع ا -الرجوع عن االقرار مبا يوجب التعزير اليقبل - من لم يندفع فساده اال بالقتل يقتل -التعزير بالقتل ومصادرة السيارة واجلوال املستخدمة يف اجلرمية.","document_number":"34279643","case_number":"34243103","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/25","year":"1434","subject":"مخدرات -تهريب احلبوب احملظورة «الكبتاجون» -رجوع عن إقرار مصدق شرع ا -الرجوع عن االقرار مبا يوجب التعزير اليقبل - من لم يندفع فساده اال بالقتل يقتل -التعزير بالقتل ومصادرة السيارة واجلوال املستخدمة يف اجلرمية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 34279643 :‬تاريخه‪1434/7/25 :‬هـ رقم‬\n                            ‫الدعوى‪34243103 :‬‬\n‫رقم قرار التصديق من محكمة االستئناف‪34350294 :‬‬\n                          ‫تاريخه‪1434/11/4 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬تهريــب احلبــوب احملظــورة «الكبتاجــون» ‪ -‬رجــوع عــن إقــرار‬\n      ‫مصــدق شــرع ًا‪ -‬الرجــوع عــن االقــرار مبــا يوجــب التعزيــر اليقبــل ‪-‬‬\n      ‫مــن لــم يندفــع فســاده اال بالقتــل يقتــل ‪ -‬التعزيــر بالقتــل ومصــادرة‬\n                                   ‫الســيارة واجلــوال املســتخدمة يف اجلرميــة‪.‬‬\n\n\n\n\n      ‫‪ -‬قولــه تعالــى‪« :‬إمنــا جــزاء الذيــن يحاربــون اهلل ورســوله ويســعون يف‬\n      ‫األرض فســاد ًا أن يقتلــوا أو يصلبــوا أو تقطــع أيديهــم وأرجلهــم مــن‬\n                                                         ‫خــاف) اآليــة [املائــدة‪]33:‬‬\n      ‫‪ -‬قــال ابــن قدامــة رحمــه اهلل‪( :‬وال يقبــل رجــوع املقــر عــن إقــراره إال‬\n      ‫فيمــا كان حــدا هلل تعالــى يــدرأ بالشــبهات‪ ،‬ويحتــاط إلســقاطه فأمــا‬\n      ‫حقــوق اآلدميــن وحقــوق اهلل تعالــى التــي ال تدرأ بالشــبهات كالزكاة‬\n      ‫والكفــارات‪ ،‬فــا يقبــل رجوعــه عنهــا وال نعلــم يف هــذا خالفــا ) أ‪.‬ه ـ‬\n                                                                       ‫املغنــي‪469/4 :‬‬\n      ‫‪ -‬قــال يف كشــاف القنــاع‪( :‬ويكــون التعزيــر بالضرب واحلبس والصفع‬\n      ‫والتوبيــخ والعــزل عــن الواليــة وقــال يف االختيــارات إذا كان املقصــود‬\n      ‫دفــع الفســاد ولــم يندفــع إال بالقتــل قتــل وحينئــذ فمــن تكــرر منــه‬\n      ‫جنــس الفســاد ولــم يرتــدع باحلــدود املقــدرة بــل اســتمر علــى الفســاد‬\n                               ‫فهــو كالصائــل ال يندفــع إال بالقتــل فيقتل)أ‪.‬ه ـ‬\n      ‫وقــال‪( :‬وقــال الشــيخ يعــزر أي مــن وجــب عليــه التعزيــر مبــا يردعــه ألن‬\n                                                                                         ‫‪94‬‬\n\f     ‫القصــد الــردع وقــد يقــال بقتلــه أي مــن لزمــه التعزيــر للحاجة)أ‪.‬ه ـ‬\n                                                   ‫كشــاف القنــاع‪.)120/14( :‬‬\n     ‫‪ -‬مــا جــاء يف قــرار هيئــة كبــار العلمــاء رقــم ( ‪ ) 138‬الصــادر عــن‬\n     ‫مجلــس هيئــة كبــار العلمــاء يف دورتــه التاســعة والعشــرين املنعقــدة‬\n     ‫مبدينــة الريــاض بتاريــخ ‪1407 /6/9‬ه ـ وحتــى‪1407 /6/20‬هــ‪( :‬أوال‬\n     ‫بالنســبة ملهــرب املخــدرات فــإن عقوبتــه القتــل ملــا يســببه تهريــب‬\n     ‫املخــدرات وإدخالهــا البــاد مــن فســاد عظيــم ال يقتصــر علــى املهــرب‬\n     ‫نفســه وأضــرار جســيمة وأخطــار بليغــة علــى األمــة مبجموعهــا ويلحــق‬\n     ‫باملهــرب الشــخص الــذي يســتورد أو يتلقــى املخــدرات مــن اخلــارج‬\n                                                     ‫فيم ـ ّون بهــا املروجني)أ‪.‬ه ـ‬\n     ‫‪ -‬الفقــرة األولــى مــن املــادة الســابعة والثالثــن مــن نظــام مكافحــة‬\n     ‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )37‬يف‬\n                                                                 ‫‪1426/7/8‬هــ‪.‬‬\n\n\n\n\n     ‫أســفر التحقيــق مــع املدعــى عليــه عــن اتهامــه بتهريــب كميــة مــن حبوب‬\n     ‫اإلمفيتامــن املنبــه للجهــاز العصبــي احملظــور البالــغ عددهــا مائتــان‬\n     ‫وتســعة آالف ومائــة وعشــر حبــات‪ ،‬طلــب املدعــي العــام إثبــات مــا أســند‬\n     ‫إلــى املدعــى عليــه‪ ،‬واحلكــم عليــه بالقتــل تعزيــرا‪ ،‬ومصــادرة الســيارة‪،‬‬\n     ‫واجلــوال املســتخدمة يف اجلرميــة‪ ،‬وفــق نظــام مكافحــة املخــدرات‬\n     ‫واملؤثــرات العقليــة ‪ ،‬لــم يســجل علــى املدعــى عليــه أي ســوابق‪ ،‬بعــرض‬\n     ‫دعــوى املدعــي العــام علــى املدعــى عليــه أنكرهــا‪ ،‬ودفــع أن الكميــة‬\n     ‫وجــدت يف ســيارته وأنــه ليــس هــو الــذي وضعهــا‪ ،‬وال يعلــم عنهــا‪ ،‬جــرى‬\n\n‫‪95‬‬\n\f‫االطــاع علــى إقــرار املدعــى عليــه املصــدق شــرعا‪ ،‬كما جــرى االطالع‬\n‫علــى محضــر الضبــط‪ ،‬كمــا جــرى االطــاع علــى التقريــر الكيميائــي‬\n‫الشــرعي املتضمــن أنــه بالفحــص الكيميائــي الشــرعي حملتويــات احلــرز‬\n‫املرســل ثبــت إيجابيــة العينــة ملــادة اإلمفيتامــن ‪ ،‬بعــرض أدلــة املدعــي‬\n‫العــام علــى املدعــى عليــه‪ ،‬أنكــر إقــراره املصــدق شــرعا‪ ،‬ودفــع أنــه‬\n‫أخــذ منــه بالقــوة وأنــه ال بينــة لــه علــى ذلــك‪ ،‬وصــادق علــى مــا جــاء يف‬\n‫محضــر الضبــط‪ ،‬وقــرر عــدم علمــه مبــا جــاء يف التقريــر الكيميائــي‬\n‫الشــرعي ‪ ،‬نظــر ًا إلنــكار املدعــى عليــه مــا جــاء يف دعــوى املدعــي العام‬\n‫جملــة وتفصي ـاً‪ ،‬وملــا جــاء يف اعتــراف املدعــى عليــه املصــدق شــرعاً‪،‬‬\n‫واملتضمــن صحــة مــا ذكــره املدعــي العــام يف دعــواه‪ ،‬وإلنــكار املدعــى‬\n‫عليــه هــذا االعتــراف جملــة وتفصيــا ودفعــه بأنــه أخــذ منــه بالقــوة وال‬\n‫بينــة لــه علــى ذلــك‪ ،‬وألن الرجــوع عــن اإلقــرار مبــا يوجــب التعزيــر ال‬\n‫يقبــل‪ ،‬ولكــون املدعــى عليــه مكلفــا لــذا ثبتــت إدانــة املدعــى عليــه مبــا‬\n‫أســند إلــى املدعــى عليــه‪ ،‬ومت احلكــم بقتلــه تعزيــراً‪ ،‬ومصــادرة ســيارته‬\n‫وجوالــه املوصوفــن يف الدعــوى ‪ ،‬بعــرض احلكــم علــى املدعــى عليــه‬\n‫قــرر اعتراضــه عليــه وطلــب اســتئنافه مــع تقــدمي الئحــة اعتراضيــة‪،‬‬\n‫وال حاجــة لعــرض احلكــم علــى املدعــي العــام ألنــه حكــم لــه بــكل‬\n‫طلباتــه بنــاء علــى املــادة (‪ )174‬مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n‫التنفيذيــة‪ ،‬وبعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقة عليه‪.‬‬\n\n\n\n\n                                                                                      ‫‪96‬‬\n\f     ‫احلمــد هلل وحــده وبعــد يف يــوم الثالثــاء ‪1434/7/25‬ه ـ لدينــا نحــن‬\n     ‫القضــاة باحملكمــة العامــة بتبــوك ‪ ......‬و‪ ......‬و‪ ......‬وبنــاء علــى ورود‬\n     ‫املعاملــة إلــى احملكمــة العامــة بتبــوك بخطاب رئيس فــرع هيئة التحقيق‬\n     ‫واإلدعــاء العــام مبنطقــة تبــوك رقــم ‪ 8776‬يف ‪1434/5/7‬ه ـ واملقيــدة يف‬\n     ‫احملكمــة برقــم ‪ 341175324‬يف ‪1434/5/13‬ه ـ واحملالــة إلينــا مــن‬\n     ‫فضيلــة الرئيــس برقــم ‪ 34243103‬يف ‪1434/5/26‬ه ـ والتــي ســبق وأن‬\n     ‫صــدر فيهــا قــرار مــن هــذه احملكمــة برقــم ‪/3/3‬ض يف ‪1431/4/28‬هـ‬\n     ‫ومت نقضــه مبوجــب القــرار الصــادر مــن الدائــرة اجلزائيــة األولــى‬\n     ‫باحملكمــة العليــا رقــم ‪ 3/1/19‬يف ‪1434/3/21‬ه ـ بشــأن دعــوى‬\n     ‫املدعــي العــام ضــد ‪ ......‬بشــأن قضيــة تهريــب مخــدرات فتحــت اجللســة‬\n     ‫األولــى يف متــام الســاعة الثامنــة وفيهــا حضــر املدعــي العام ‪ ......‬الســعودي‬\n     ‫بالســجل املدنــي رقــم ‪ ......‬مبوجــب خطــاب التكليــف الصــادر مــن‬\n     ‫ســعادة رئيــس فــرع هيئــة التحقيــق واإلدعــاء العــام بتبــوك رقــم ‪ ......‬يف‬\n     ‫‪1433/9/5‬ه ـ وادعــى علــى احلاضــر معــه ‪ ......‬الســعودي بالســجل املدنــي‬\n     ‫رقــم ‪ ......‬قائــا يف حتريــر دعــواه بصفتــي مدعيــا عامــا بدائــرة اإلدعــاء‬\n     ‫العــام لفــرع الهيئــة مبنطقــة تبــوك أدعــي علــى احلاضــر ‪ ......‬إنــه بتاريــخ‬\n     ‫‪1430/4/28‬ه ـ قــدم املدعــى عليــه مــن دولــة األردن إلــى منفــذ الــدرة‬\n     ‫الســعودي وعنــد تفتيــش ســيارته مــن نــوع ‪ ....‬يحمــل اللوحــة رقــم ‪ ......‬مت‬\n     ‫اشــتباه موظــف اجلمــرك بخــزان الوقــود األساســي وعنــد إنزالــه وفتحــه‬\n     ‫وجــد بداخلــه كميــة مــن احلبــوب يشــتبه أن تكــون مــن حبــوب‬\n     ‫الكبتاجــون املخــدرة احملظــورة بلــغ عددهــا مائتــن وتســعة آالف ومائــة‬\n\n‫‪97‬‬\n\f‫وعشــر ‪209110‬حبــة موزعــة علــى أكيــاس بالســتيك وكان يرافــق‬\n‫املدعــى عليــه أثنــاء القبــض عليــه اثنــان مــن أبنائــه وأثنــاء وجــوده داخــل‬\n‫اجلمــرك ورده اتصــال مــن رقــم أردنــي (‪ ) ......‬وذكــر أن املتصــل هــو‬\n‫مكفولــه املدعــو ‪ ......‬أردنــي اجلنســية ولديــه إقامــة ســائق خــاص وقــال‬\n‫لــه (هــل خرجــت مــن اجلمــرك؟ قــال لــه نعــم) ثــم اتصــل عليــه مــرة أخــرى‬\n‫إال أنــه أقفــل جوالــه وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم ‪......‬‬\n‫لعــام ‪1430‬ه ـ الصــادر مــن مراقبة الســموم والكيمياء الطبية الشــرعية‬\n‫بصحــة تبــوك ثبــوت إيجابيــة العينــة املضبوطــة ملــادة األمفيتامــن املنبــه‬\n‫للجهــاز العصبــي املركــزي واملــدرج باجلــدول رقــم (‪ )2‬فئــة (ب) مــن‬\n‫تعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم (‪)89400/19‬‬\n‫وتاريــخ ‪1426/10/25‬ه ـ وباســتجواب املدعــى عليــه أقــر أنــه بتاريــخ‬\n‫‪1430/4/28‬ه ـ قــدم مــن دولــة األردن إلــى الســعودية عبــر منفــذ الــدرة‬\n‫علــى ســيارته مــن نــوع ‪ .....‬يحمــل اللوحــة رقــم ‪ ......‬وعنــد إجــراء التفتيــش‬\n‫علــى ســيارته عثــر موظــف اجلمــارك بداخــل خــزان الوقــود لســيارته علــى‬\n‫كميــة مــن احلبــوب احملظــورة بلــغ عددهــا مائتــن وتســعة آالف ومائــة‬\n‫وعشــر ‪209110‬حبــة واعتــرف بــأن هــذه الكميــة تعــود لشــخص أردنــي‬\n‫يدعــى ‪ ......‬حيــث أنــه يف نفــس اليــوم وعندمــا كان يف األردن اتصــل‬\n‫عليــه املدعــو ‪ ......‬علــى جوالــه وطلــب منــه احلضــور إلــى منزلــه عصــرا يف‬\n‫‪ ......‬بــاألردن وتوجــه إلــى منــزل املدعــو ‪ ......‬يف األردن وعــرض عليــه‬\n‫تركيــب خــزان الوقــود املخــزن بداخلــه كميــة احلبــوب احملظــورة وطلب‬\n‫منــه تركيبــه علــى ســيارته ومــن ثــم إدخالــه إلــى الســعودية عبــر منفــذ‬\n‫الــدرة فوافــق علــى ذلــك ثــم توجــه إلــى الســعودية فتــم القبــض عليــه‬\n‫وذكــر أنــه أقــدم علــى هــذا الفعــل لعــدم وجــود دخــل لــه ولكبــر أســرته‬\n\n\n                                                                                        ‫‪98‬‬\n\f     ‫وحاجتــه املاســة للمــال وقــد أســفر التحقيــق مــع املدعــى عليــه عــن اتهامــه‬\n     ‫بتهريــب كميــة مــن حبــوب األمفيتامــن املنبــه للجهــاز العصبــي احملظور‬\n     ‫البالــغ عددهــا مائتــن وتســعة آالف ومائــة وعشــر ‪209110‬حبــة وحيــث‬\n     ‫إن مــا أقــدم عليــه املذكــور فعــل محــرم شــرعا ومجــرم نظامــا اســتنادا‬\n     ‫للمــادة الثالثــة فقــرة (‪ )1‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n     ‫ومعاقــب عليــه بالعقوبــات األصليــة والتكميليــة لــذا أطلــب مــا يلــي ‪-1:‬‬\n     ‫إثبــات مــا أســند إليــه ‪ -2‬احلكــم عليــه بالقتــل تعزيــرا اســتنادا للمــادة‬\n     ‫(‪ )37‬فقــرة (‪ )1‬مــن البنــد أوال مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة املشــار إليــه ‪ -3 -‬احلكــم مبصــادرة الســيارة العائــدة ملكيتهــا‬\n     ‫مــن نــوع ‪ .....‬رقــم اللوحــة ‪ ......‬اللــون بيــج صنــع عــام (‪1991‬م) ومصــادرة‬\n     ‫اجلــوال العائــد لــه مــن نــوع ‪ ....‬الرقــم التسلســلي للجهــاز (‪ ) ......‬اســتنادا‬\n     ‫للمــادة رقــم (‪ )53‬فقــرة (‪ )1‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة املشــار إليــه الســتخدامها يف اجلرميــة (علمــا بــأن املدعــى عليــه‬\n     ‫ليــس مســجل ضــده ســوابق جنائيــة كمــا ذكــر ذلــك يف هــذه الالئحــة)‬\n     ‫هــذه دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب‬\n     ‫قائــا مــا ذكــره املدعــي العــام يف دعــواه غيــر صحيــح جملــة وتفصيــا‬\n     ‫والصحيــح أنــه بتاريــخ ‪1430/4/27‬ه ـ وقبــل قدومــي إلــى منفــذ الــدرة‬\n     ‫بيــوم طلــب منــي مكفولــي ‪ ......‬ســيارتي املوصوفــة يف الدعــوى إليصــال‬\n     ‫ابنتــه إلــى املستشــفى ومكثــت لديــه ســيارتي حوالــي ســبع ســاعات‬\n     ‫وبعدهــا رجــع وأعطانــي ســيارتي ثــم اجتهــت بهــا إلــى منفــذ الــدرة وكان‬\n     ‫يرافقنــي اثنــن مــن أبنائــي وبعــد التفتيــش علــى ســيارتي مــن قبــل رجــال‬\n     ‫اجلمــرك وجــدوا معــي الكميــة املذكــورة ولســت أنــا الــذي وضعتهــا يف‬\n\n\n‫‪99‬‬\n\f‫ســيارتي وال أعلــم عــن هــذه احلبــوب الكبتاجــون احملظــورة شــيئا ولــم‬\n‫يتصــل علــي مكفولــي يف اجلمــرك ولــم أتصــل عليــه وأنــا بــرئ مــن هــذه‬\n‫القضيــة هــذه إجابتــي وجــرى ســؤال املدعــي العــام عــن بينتــه علــى دعــواه‬\n‫أجــاب قائــا بينتــي هــي مــا يلــي‪ -1 :‬إقــراره املصــدق شــرعا املــدون علــى‬\n‫الصفحــة رقــم (‪ )6‬لفــة رقــم (‪ -2 )1‬محضــر الضبــط املــدون علــى اللفــة‬\n‫رقــم (‪ -3 )5‬التقريــر الكيميائــي الشــرعي املــدون علــى اللفــة رقــم (‪)14‬‬\n‫هــذه بينتــي وجــرى منــا االطــاع علــى الدليــل األول مــن أدلــة املدعــي‬\n‫العــام وهــو إقــرار املدعــى عليــه املــدون علــى الصفحــة رقــم (‪ )6‬لفــة رقــم‬\n‫(‪ )1‬ونصــه (أقــر أنــا املدعــو ‪ ......‬ســعودي اجلنســية مبوجــب الهويــة رقــم‬\n‫(‪ ) ......‬صــادرة مــن حقــل بتاريــخ ‪1403/10/29‬ه ـ عاطــل عــن العمــل‬\n‫أبلــغ مــن العمــر حوالــي (‪ 44‬ســنة) أقــر أنه بتاريــخ ‪1430/4/28‬هـ قدمت‬\n‫مــن األردن إلــى الســعودية عبــر منفــذ الــدرة علــى ســيارتي نــوع ‪ ....‬حتمــل‬\n‫اللوحــة رقــم ‪ ......‬وعنــد إجــراء التفتيــش علــى ســيارتي عثــر موظــف‬\n‫اجلمــرك بداخــل خــزان الوقــود العائــد لســيارتي علــى كميــة مــن حبــوب‬\n‫الكبتاجــون بلــغ عددهــا مائتــن وتســعة آالف ومائــة وعشــرة ‪209110‬‬\n‫حبــة وهــذه الكميــة مــن احلبــوب تعــود أصــا لشــخص أردنــي يعمــل‬\n‫حتــت كفالتــي مبهنــة ســائق خــاص ويســكن األردن ويدعــى ‪ ......‬حيــث‬\n‫أنــه يف يــوم القبــض علــي وعندمــا كنــت بــاألردن اتصــل علــى جوالــي ‪....‬‬\n‫يطلــب منــي احلضــور إلــى منزلــه عصــرا الــذي يقــع يف مدينــة ‪ ......‬األردنية‬\n‫وفعــا توجهــت لــه ومبنزلــه عــرض علــي تركيــب تانكــي الوقــود الــذي‬\n‫بــه احلبــوب علــى ســيارتي وإدخالــه إلــى حقــل عبــر منفــذ الــدرة ولــم يحــدد‬\n‫لــي املبلــغ قيمــة قيامــي بذلــك العمــل فوافقــت علــى ذلــك وقــام هــو بفــك‬\n‫خــزان الوقــود األساســي بســيارتي وتركيــب خــزان الوقــود الــذي‬\n\n\n                                                                                       ‫‪100‬‬\n\f      ‫بداخلــه كميــة احلبــوب ومــن ثــم توجهــت إلــى الســعودية ومت القبــض‬\n      ‫علــي كمــا أنــه أثنــاء تواجــودي داخــل اجلمــرك وقــت القبــض علــي اتصــل‬\n      ‫بــي ‪ .....‬مــن جوالــه األردنــي رقــم (‪ ) ......‬وقــال لــي هــل خرجــت مــن‬\n      ‫اجلمــرك قلــت لــه نعــم وقمــت باالتصــال عليــه مــرة أخــرى إال أنــه أقفــل‬\n      ‫جوالــه وهــذه هــي املــرة األولــى التــي أقــوم بهــا بتهريــب املمنوعــات إلــى‬\n      ‫البــاد وال يوجــد لــي أي ســوابق وال أســتعمل أي نــوع مــن املخــدرات وأن‬\n      ‫إقدامــي علــى هــذا الفعــل هــو حاجتــي املاســة للمــال حيــث ال يوجــد لــدي‬\n      ‫أي دخــل مــادي ولــدي أســرة مكونــة مــن ثمانيــة أشــخاص وأنــا نــادم‬\n      ‫علــى هــذا الفعــل الــذي قمــت بــه هــذا إقــراري عليــه أوقــع واهلل املوفــق)‬\n      ‫أ‪.‬ه ـ املقــر مبــا فيــه ‪ ......‬بصمتــه شــاهد ‪ ......‬توقيعــه شــاهد ‪ ......‬توقيعــه‬\n      ‫وجــرى منــا االطــاع علــى الدليــل الثانــي مــن أدلــة املدعــي العــام وهــو‬\n      ‫محضــر الضبــط املــدون علــى اللفــة رقــم (‪ )5‬ونــص احلاجــة منــه (محضــر‬\n      ‫ضبــط رقــم (‪ )40‬بتاريــخ ‪1430/4/29‬ه ـ وصفــا كامــا لكيفيــة‬\n      ‫الضبــط‪ :‬بقــدوم الســيارة بقيــادة مالكهــا ‪ ......‬ويرافقه أطفاله وعددهم‬\n      ‫اثنــان ولــدى إجــراء التفتيــش اشــتبه املفتــش اجلمركــي بخــزان الوقــود‬\n      ‫األساســي ولــدى إنزالــه وفتحــه تبــن أنــه مقســوم مــن الداخــل إلــى‬\n      ‫قســمني اجلــزء األصغــر مخصــص للوقــود واآلخــر مخبــأ فيــه كميــة مــن‬\n      ‫احلبــوب التــي يشــتبه أنهــا إفيتامــن وهــي دائريــة علــى أحــد جوانبهــا‬\n      ‫قوســن واجلانــب اآلخــر خــط مســتقيم بلــغ عددهــا مائتــن وتســعة آالف‬\n      ‫ومائــة وعشــر حبـ‪ 209110‬ــات موزعــة علــى أكيــاس بالســتيكية‬\n      ‫عددهــا مائــة وأربعــة وثمانــن كيـ‪ 184‬ــسا علــى النحــو التالــي (ثمانيــة‬\n      ‫عشــر كيـ‪ 18‬ــسا عليــه صــورة إشــارة لكــزس يف كل كيــس ألفــن‬\n      ‫وخمســن حبـ‪ 2050‬ــة لونهــا بيــج) (ســتة أكيـ‪ 6‬ــاس عليهــا صــورة متســاح‬\n\n\n‫‪101‬‬\n\f‫يف كل كيــس ألفــن وخمســة وثالثــن حبـ‪ 2035‬ــة لونهــا بنــي فــاحت)‬\n‫(مائــة وســبع وأربعــن كيـ‪ 147‬ــسا عليهــا صــورة إشــارة لكــزس يف‬\n‫كل كيــس ألــف حبـ‪ 1000‬ــة لونهــا أصفــر فاحت))أ‪.‬ه ـ الضابــط‬\n‫والضابطــون ‪ ......‬توقيعــه ‪ ......‬توقيعــه ‪ ......‬توقيعــه ‪ ......‬توقيعــه وجــرى‬\n‫منــا االطــاع علــى الدليــل الثالــث مــن أدلــة املدعــي العــام وهــو التقريــر‬\n‫الكيميائــي الشــرعي املــدون علــى اللفــة رقــم (‪ )14‬ونــص احلاجــة منــه‬\n‫(تقريــر كيميائــي شــرعي رقــم (‪ ) ......‬بالفحــص الكيميائــي الشــرعي‬\n‫حملتويــات احلــرز املرســل واملنــوه انــه صنــدوق خشــبي مرصــص يحــوى‬\n‫عــدد خمســة عشــر حبــة كالتالــي‪( :‬خمــس حبــات لونهــا أصفــر فــاحت)‬\n‫(خمــس حبــات لونهــا بنــي فــاحت) (خمــس حبــات لونهــا بيــج) ثبــت لدينــا‬\n‫اآلتي‪ :‬املرســل عبارة عن صندوق خشــبي بداخله خمســة عشــر حبـ‪ 15‬ــة‬\n‫كالتالــي ‪ -1‬كيــس بالســتيك شــفاف يحــوي خمــس حبـ‪ 5‬ــات مصفــرة‬\n‫اللــون ثبــت إيجابيــة العينــة لألمفيتامــن ‪ -2‬كيــس بالســتيك شــفاف‬\n‫يحــوي خمــس حبـ‪ 5‬ــات بنيــة اللــون ثبــت إيجابيــة العينــة لألمفيتامــن ‪-3‬‬\n‫كيــس بالســتيك شــفاف يحــوي خمــس حبـ‪ 5‬ــات بيــج اللون ثبــت إيجابية‬\n‫العينــة لألمفيتامــن هــذا وقــد اســتهلكت العينــة خــال الفحص)أ‪.‬ه ـ‬\n‫وبعــرض أدلــة املدعــي العــام علــى املدعــى عليــه أجــاب قائــا مــا ذكــره‬\n‫املدعــي العــام يف دليلــه األول وهــو إقــراري املصــدق شــرعا غيــر صحيــح‬\n‫وقــد أخــذ منــي بالقــوة وال بينــة لــي علــى ذلــك ومــا ذكــره املدعــي العــام‬\n‫يف دليلــه الثانــي وهــو محضــر الضبــط فصحيــح ومــا ذكــر املدعــي‬\n‫العــام يف دليلــه الثالــث وهــو التقريــر الكيميائــي الشــرعي فــا أعلــم‬\n‫عنــه شــيئا هكــذا أجــاب وجــرى ســؤال املدعــي العــام واملدعــى عليــه‬\n‫هــل لديهمــا مــا يريــدان إضافتــه يف هــذه القضيــة أجــاب املدعــى عليــه‬\n\n\n                                                                                       ‫‪102‬‬\n\f      ‫قائــا إننــي رجــل يتيــم ليــس عنــدي أب وال أم وال إخــوة ولــدي أســرة‬\n      ‫مكونــة مــن تســعة أطفــال وليــس لهــم عائــل بعــد اهلل إال أنــا ومــن فتــرة‬\n      ‫بقائــي يف الســجن وحتــى تاريخــه لــم يذهبــوا أوالدي إلــى املدرســة وليــس‬\n      ‫لــي عالقــة بعمليــة التهريــب هــذه وأطلــب مــن فضيلتكــم النظــر يف‬\n      ‫حالــي هكــذا أجــاب وأجــاب املدعــي العــام ليــس لــدي ســوى مــا قدمــت‬\n      ‫وأطلــب احلكــم يف هــذه القضيــة هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واإلجابــة وإلنــكار املدعــى عليــه مــا جــاء يف دعــوى املدعــي‬\n      ‫ا وإلقــرار املدعــي العــام أن بينتــه علــى صحــة دعــواه‬ ‫العــام جملــة وتفصيـ ً‬\n      ‫هــي اعتــراف املدعــى عليــه املصــدق شــرع ًا واملتضمــن صحــة مــا ذكــره‬\n      ‫املدعــي العــام يف دعــواه وإلنــكار املدعــى عليــه هــذا االعتــراف جملــة‬\n      ‫وتفصيــا ودفعــه بأنــه أخــذ منــه بالقــوة وال بينــة لــه علــى ذلــك وألن‬\n      ‫الرجــوع عــن اإلقــرار مبــا يوجــب التعزيــر ال يقبــل كمــا جــاء ذلــك يف‬\n      ‫كتــاب املغنــي البــن قدامــة رحمــه اهلل ‪ 469/4‬ونــص احلاجــة منــه (وال‬\n      ‫يقبــل رجــوع املقــر عــن إقــراره إال فيمــا كان حــدا هلل تعالــى يــدرأ‬\n      ‫بالشــبهات‪ -‬ويحتــاط إلســقاطه فأمــا حقــوق اآلدميــن وحقــوق اهلل‬\n      ‫تعالــى التــي ال تــدرأ بالشــبهات كالــزكاة والكفــارات‪ -‬فــا يقبــل‬\n      ‫رجوعــه عنهــا وال نعلــم يف هــذا خالفــا )أ‪.‬ه ـ ولقولــه تعالــى يف ســورة‬\n      ‫املائــدة آيــة رقــم (‪( )33‬إمنــا جــزاء الذيــن يحاربــون اهلل ورســوله ويســعون‬\n      ‫يف األرض فســاد ًا أن يقتلــوا أو يصلبــوا أو تقطــع أيديهــم وأرجلهــم مــن‬\n      ‫خــاف) اآليــة وملــا جــاء يف كشــاف القنــاع(‪ )120/14‬مانصه(ويكــون‬\n      ‫التعزيــر بالضــرب واحلبــس والصفــع والتوبيــخ والعــزل عــن الواليــة وقــال‬\n      ‫يف االختيــارات إذا كان املقصــود دفــع الفســاد ولــم يندفــع إال بالقتــل‬\n      ‫قتــل وحينئــذ فمــن تكــرر منــه جنــس الفســاد ولــم يرتدع باحلــدود املقدرة‬\n\n\n‫‪103‬‬\n\f‫بــل اســتمر علــى الفســاد فهــو كالصائــل ال يندفــع إال بالقتــل فيقتل)أ‪.‬ه ـ‬\n‫وجــاء فيــه أيضــا صفحــة رقــم(‪ )120‬مانصه(وقــال الشــيخ يعــزر أي مــن‬\n‫وجــب عليــه التعزيــر مبــا يردعــه ألن القصــد الــردع وقــد يقــال بقتلــه أي‬\n‫مــن لزمــه التعزيــر للحاجة)أ‪.‬ه ـ وملــا جــاء يف قــرار هيئــة كبــار العلمــاء‬\n‫رقــم( ‪ ) 138‬الصــادر عــن مجلــس هيئــة كبــار العلمــاء يف دورتــه التاســعة‬\n‫والعشــرين املنعقــدة مبدينة الريــاض بتأريخ‪1407 /6/9‬هـ وحتى‪/6/20‬‬\n‫‪1407‬ه ـ واملتضمــن قتــل مهــرب املخــدرات داخــل اململكــة إذا رأى‬\n‫حــكام القضيــة ذلــك والــذي جــاء فيــه (أوال بالنســبة ملهــرب املخــدرات‬\n‫فــإن عقوبتــه القتــل ملــا يســببه تهريــب املخــدرات وإدخالهــا البــاد مــن‬\n‫فســاد عظيــم ال يقتصــر علــى املهــرب نفســه وأضــرار جســيمة وأخطــار‬\n‫بليغــة علــى األمــة مبجموعهــا ويلحــق باملهــرب الشــخص الــذي يســتورد أو‬\n‫يتلقــى املخــدرات مــن اخلــارج فيمـ ّـون بهــا املروجني)أ‪.‬ه ـ وملــا نصــت عليــه‬\n‫املــادة الســابعة والثالثــن مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم(م‪)37‬يف ‪1426/7/8‬ه ـ الفقــرة‬\n‫األولى(أوالً‪:‬مــع مراعــاة مــا ورد يف البنــد (ثانيـاً) مــن هــذه املــادة يعاقــب‬\n‫بالقتــل تعزيــرا مــن ثبــت شــرعا بحقــه شــيء مــن األفعــال اآلتيــة‪-1:‬‬\n‫تهريــب مــواد مخــدرة أو مؤثــرات عقلية)أ‪.‬ه ـ ولكــون املدعــى عليــه‬\n‫مكلفــا لذلــك كلــه فقــد حكمنــا مبــا يلــي أوال‪ :‬إثبــات مــا أســند إلــى‬\n‫املدعــى عليــه ‪ ......‬مــن قيامــه بتهريــب الكميــة املذكــورة يف دعــوى‬\n‫املدعــي العــام ثانيــا‪ :‬حكمنــا بقتلــه تعزيــر ًا ثالثــا‪ :‬مصــادرة ســيارته‬\n‫وجوالــه املوصوفــن يف الدعــوى وبذلــك حكمنــا وبعــرض احلكــم علــى‬\n‫املدعــى عليــه قــرر اعتراضــه عليــه وطلــب اســتئنافه مــع تقــدمي الئحــة‬\n‫اعتراضيــة فســلم لــه صــورة مــن صــك احلكــم يف هــذه اجللســة بتاريــخ‬\n\n\n                                                                                       ‫‪104‬‬\n\f      ‫‪1434/7/25‬ه ـ وأفهمنــاه بــأن لــه مــدة أقصاهــا ثالثــون يومــا مــن تاريــخ‬\n      ‫اســتالمه لصــورة الصــك فــإذا انقضــت املــدة ولــم يقــدم اعتراضــه‬\n      ‫فيســقط حقــه يف االعتــراض وســيتم رفــع كامــل املعاملــة إلــى مقــام‬\n      ‫محكمــة االســتئناف املوقــرة لدراســة احلكــم وتدقيقــه حســب املتبــع‬\n      ‫ففهــم ذلــك ولــم جنــد حاجــة لعــرض احلكــم علــى املدعــي العــام ألنــه‬\n      ‫حكــم لــه بــكل طلباتــه بنــاء علــى املــادة (‪ )174‬مــن نظــام املرافعــات‬\n      ‫الشــرعية ولوائحــه التنفيذيــة واختتمــت اجللســة يف متــام الســاعة احلاديــة‬\n      ‫عشــرة وللبيــان حــرر يف ‪1434/7/25‬ه ـ وصلــى اهلل وســلم علــى نبينــا‬\n      ‫محمــد‪ .‬احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪،‬‬\n                                                                               ‫وبعد ‪-:‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلماســية الثانيــة‬\n      ‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بتبــوك برقــم‪341175324‬‬\n      ‫وتاريــخ ‪1434/9/1‬ه ـ املرفــق بهــا الصــك رقــم ‪ 34279643‬وتاريــخ‬\n      ‫‪1434/7/25‬ه ـ الصــادر مــن أصحــاب الفضيلــة القضــاة باحملكمــة‬\n      ‫العامــة بتبــوك الشــيخ‪ ...... /‬والشــيخ‪ ...... /‬والشــيخ‪ ...... /‬املتضمــن‬\n      ‫دعــوى املدعــي العــام ضــد‪ ...... /‬املتهــم بتهريــب كميــة مــن حبــوب‬\n      ‫األمفيتامــن املنبــه للجهــاز العصبــي احملظــورة البالــغ عددهــا مائتــن‬\n      ‫وتســعة آالف ومائــة وعشــر حبــات ‪ ،‬احملكــوم فيــه بقتــل املدعــى عليــه‬\n      ‫تعزيــر ًا و مصــادرة ســيارته وجوالــه‪ .‬وبدراســة احلكــم وصــورة ضبطــه‬\n      ‫والئحتــه االعتراضيــة تقــرر باالكثريــة املوافقــة علــى احلكــم ‪ .‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪،،،‬‬\n\n\n\n‫‪105‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":94,"source_page_end":105,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3daeb0466fcd1676ae7184e3c2b36247da4bb56ad8e84c6517307069eca3a333","normalized_text_hash":"91802c4ec4fb5f0ea2325c89e234c8d6fd0d0342bfeaecfdee6bc77aaa3e8fd0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p94-34279643"},{"id":"45c41e35-34cc-5678-b02d-29e4fc534494","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -االشتراك يف تهريب القات -تعاطي القات -اإلقرار باملشاركة يف نقل القات وتعاطيه -تعزير بالسجن واجللد ومصادرة اجلواالت -صرف النظر عن طلب املدعي العام مصادرة السيارة املستخدمة يف اجلرمية.","document_number":"34280698","case_number":"34265411","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/26","year":"1434","subject":"مخدرات -االشتراك يف تهريب القات -تعاطي القات -اإلقرار باملشاركة يف نقل القات وتعاطيه -تعزير بالسجن واجللد ومصادرة اجلواالت -صرف النظر عن طلب املدعي العام مصادرة السيارة املستخدمة يف اجلرمية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34280698 :‬تاريخه‪1434/7/26 :‬هـ‬\n                   ‫رقم الدعوى‪34265411 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34324713‬تاريخه‪1434/9/23 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬االشــتراك يف تهريــب القــات‪ -‬تعاطــي القــات‪ -‬اإلقــرار‬\n‫باملشــاركة يف نقــل القــات وتعاطيــه ‪ -‬تعزيــر بالســجن واجللــد‬\n‫ومصــادرة اجلــواالت‪ -‬صــرف النظــر عــن طلــب املدعــي العــام مصــادرة‬\n                                     ‫الســيارة املســتخدمة يف اجلرميــة‪.‬‬\n\n\n\n\n                        ‫‪ -‬األمر امللكي رقم ‪ 59633‬وتاريخ ‪1432/12/9‬هـ‬\n‫‪ -‬املــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬الصــادر يف ســنة‬\n                                                                    ‫‪1374‬ه ـ‬\n‫‪ -‬املــادة الثالثــة مــن قــرار ســمو وزيــر الداخليــة رقــم ‪ 2057‬وتاريــخ‬\n                                                             ‫‪1404/5/26‬هـ‬\n\n\n\n\n‫انتهــى التحقيــق مــع املدعــى عليهمــا إلــى توجيــه االتهــام إليهمــا‬\n‫باالشــتراك بنقــل (‪ )212‬حزمــة مــن القــات املخــدر بلــغ وزنهــا جميع ـ ًا‬\n‫تســعة وأربعــون كيلــو وثــاث مئــة وســتة وتســعون جــرام مــن نبــات‬\n‫القــات املخــدر‪ ،‬واســتخدام املدعــى عليــه الثانــي للقــات املخــدر‪ ،‬وذلــك‬\n‫بعــد ورود بــاغ للجهــة املختصــة يفيــد أن هنــاك شــخصني يقومــان‬\n‫بنقــل كميــة مــن القــات املخــدر وأن املدعــى عليــه الثانــي يقــوم مبســح‬\n\n                                                                                 ‫‪106‬‬\n\f      ‫الطريــق للمدعــى عليــه األول فتــم القبــض علــى املدعــى عليــه الثانــي‬\n      ‫وبتفتيشــه لوحــظ عليــه االرتبــاك وأنكــر معرفتــه بــاألول‪ ،‬ثــم مت القبــض علــى‬\n      ‫املدعــى عليــه األول وبتفتيــش الســيارة عثــر بداخلهــا علــى احلــزم املذكــورة ‪،‬‬\n      ‫أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة ملــادة نبــات القــات‬\n      ‫املخــدر ‪،‬طلــب املدعــي احلكــم عليهمــا بعقوبــة تعزيريــة ومعاقبــة الثانــي‬\n      ‫لقــاء اســتخدامه القــات املخــدر ومصــادرة جــواالت املدعــى عليهمــا‪،‬‬\n      ‫ومصــادرة الســيارة املســتخدمة يف اجلــرمي والعائــدة ملكيتهــا للمدعــى‬\n      ‫عليــه الثانــي ‪،‬وصــادق املدعــى عليهمــا علــى مــا هــو منســوب إليهمــا‪،‬‬\n      ‫وبنــاء علــى مــا تقــدم حكمــت احملكمــة بصــرف النظــر عــن طلــب‬\n      ‫املدعــي العــام مبطالبتــه مبصــادرة الســيارة وســجن املدعــى عليــه األول‬\n      ‫ثمانيــة أشــهر مــن دخولــه الســجن وجلــده خمســن جلــدة تكــرر عليــه‬\n      ‫ثــاث مــرات وســجن املدعــى عليــه الثانــي ســنة وجلــده خمســن جلــده‬\n      ‫تكــرر عليــه أربــع مــرات وذلــك لقــاء اشــتراكهما يف نقــل نبــات القــات‬\n      ‫املخــدر ويدخــل يف ذلــك مجــازاة املدعــى عليــه الثانــي علــى تعاطــي نوعهــا‬\n      ‫ومصــادرة جــواالت املدعــى عليهــم ‪،‬وبعــرض احلكــم علــى املدعــى‬\n      ‫عليهمــا قــررا القناعــة باحلكــم كمــا قــرر املدعــي العــام اعتراضــه علــى‬\n      ‫احلكــم وطلــب رفعهــا حملكمــة االســتئناف بالئحــة اعتراضيــه‪ ،‬وبعــد‬\n                       ‫رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬مســاعد رئيــس احملكمــة العامــة‬\n      ‫مبحافظــة اخلرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة اخلرمــة برقــم ‪ 34265411‬وتاريــخ‬\n‫‪107‬‬\n\f‫‪1434/06/10‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341395241‬وتاريــخ‬\n‫‪1434/6/10‬ه ـ ففــي يــوم االثنــن املوافق‪1434/07/17‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 08 : 00‬وفيهــا حضــر املدعــي العــام بدائــرة هيئــة‬\n‫التحقيــق واالدعــاء العــام مبحافظــة اخلرمــة‪ ....../‬مبوجــب خطــاب‬\n‫التكليــف رقــم ‪ ......‬يف‪1434/1/11‬ه ـ وقــدم دعــواه اخلطيــة قائــا فيهــا‬\n‫بصفتــي عضــو هيئــة التحقيــق واالدعــاء العــام بدائــرة محافظــة اخلرمــة‬\n‫أدعــي علــى‪1/‬ـ ‪ 39 ......‬عام ـ ًا ‪ ،‬ســعودي اجلنســية ‪ ،‬مبوجــب الســجل‬\n‫املدنــي رقــم (‪ ) ......‬متــزوج ‪ ،‬متعلــم ‪ ،‬عســكري ‪ ،‬موقــوف بســجن‬\n‫محافظــة اخلرمــة مبوجــب أمــر التوقيــف رقــم (‪ ......‬س) بتاريــخ‬\n‫‪1434/4/1‬هـ ـ اســتنادا للقــرار الــوزاري رقــم (‪ )1900‬يف‪1428/7/9‬ه ـ‬\n‫املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‪2 .‬ـ ‪28 ......‬‬\n‫عامـاً‪ ،‬ســعودي اجلنســية‪ ،‬مبوجــب الســجل املدنــي رقــم (‪ ) ......‬متســبب‪،‬‬\n‫متــزوج ‪،‬موقــوف بســجن محافظــة اخلرمــة مبوجــب أمــر التوقيــف رقــم‬\n‫(‪ )......‬بتاريــخ ‪1434/4/1‬هـ ـ اســتنادا للقــرار الــوزاري رقــم (‪ )1900‬يف‬\n‫‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‪.‬‬\n‫إنــه بتاريــخ ‪1434/3/27‬ه ـ ورد خطــاب مكافحــة املخــدرات رنيــة رقــم‬\n‫‪ ......‬يف ‪1434/3/27‬ه ـ إلــى وحــدة مكافحــة املخــدرات مبحافظــة‬\n‫اخلرمــة تفيــد أن هنــاك شــخصني يقومــون بنقــل كميــة مــن القــات‬\n‫املخــدر مــن املنطقــة اجلنوبيــة مــرور ًا مبحافظــة رنيــة ـ ـ اخلرمــة وأن املدعى‬\n‫عليــه الثانــي يقــوم مبســح الطريــق للمدعــى عليــه األول ومت القبــض علــى‬\n‫املدعــى عليــه الثانــي وبتفتيشــه لوحــظ عليــه االرتبــاك وأنكــر معرفتــه‬\n‫بــاألول ومت تشــكيل فرقــة ميدانيــة واالنتقــال للخــط الســريع املــؤدي‬\n‫حملافظــة رنيــة اخلرمــة وجــرى عمــل عــدة كمائــن متفرقــة وعنــد‬\n\n\n                                                                                        ‫‪108‬‬\n\f      ‫اســتيقاف إحــدى الســيارات القادمــة مــن جهــة محافظــة رنيــة وهــي مــن‬\n      ‫نــوع موديــل (‪ )2011‬لوحــة رقــم ‪ ......‬بيضــاء اللــون بداخلهــا شــخص‬\n      ‫وبرفقتــه امــرأة وبطلــب إثباتــه ظهــرت عليــه عالمــات االرتبــاك وأفــاد‬\n      ‫انــه يدعــى ‪ ......‬وبطلــب إثبــات العائلــة اتضــح أنــه يدعــى ‪ ......‬وبرفقتــه‬\n      ‫املواطنــة ‪ ......‬واتضــح إن املــرأة هــي زوجتــه كمــا يتضــح مــن كــرت‬\n      ‫العائلــة وبتفتيــش الســيارة وجــد بداخلهــا وحتديــد ًا داخــل األبــواب‬\n      ‫األربعــة‪ ،‬وداخــل املقعــد اخللفــي وداخــل ديكــور القيــر والطبلــون ‪ ،‬عثــر‬\n      ‫علــى عــدد (‪ )212‬حزمــة مــن نبــات القــات املخــدر بلــغ وزنهــا اإلجمالــي‬\n      ‫‪49,396‬كجــم تســعه وأربعــون كيلــو وثــاث مئــة وســتة وتســعون جــرام‬\n      ‫مــن نبــات القــات املخــدر‪ ،‬وقــد اثبــت التقريــر الكيميائــي الشــرعي‬\n      ‫رقــم (‪ )......‬بتاريــخ ‪1434/4/23‬ه ـ إيجابيــة العينــة مبــا مت ضبطــه مــع‬\n      ‫املدعــى عليــه األول ملــادة نبــات القــات املخــدر وهــي مــن املــواد املدرجــة‬\n      ‫بجــدول املــواد املخــدرة امللحقــة بنظــام مكافحــة املخــدرات املرفقــة‬\n      ‫بالتعميــم البرقــي لصاحــب الســمو امللكــي وزيــر الداخليــة رقــم‬\n      ‫(‪)89400/19‬يف ‪1426/10/25‬ه ــ‪ .‬وبســماع أقــوال املدعى عليه األول‪/‬‬\n      ‫اقــر أنــه اتفــق مــع املدعــي عليــه الثانــي بنقــل كميــة القــات املخــدر إلــى‬\n      ‫الريــاض مقابــل مبلــغ مالــي قــدرة عشــرة اآللــف ريــال‪ .‬وبســماع أقــوال‬\n      ‫املدعــى عليــه الثانــي‪ /‬اقــر أن القــات الــذي مت ضبطــه يعــود لــه وقــد قــام‬\n      ‫بإخفائــه بســيارته وإعطائهــا للمدعــي عليــه األول لتوصيلهــا مقابــل‬\n      ‫عشــرة أالف ريــال وإنــه يقــوم مبتابعتهــم ومســح الطريــق علــى ســيارة‬\n      ‫أخــرى‪ .‬وقــد انتهــى التحقيــق معهما إلى توجيه االتهام إليهما باالشــتراك‬\n      ‫بنقــل (‪ )212‬حزمــة مــن القــات املخــدر بلــغ وزنهــا جميعاً(‪ )49,396‬تســعة‬\n      ‫وأربعــون كيلــو وثــاث مئــة وســتة وتســعون جــرام مــن نبــات القــات‬\n\n\n‫‪109‬‬\n\f‫املخــدر‪ ،‬واســتخدام املدعــى عليــه الثانــي للقــات املخــدر وذلــك لألدلــة‬\n‫والقرائــن التاليــة‪ -1/‬مــا ورد بإقرارهمــا املصــدق شــرعا املنــوه عنــه‬\n‫مبلــف التحقيــق صفحــة رقــم (‪ )20‬لفــه رقــم (‪ )1‬وصفحــة رقــم (‪)8 ،7‬‬\n‫لفــه رقــم (‪-2 .)2‬التقريــر الكيميائــي الشــرعي رقــم (‪ ......‬بتاريــخ‬\n‫‪1434/4/23‬ه ـ لفــه (‪ -3 .)36‬شــهادة الشــهود الــواردة يف محضــر‬\n‫القبــض املــدون مبلــف التحقيــق صفحــة رقــم (‪ )11،12،13‬لفــه (‪.)1‬‬\n‫وباالطــاع علــى ســوابقهما لــم يعثــر للمدعــى عليــه األول علــى ســوابق‬\n‫وعثــر علــى املدعــى عليــه الثانــي علــى ســابقة حيــازة قــات لــذا اطلــب‬\n‫اثبــات مــا أســند إليهمــا واحلكــم عليهــم باالتــي ‪ -1 /‬إثبــات إدانتهمــا‬\n‫باالشــتراك بنقــل مــا وزنــه (‪ ) 49,396‬جــرام مــن نبــات القــات احملظــور‬\n‫واحلكــم عليهمــا بعقوبــة تعزيريــة وفقـ ًا للمــادة الرابعــة مــن قــرار مجلــس‬\n‫الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ اســتناد ًا لألمــر الســامي الكــرمي رقــم‬\n‫(‪ )59633‬يف ‪1432/12/9‬ه ـ ومعاقبــة الثانــي بعقوبــة تعزيريــة لقــاء‬\n‫اســتخدامه القــات املخــدر‪ -2‬مصــادرة جــوال املدعــي عليــة األول رقــم‬\n‫(‪ ) ......‬يحمــل الرقــم التسلســلي ‪ ) ......‬ومصــادرة جــوال املدعــي عليــة‬\n‫الثانــي رقــم ( ‪ ) ......‬يحمــل الرقــم التسلســلي (‪ ) ......‬وكذلــك جوالــه‬\n‫الثانــي رقــم (‪ ) ......‬يحمــل الرقــم التسلســلي رقــم (‪ -3 .) ......‬مصــادرة‬\n‫الســيارة املســتخدمة يف اجلرميــة وهــي مــن نــوع ‪ .....‬موديــل (‪ )2011‬لوحــة‬\n‫رقــم (‪ ) ......‬ابيــض اللــون والعائــد ملكيتهــا للمدعــى عليــة الثانــي ‪.‬هــذه‬\n‫دعــواي‪ .‬وبســؤال املدعــى عليــه األول عمــا ورد يف دعــوى املدعــي العــام‬\n‫ا مــا ذكــره املدعــي العــام يف دعــواه مــن اتفاقــي مــع املدعــى‬  ‫أجــاب قائـ ً‬\n‫عليــه الثانــي علــى نقــل كميــة القــات املذكــور يف الدعــوى علــى ســيارته‬\n‫وكونــي علــى علــم بذلــك وذلــك مقابــل مبلــغ مالــي وقــدره عشــرة اآلف‬\n\n\n                                                                                       ‫‪110‬‬\n\f      ‫ريــال فهــذا كلــه صحيــح هكــذا أجــاب‪ .‬كمــا جــرى ســؤال املدعــى‬\n      ‫ا مــا ذكــره املدعــي العــام يف دعــواه مــن‬   ‫عليــه الثانــي فأجــاب قائ ـ ً‬\n      ‫اشــتراكي بنقــل كميــة القــات املذكــورة يف الدعــوى فهــذا كلــه‬\n      ‫صحيــح فقــد قمــت بإخفائــه بســيارتي وإعطائــه للمدعــى عليــه األول‬\n      ‫لتوصيلــه إلــى منطقــة الريــاض مقابــل مبلــغ مالــي وقــدره عشــرة اآلف‬\n      ‫ريــال وأنــا أقــوم مبتابعتــه ومســح الطريــق لــه علــى ســيارة أخــرى هكــذا‬\n      ‫أجــاب‪ .‬ثــم جــرى االطــاع علــى أوراق املعاملــة فوجــدت إقــرار املدعــى‬\n      ‫عليــه حتقيقــا علــى اللفــة(‪ )1‬صفحــة رقــم(‪ )19-18‬مــن ملــف التحقيــق‬\n      ‫املتضمــن إقــرار املدعــى عليــه االول بنقــل (‪ )212‬مائتــن واثنــا عشــر‬\n      ‫حزمــة قــات بلــغ وزنهــا (‪ )49.396‬كجــم تســعة وأربعــون كيلــو‬\n      ‫وثالثمائــة وســتة وتســعون جرام ـ ًا مــن نبــات أخضــر اللــون يشــتبه أن‬\n      ‫يكــون مــن نبــات القــات املخــدر وهــي عائــدة للمدعــى عليــه الثانــي‬\n      ‫كمــا جــرى االطــاع علــى إقــرار املدعــى عليــه الثانــي حتقيق ـ ًا علــى‬\n      ‫اللفــة(‪ )2‬صفحــة رقــم (‪ )6-5‬املتضمــن إقــرار املدعــى عليــه الثانــي بورود‬\n      ‫اتصــال إليــه مــن املدعــو ‪ ......‬يف مدينــة الريــاض بحضــور شــخص إلــى‬\n      ‫منزلــه معــه كميــة مــن القــات املخــدر وطلــب منــه إخفائهــا يف ســيارته‬\n      ‫وإيصالهــا إلــى مدينــة الريــاض مببلــغ مــادي وهــو عشــرة اآلف ريــال‬\n      ‫للســائق الــذي يقــوم بنقــل الكميــة وعشــرة ريــاالت للقــرف (احلزمــة)‬\n      ‫الواحــدة بينــه وبــن املتصــل ثــم قــام باالتفــاق مــع املدعــى عليــه األول‬\n      ‫بإيصالهــا كمــا وجــدت التقريــر الكيميائــي الشــرعي رقــم (‪)......‬‬\n      ‫يف‪1434/4/23‬ه ـ علــى اللفــة (‪ )36‬املتضمــن ايجابيــة العينــة املضبوطــة‬\n      ‫مــع املدعــى عليــه ملــادة نبــات القــات املخــدر كمــا جــرى االطــاع علــى‬\n      ‫ســوابق املدعــى عليهمــا ولــم يعثــر للمدعــى عليــه األول علــى ســوابق وعثر‬\n\n\n‫‪111‬‬\n\f‫للمدعــى عليــه الثانــي علــى ســابقة حيــازة قــات‪ .‬فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة وإلقــرار املدعــى عليــه األول بنقــل كميــة القــات‬\n‫املخــدر إلــى مدينــة الريــاض مقابــل مبلــغ مالــي وقــدره عشــرة اآلف‬\n‫وإقــرار املدعــى عليــه الثانــي باشــتراكه بنقــل القــات التــي مت ضبطهــا‬\n‫مــع املدعــى عليــه األول وقيامــه بإخفائــه بســيارته وإعطائــه للمدعــى‬\n‫عليــه األول لتوصيلــه إلــى منطقــة الريــاض مقابــل مبلــغ مالــي وقــدره‬\n‫عشــرة اآلف ريــال وقيامــه مبتابعتــه ومراقبــة الطريــق لــه علــى ســيارة‬\n‫أخــرى وملــا ورد يف الدعــوى ونظــرا ملــا تضمنــه التقريريــن الكيميائيــن‬\n‫الشــرعيني املشــار إليهمــا أعــاه ونظــرا ألن املدعــى عليهمــا يســتحقان‬\n‫العقوبــة طبق ـ ًا للقواعــد الشــرعية واألنظمــة املرعيــة وملــا قــرره املدعــى‬\n‫عليهمــا واســتنادا لألمــر امللكــي رقــم ‪ 59633‬وتاريــخ ‪1432/12/9‬ه ـ‬\n‫املتضمــن املوافقــة علــى إخــراج نبــات القــات مــن العقوبــات املنصــوص‬\n‫عليهــا يف نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واالســتمرار يف‬\n‫معاملتــه وفــق العقوبــات الســائدة قبــل الشــروع يف تطبيــق النظــام‬\n‫واســتناد ًا للمــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬الصــادر يف‬\n‫ســنة ‪1374‬ه ـ واملــادة الثالثــة مــن قــرار ســمو وزيــر الداخليــة رقــم ‪2057‬‬\n‫وتاريــخ ‪1404/5/26‬ه ـ وحيــث ال ســوابق لــدى املدعــى عليــه االول وملــا‬\n‫يفهــم مــن منطــوق االمــر امللكــي املتضمــن اخــراج نبــات القــات مــن نظام‬\n‫مكافحــة املخــدرات ان املقصــود عــدم مســاواتها بالعقوبــات املقــررة‬\n‫علــى جرائــم املخــدرات والتوجــه الــى مــا هــو اقــل منهــا وملــا ظهــر لــي مــن‬\n‫نــدم املدعــى عليهمــا وظهــور عالمــات التوبــة عليهمــا وحيــث لــم ينــص يف‬\n‫العقوبــات الســائدة قبــل تطبيــق نظــام املخــدرات الــذي جــرى الرجــوع‬\n‫الــى العمــل بــه حاليــا علــى مصــادرة وســائل النقــل ولكــون املقصــود مــن‬\n\n\n                                                                                         ‫‪112‬‬\n\f      ‫العقوبــة الــردع وليــس التشــفي لذلــك كلــه فقــد ثبــت لــدي إدانــة املدعــى‬\n      ‫عليهمــا باالشــتراك يف نقــل مــا وزنــه (‪49.396‬كجــم) تســعة وأربعــون‬\n      ‫كيلــو وثالثمائــة وســتة وتســعون جرام ـ ًا نبــات القــات املخــدر وذلــك‬\n      ‫بقيــام املدعــى عليــه الثانــي ‪ ......‬بإخفــاء الكميــة املهربــة داخــل ســيارته‬\n      ‫وتســليمها لــأول وقيامــه مبراقبــة الطريــق لــه علــى ســيارة أخــرى وقيــام‬\n      ‫املدعــى عليــه األول بقيــادة الســيارة التــي فيهــا الكميــة وهــو علــى علــم‬\n      ‫مبــا فيهــا وإدانــة املدعــى عليــه الثانــي بتعاطــي نوعهــا وقــررت مــا يلــي‪:‬‬\n      ‫أوالً‪ /‬صرفــت النظــر عــن طلــب املدعــي العــام مطالبتــه مبصــادرة‬\n      ‫الســيارة ‪ .‬ثاني ـ ًا ‪ /‬ســجن املدعــى عليــه االول ثمانيــة أشــهر مــن دخولــه‬\n      ‫الســجن وجلــده خمســن جلــدة تكــرر عليــه ثــاث مرات وســجن املدعى‬\n      ‫عليــه الثانــي ســنة وجلــده خمســن جلــدة تكــرر عليــه أربــع مــرات وذلــك‬\n      ‫لقــاء اشــتراكهما يف نقــل نبــات القــات املخــدر ويدخــل يف ذلــك مجــازاة‬\n      ‫املدعــى عليــه الثانــي علــى تعاطــي نوعهــا ثالثـاً‪ /‬مصــادرة جــوال املدعــى‬\n      ‫عليــه األول رقــم (‪ ) ......‬والــذي يحمــل الرقــم التسلســلي (‪ ) ......‬ومصادرة‬\n      ‫جــوال املدعــى عليــه الثانــي رقــم (‪ ( ......‬ويحمــل الرقــم التسلســلي (‪......‬‬\n      ‫) ‪ .‬ومبــا تقــدم حكمــت وبعــرض احلكــم علــى املدعــى عليهمــا قــرروا‬\n      ‫القناعــة باحلكــم كمــا قــرر املدعــي العــام اعتراضــه علــى احلكــم‬\n      ‫وطلــب رفعهــا حملكمــة االســتئناف بالئحــة اعتراضيــه فجــرى تســليمه‬\n      ‫نســخه مــن احلكــم لتقــدمي اعتراضــه خــال ثالثــن يــوم مــن هــذا التاريــخ‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد ختمــت اجللســة يف‬\n                                       ‫متام الساعة التاسعة حرر يف ‪71434/17‬هـ ـ ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة مبحكمــة االســتئناف‬\n\n\n‫‪113‬‬\n\f‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫القاضــي باحملكمــة العامــة باخلرمــة الشــيخ‪ ....../‬برقــم ‪342129456‬‬\n‫وتاريــخ ‪1434/9/6‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلتــه برقــم‬\n‫‪ 34280698‬وتاريــخ ‪1434/7/26‬ه ـ املتضمــن دعــوى املدعــي العــام‬\n‫ضــد‪ ....../‬ورفيقــه ‪ ،‬املتهمــن يف قضيــة قــات احملكــوم فيــه مبــا دون‬\n‫باطــن القــرار ‪.‬وبدراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة‬\n‫تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                          ‫وعلــى آلــه وصحبــه وســلم ‪،،،،،‬‬\n\n\n\n\n                                                                                   ‫‪114‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":106,"source_page_end":114,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0f88eada51e3e4735f2c59a8f36c13060b1f5bddb6859c162e5d6a9cfa63b7e0","normalized_text_hash":"5e0e3cdc4f8e1223762f562404c7cd93f706fee2e22b8bffa38bada3c7181952","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p106-34280698"},{"id":"f9d8aac6-e471-53b5-8c22-cf0d4598734e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -قات -تهريب قات بقصد االستعمال الشخصي -اإلقرار بالتهريب -قلة الكمية املضبوطة -حداثة سنه -ظروف مخففة للعقوبة -تعزير بالسجن واجللد واملنع من السفر املادة (األولى) الفقرة) ب) واملادة (اخلامسة) الفقرة (ب-ج) من قرار مجلس الوزراء رقم ( )11لعام 1374ه","document_number":"34275215","case_number":"34308056","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/22","year":"1434","subject":"مخدرات -قات -تهريب قات بقصد االستعمال الشخصي -اإلقرار بالتهريب -قلة الكمية املضبوطة -حداثة سنه -ظروف مخففة للعقوبة -تعزير بالسجن واجللد واملنع من السفر املادة (األولى) الفقرة) ب) واملادة (اخلامسة) الفقرة (ب-ج) من قرار مجلس الوزراء رقم ( )11لعام 1374ه","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34275215 :‬تاريخه‪1434/7/22 :‬هـ‬\n                         ‫رقم الدعوى‪34308056 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34318448‬تاريخه ‪1434/9/14 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬قــات ‪ -‬تهريــب قــات بقصــد االســتعمال الشــخصي‪ -‬اإلقــرار‬\n      ‫بالتهريــب ‪ -‬قلــة الكميــة املضبوطــة ‪ -‬حداثــة ســنه ‪ -‬ظــروف مخففــة‬\n                      ‫للعقوبــة ‪ -‬تعزيــر بالســجن واجللــد واملنــع مــن الســفر‬\n\n\n\n\n      ‫املــادة (األولــى) الفقــرة) ب) واملــادة (اخلامســة) الفقــرة (ب‪-‬ج) مــن قــرار‬\n                                        ‫مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه قيامــه بتهريــب تســعة وعشــرين‬\n      ‫جراما وتســعة أعشــار اجلرام من نبات القات املخدر بقصد االســتخدام‬\n      ‫الشــخصي وطلــب احلكــم علــى املدعــى عليــه بعقوبــة تعزيريــة ومنعــه‬\n      ‫مــن الســفر مبوجــب قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ‬\n      ‫وذلــك أثــر القبــض علــى املدعــى عليــه وتفتيــش ســيارته عثــر بداخــل‬\n      ‫شــنطتها كميــة يشــتبه أن تكــون مــن نبــات القــات ‪ -‬أثبــت التقريــر‬\n      ‫الكيميائــي الشــرعي الصــادر إيجابيــة العينــة لنبــات القــات املخــدر‬\n      ‫ا ‪،‬وحيــث‬  ‫صــادق املدعــى عليــه علــى دعــوى املدعــي العــام جملــة وتفصيـ ً‬\n      ‫إن الكميــة املضبوطــة مــع املدعــى عليــه قليلــة جــدا‪ ،‬وقــد أبــدى أســفه‬\n      ‫وندمــه علــى ذلــك‪ ،‬وحلداثــة ســنه واســتصالح ًا حلالــه‪ ،‬فقــد مت احلكــم‬\n\n‫‪115‬‬\n\f‫بتعزيــره بســجنه ملــدة شــهرين وجلــده أربعــن جلــدة دفعــة واحــدة ومنعــه‬\n‫مــن الســفر خــارج البــاد ملــدة ســنة واحــدة تبــدأ بعــد انتهــاء مــدة تنفيــذ‬\n‫عقوبــة الســجن وبعــرض احلكــم علــى املدعــى عليــه قــرر اعتراضــه علــى‬\n‫احلكــم بالئحــة اعتراضيــة وقــرر املدعــي العــام اعتراضــه علــى احلكــم‬\n             ‫بــدون الئحــة‪ ،‬صدقــت محكمــة االســتئناف علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بنجــران برقــم ‪ 34308056‬وتاريــخ ‪ 1434/07/04‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 341612700‬وتاريــخ ‪ 1434/7/4‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق‪ 1434/07/22‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 15‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ ......‬مبوجــب التكليــف الصــادر مــن هيئــة‬\n‫التحقيــق واالدعــاء العــام بنجــران رقــم ‪ ......‬بتاريــخ ‪1430/12/29‬ه ـ‬\n‫وادعــى علــى احلاضــر معــه يف مجلــس احلكــم ‪ ......‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ......‬قائــا يف دعــواه عليــه بتهريــب (‪)29,9‬‬\n‫تســعة وعشــرين جــرام وتســعة أعشــار اجلــرام مــن نبــات القــات املخــدر‬\n‫بقصــد االســتخدام الشــخصي‪ 0‬حيــث ورد مبحضــر القبــض والتفتيــش‬\n‫املعــد مــن قبــل منفــذ جمــرك اخلضــراء بنجــران رقــم (‪ )12‬أنــه بتاريــخ‬\n‫‪1434/6/8‬ه ـ قــدم مــن اليمــن ســيارة نــوع ‪ ........‬رقــم اللوحــة ‪ ......‬بقيــادة‬\n‫املهتــم أعــاه‪ ...... /‬وترافقــه والدتــه‪ ...... /‬وعنــد تفتيشــها عثــر بداخــل‬\n‫شــنطتها كميــة يشــتبه أن تكــون مــن نبــات القــات بلــغ وزنــه (‪)29,9‬‬\n‫جــرام ولــم تصــرح عنهــا (أخلــى ســبيلها يف احلــال لعــدم عالقتهــا مبــا‬\n\n                                                                                       ‫‪116‬‬\n\f      ‫ضبــط) ‪ ،‬فتــم تســليم املذكــور ومــا ضبط معه إلى مكافحة املخدرات‬\n      ‫بنجــران إلكمــال الــازم‪ .‬وبعــد انتهــاء التحقيــق معــه ُأطلــق ســراحه‬\n      ‫بالكفالــة احلضوريــة املرفقــة بــاألوراق اســتناد ًا للمــادة (‪ )120‬مــن نظــام‬\n      ‫اإلجــراءات اجلزائيــة ‪،‬وبســماع اقــوال املواطنــة‪ ...... /‬لــم تفــد التحقيــق‬\n      ‫بشــئ‪ 0‬وبســماع أقــوال املتهــم (‪ : ) ......‬أقــر بــأن القــات املضبــوط يف‬\n      ‫شــنطة والدتــه عائــد لــه شــخصي ًا وأنــه يســتخدم القــات ‪ 0‬وباســتجوابه‪:‬‬\n      ‫لــم يفــد التحقيــق بشــئ‪0‬وأثبت التقريــر الكيميائــي الشــرعي الصــادر‬\n      ‫مــن مركــز الســموم والكيميــاء الطبيــة الشــرعية مبنطقــة مكــة‬\n      ‫املكرمــة رقــم‪ ......‬أن العينــة املضبوطــة واملرســلة للتحليــل بخطــاب‬\n      ‫جمــرك اخلضــراء رقــم‪ ......‬ثبــت أنهــا لنبــات القــات املخــدر‪ ،‬والقــات‬\n      ‫مــن املــواد املدرجــة يف اجلــدول رقــم (‪ 4‬فئــة د) املرفقــة بنظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي الكــرمي رقــم‬\n      ‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬هـ ـ وقــد انتهــى التحقيــق بتوجيــه االتهــام‬\n      ‫إلــى‪ ....../‬ـ بتهريــب (‪ )29,9‬تســعة وعشــرين جــرام وتســعة أعشــار اجلــرام‬\n      ‫ا‬\n      ‫مــن نبــات القــات املخــدر بقصــد االســتخدام الشــخصي‪ ،‬ممــا يعــد فعـ ً‬\n      ‫مجرم ـ ًا اســتناد ًا للفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n                       ‫وتاريــخ ‪ 1426/7/8‬ه ـ وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n      ‫‪-1‬إعترافــه لــدى جهــة الضبــط املنــوه واملــدون علــى ص (‪ 1‬و ‪ )3‬مــن دفتــر‬\n                                                            ‫االســتدالل املرفــق لفه (‪)1‬‬\n      ‫‪-2‬محضــر القبــض والتفتيــش املنــوه عنــه واملرفــق علــى اللفــات (‪ 7‬و ‪8‬‬\n                                                                                        ‫و ‪)9‬‬\n      ‫‪-3‬التقريــر الكيميائــي الشــرعي املنــوه عنــه واملرفــق لفــه (‪. )36‬وحيــث‬\n\n\n‫‪117‬‬\n\f‫إن مــا أقــدم عليــه املتهــم‪ ...... /‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل‬\n‫مخالــف ومعاقــب عليــه نظامـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n‫لعــام ‪1374‬ه ـ لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n                                                                              ‫باآلتــي‪:‬‬\n‫‪-1‬تعزيــره شــرع ًا يف ضــوء املــادة (األولــى) الفقــرة (ب) مــن القــرار‬\n                                                ‫الــوزاري املشــار إليــه أعــاه ‪.‬‬\n‫‪-2‬منعــه مــن الســفر بعــد تنفيــذ محكوميتــه اســتناد ًا للفقــرة (د) مــن‬\n‫ذات املــادة ‪ .‬هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه وســؤاله‬\n‫ا مــا ذكــره املدعــي العــام يف دعــواه صحيــح كلــه‬       ‫اجلــواب أجــاب قائ ـ ً‬\n‫ا فقــد قمــت بتهريــب (‪ )29,9‬تســعة وعشــرين جــرام‬               ‫جملــة وتفصي ـ ً‬\n‫وتســعة أعشــار اجلــرام مــن نبــات القــات املخــدر بقصــد االســتخدام‬\n‫الشــخصي عــن طريــق منفــذ اخلضــراء وهــي عبــارة عــن بقايــا أعــواد‬\n‫قــات اســتعملته أثنــاء وجــودي يف اليمــن وقــد تبــت إلــى اهلل وندمــت علــى‬\n‫مــا فعلــت وليــس علـ ّـي ســوابق هــذه إجابتــي ‪.‬أ‪.‬ه ـ وبعــد ســماع الدعــوى‬\n‫واإلجابــة جــرى االطــاع علــى صــورة التقريــر الكيميائــي الشــرعي‬\n‫املشــار إليــه يف الدعــوى فوجــد يتضمــن ايجابيــة مــا ضبــط يف هــذه‬\n‫القضيــة للقــات‪ .‬أ‪.‬هــ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد‬\n‫االطــاع علــى وقائــع الدعــوى وأوراق املعاملــة ودراســتها ومبــا أن املدعــى‬\n‫ا فأقــر بتهريــب‬  ‫عليــه صــادق علــى دعــوى املدعــي العــام جملــة وتفصي ـ ً‬\n‫(‪ )29,9‬تســعة وعشــرين جــرام وتســعة أعشــار اجلــرام مــن نبــات القــات‬\n‫املخــدر بقصــد االســتخدام الشــخصي ‪ ،‬ومبــا أن كميــة مــا ضبــط مــع‬\n‫املدعــى عليــه قليــل جــدا‪ ،‬وقــد أبــدى املدعــى عليــه أســفه وندمــه علــى‬\n‫ذلــك‪ ،‬وحلداثــة ســن املدعــى عليــه واســتصالح ًا حلالــه‪ ،‬واســتناد ًا إلــى‬\n\n\n                                                                                          ‫‪118‬‬\n\f      ‫املــادة (األولــى) الفقــرة (ب) واملــادة (اخلامســة) الفقــرة (ب‪-‬ج) مــن قــرار‬\n      ‫مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ لــكل هــذه األســباب وتأسيسـ ًا‬\n      ‫علــى كل مــا تقــدم فقــد قــررت اآلتــي أوالً‪ :‬ثبــت لــدي إدانــة املدعــى‬\n      ‫عليــه بتهريــب (‪ )29,9‬تســعة وعشــرين جــرام وتســعة أعشــار اجلــرام مــن‬\n      ‫نبــات القــات املخــدر بقصــد االســتخدام الشــخصي‪ ،‬وقــررت تعزيــره‬\n      ‫لقــاء ذلــك بســجنه ملــدة شــهرين يحتســب منهــا مــا أمضــاه موقوفـ ًا علــى‬\n      ‫ذمــة هــذه القضيــة وجلــده أربعــن جلــدة دفعــة واحــدة‪ .‬ثانيـاً‪ :‬مينــع املدعــى‬\n      ‫عليــه مــن الســفر خــارج البــاد ملــدة ســنة واحــدة تبــدأ بعــد انتهــاء مــدة‬\n      ‫تنفيــذ عقوبــة الســجن املقــررة يف البنــد (أوالً)‪ .‬وبذلــك كلــه حكمــت‬\n      ‫وبعرضــه علــى املدعــى عليــه قــرر اعتراضــه علــى احلكــم بالئحــة‬\n      ‫اعتراضيــة لــذا واســتناد ًا إلــى املــواد (‪ )195-194‬مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة فســيتم تســليمه صــورة مــن احلكــم هــذا اليــوم وأفهــم أن مــدة‬\n      ‫االعتــراض ثالثــون يومـ ًا تبــدأ مــن يــوم غــد فــإذا مضــت املــدة ولــم يقــدم‬\n      ‫الالئحــة االعتراضيــة فــإن حقــه يف طلــب االســتئناف يســقط وترفــع‬\n      ‫املعاملــة حملكمــة االســتئناف دون الئحــة اعتراضيــة خــال خمســة‬\n      ‫وأربعــن يومـ ًا مــن تاريــخ النطــق باحلكــم ففهــم ذلــك وقــرر املدعــي العــام‬\n      ‫اعتراضــه علــى احلكــم بــدون الئحــة وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1434/7/22‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n      ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بنجــران برقــم‬\n      ‫‪ 341612700‬وتاريخ‪1434/8/9‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيل ــة القاضــي باحملكمــة الشــيخ ‪ ....../‬برقــم ‪ 34275215‬وتاريــخ‬\n\n\n‫‪119‬‬\n\f‫‪1434/7/22‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪ ...... /‬يف قضيــة‬\n‫(مخــدرات) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق‬\n                      ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n\n\n\n\n                                                                                   ‫‪120‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":115,"source_page_end":120,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e787fe01cba5608c2ad785eef9fc9ec4d81296a1440eb7cdc04dc8d6670dfb9f","normalized_text_hash":"c9e87572f535a17b734ddb24a8df029199e5cbc6996401621098de7100682867","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p115-34275215"}]$archive_payload$::jsonb) AS x LIMIT 25
